globalThis.__BOOKS_BUNDLE__ = {"schema": "books.bundle.v2", "catalog": {"schema": "books.catalog.v2", "kind": "book-catalog", "version": 2, "packages": [{"id": "arquitetura-memoria-cpp", "title": "Arquitetura de Memória, Compilação e Modelo de Objetos em C++", "description": "Do processador e assembly ao pré-processador, compilador, linker, ELF, memória virtual, modelo de objetos e Itanium ABI em C++.", "manifest": "packages/arquitetura-memoria-cpp/manifest.json", "cover": {"src": "packages/arquitetura-memoria-cpp/cover.jpg", "alt": "Capa técnica de arquitetura de memória, compilação e modelo de objetos em C++.", "ratio": "16:9"}, "tags": ["c++", "memória", "assembly", "ELF", "ABI", "sistemas"]}, {"id": "combinatoria-computacao", "title": "Combinatória: fundamentos, provas e aplicações em computação", "description": "Percurso completo da combinatória elementar à universitária avançada, com definições, fórmulas provadas passo a passo, recorrências, grafos, probabilidade, algoritmos, simetria e exercícios.", "tags": ["combinatória", "matemática discreta", "algoritmos", "grafos", "probabilidade", "provas"], "manifest": "packages/combinatoria-computacao/manifest.json", "cover": {"src": "packages/combinatoria-computacao/cover.jpg", "alt": "Capa abstrata com árvores, conjuntos e símbolos de contagem.", "ratio": "16:9"}}, {"id": "programacao-competitiva-cpp", "title": "Programação Competitiva em C++: do básico ao avançado", "description": "Curso completo e moderno de programação competitiva em C++, com algoritmos, estruturas de dados, matemática, grafos, strings, DP e engenharia de contest.", "manifest": "packages/programacao-competitiva-cpp/manifest.json", "cover": {"src": "packages/programacao-competitiva-cpp/cover.svg", "alt": "Capa abstrata com uma grade de nós, arestas e símbolos de código.", "ratio": "16:9"}, "tags": ["c++", "programação competitiva", "algoritmos", "estruturas de dados", "ICPC", "CSES"]}, {"id": "fisica-eletrica-engenharia-embarcada", "title": "Física Elétrica: da Eletrostática à Engenharia de Sistemas Embarcados", "description": "Livro completo sobre eletricidade, eletromagnetismo, circuitos, semicondutores, eletrônica, sistemas embarcados, controle, DSP, instrumentação, confiabilidade e segurança.", "manifest": "packages/fisica-eletrica-engenharia-embarcada/manifest.json", "cover": {"src": "packages/fisica-eletrica-engenharia-embarcada/cover.svg", "alt": "Capa abstrata com campos elétricos, circuito e microcontrolador.", "ratio": "16:9"}, "tags": ["física", "eletricidade", "eletromagnetismo", "circuitos", "eletrônica", "sistemas embarcados"]}]}, "progress": {"schema": "books.progress.v2", "kind": "book-progress", "version": 2, "progress": {"arquitetura-memoria-cpp": {"percent": 0, "top": 0, "section": ""}}}, "settings": {}, "packages": {"arquitetura-memoria-cpp": {"manifest": {"schema": "books.package.v2", "kind": "book-package", "id": "arquitetura-memoria-cpp", "title": "Arquitetura de Memória, Compilação e Modelo de Objetos em C++", "description": "Do processador e assembly ao pré-processador, compilador, linker, ELF, memória virtual, modelo de objetos e Itanium ABI em C++.", "language": "pt-BR", "tags": ["c++", "memória", "assembly", "ELF", "ABI", "sistemas"], "header": "header.json", "sections": ["sections/fundamentos.json", "sections/visao-geral.json", "sections/toolchain.json", "sections/pipeline.json", "sections/regioes.json", "sections/objetos.json", "sections/modernizacoes.json", "sections/resumo.json", "sections/exercicios.json", "sections/glossario.json", "sections/referencias.json"]}, "header": {"schema": "books.header.v2", "kind": "book-header", "id": "arquitetura-memoria-cpp-header", "kicker": "referência técnica · C++ / sistemas", "title": "Arquitetura de Memória, Compilação e Modelo de Objetos em C++", "subtitle": "Da máquina e do código-fonte ao ELF, à memória virtual e ao despacho virtual", "guideTitle": "Como usar este guia", "guideText": "Comece pelos fundamentos de processadores e assembly. Em seguida acompanhe a toolchain, o espaço de endereçamento, as regiões de memória e o modelo de objetos C++.", "cover": {"src": "cover.jpg", "alt": "Capa escura com o título Arquitetura de Memória em C++ e linhas de regiões de memória.", "ratio": "16:9"}, "legend": [{"label": ".text", "color": "blue"}, {"label": ".rodata", "color": "teal"}, {"label": ".data", "color": "amber"}, {"label": ".bss", "color": "gray"}, {"label": "stack", "color": "violet"}, {"label": "heap", "color": "orange"}, {"label": "modelo de objetos", "color": "pink"}], "footer": "Referência didática baseada em C++ portátil e em exemplos explicitamente rotulados como Linux x86-64 / System V AMD64 / GCC-Clang."}, "sections": [{"schema": "books.section.v2", "kind": "book-section", "id": "fundamentos", "number": "1", "title": "Antes da memória: processador, ISA e assembly", "blocks": [{"type": "paragraph", "lead": true, "text": "Antes de seguir um ponteiro pela memória, precisamos entender quem o segue: o processador. Este capítulo constrói a ponte entre a máquina abstrata do C++ e uma implementação concreta Linux x86-64, separando cuidadosamente o que é garantia da linguagem do que é convenção de arquitetura."}, {"type": "callout", "variant": "definition", "title": "Três camadas que não devem ser misturadas", "text": "A **linguagem C++** define objetos, tipos, tempo de vida e comportamento observável. A **ISA** (*Instruction Set Architecture*) define o contrato visível entre software e processador: instruções, registradores, endereçamento e exceções. A **microarquitetura** é a implementação interna concreta da ISA, com caches, unidades de execução, renomeação e predição. Um programa C++ pode ser correto sem mencionar nenhuma delas."}, {"type": "mermaid", "caption": "camadas de abstração: cada camada preserva contratos diferentes", "accent": "blue", "code": "flowchart TD\n  C(\"Programa C++\") --> I(\"Compilador e ABI\")\n  I --> A(\"ISA: instruções e registradores visíveis\")\n  A --> M(\"Microarquitetura: pipeline, caches e execução\")\n  M --> H(\"Hardware físico\")"}, {"type": "heading", "level": 3, "text": "O estado que a ISA torna visível"}, {"type": "paragraph", "text": "Um **registrador arquitetural** é um armazenamento pequeno cujo nome e efeito fazem parte da ISA. Em x86-64, `RAX`–`R15` são registradores gerais de 64 bits; `RIP` aponta para a instrução corrente ou seguinte; `RSP` aponta para o topo da pilha; e `RFLAGS` contém bits de condição como `ZF` (resultado zero), `CF` (carry/borrow), `SF` (sinal) e `OF` (overflow assinado). `EAX`, `AX` e `AL` designam porções de `RAX`; escrever em `EAX` normalmente zera os 32 bits superiores de `RAX`. Isso é uma regra x86-64, não uma propriedade de um `int` C++."}, {"type": "table", "header": ["Mnemônico", "Efeito conceitual", "Exemplo detalhado"], "rows": [["`mov`", "Copia bits entre registrador, memória ou imediato; não significa necessariamente acesso à RAM.", "`mov %edi, %eax` copia os 32 bits de `EDI` para `EAX`; `mov (%rdi), %eax` calcula o endereço em `RDI` e lê 4 bytes."], ["`lea`", "Calcula um endereço efetivo sem ler o conteúdo apontado.", "`lea 8(%rdi,%rsi,4), %rax` calcula `RDI + RSI*4 + 8`, útil para `&v[i].campo`."], ["`add` / `sub`", "Soma ou subtrai e atualiza flags.", "`add %edx, %eax` calcula `EAX = EAX + EDX`; `ZF`, `CF`, `SF` e `OF` podem mudar."], ["`cmp` / `test`", "Compara ou combina valores atualizando flags, sem guardar o resultado principal.", "`cmp $0, %eax` permite `je` quando `EAX == 0`; `test %eax,%eax` é uma forma comum de testar zero."], ["`jmp` / `jcc`", "Altera o fluxo; `jcc` é um salto condicional baseado em flags.", "`jne loop` salta se `ZF=0`; o preditor de desvios pode especular esse caminho."], ["`call` / `ret`", "Faz chamada e retorno conforme a convenção de código.", "`call f` guarda um endereço de retorno; `ret` o recupera da pilha. Argumentos e resultado seguem a ABI."], ["`push` / `pop`", "Ajusta `RSP` e grava ou carrega um valor na pilha.", "`push %rbp` equivale conceitualmente a decrementar `RSP` e armazenar o antigo `RBP`."], ["`imul`", "Multiplica inteiros, com formas de um, dois ou três operandos.", "`imul -4(%rbp), %eax` calcula o quadrado de um valor local de 32 bits."], ["`and` / `or` / `xor`", "Operações bit a bit; `xor reg,reg` costuma zerar um registrador.", "`and $7, %eax` conserva apenas os três bits menos significativos."], ["`shl` / `shr` / `sar`", "Deslocam bits; `sar` preserva o sinal em deslocamento aritmético.", "`shl $2,%eax` multiplica por 4 apenas sob as condições apropriadas de overflow."]]}, {"type": "heading", "level": 3, "text": "Como uma instrução atravessa o processador"}, {"type": "paragraph", "text": "Um modelo didático usa **fetch** (buscar bytes da instrução), **decode** (decodificar opcode e operandos), renomeação/alocação, despacho, execução, acesso à memória, escrita de resultados e **retirement** (confirmar efeitos em ordem). Processadores reais sobrepõem muitas instruções. A execução fora de ordem pode executar uma operação pronta antes de outra bloqueada, mas o retirement preserva uma visão arquitetural coerente. Um **hazard** é uma dependência de dados, conflito de recursos ou incerteza de controle que impede o avanço ideal. A quantidade de estágios, micro-operações, largura de emissão e latência varia por microarquitetura."}, {"type": "mermaid", "caption": "pipeline didático, não uma descrição universal de uma CPU", "accent": "teal", "code": "flowchart LR\n  F(\"fetch\") --> D(\"decode\") --> R(\"renomear e agendar\") --> X(\"executar\") --> W(\"escrever resultado\") --> T(\"retirement em ordem\")"}, {"type": "callout", "variant": "warning", "title": "Latência não é throughput", "text": "**Latência** é o tempo até o resultado de uma operação estar disponível para uma dependência. **Throughput** é a taxa de operações independentes que uma unidade consegue sustentar. Duas multiplicações podem ter a mesma latência, mas serem iniciadas em ciclos diferentes; cache miss, dependências, prefetch e contenção alteram o tempo observado."}, {"type": "heading", "level": 3, "text": "Como ler assembly sem atribuir uma instrução a cada linha C++"}, {"type": "code", "language": "cpp", "title": "Fonte", "code": "int soma_quadrado(const int* v, int i) {\n    return v[i] * v[i] + 1;\n}"}, {"type": "code", "language": "asm", "title": "Uma tradução possível, AT&T, x86-64 System V", "code": "soma_quadrado:\n    movslq  %esi, %rax          # converte i para 64 bits\n    movl    (%rdi,%rax,4), %eax # carrega v[i], 4 bytes por int\n    imull   %eax, %eax           # eax = v[i] * v[i]\n    addl    $1, %eax             # eax += 1\n    ret                           # retorno inteiro em eax"}, {"type": "paragraph", "text": "Na sintaxe AT&T, a ordem usual é **fonte, destino**; `%` marca registradores e `$` marca imediatos. Na sintaxe Intel, a ordem é destino, fonte, e os prefixos mudam. `(%rdi,%rax,4)` significa endereço base `RDI`, índice `RAX`, escala 4 e deslocamento zero. A ABI System V AMD64 coloca o primeiro ponteiro em `RDI`, o segundo inteiro em `ESI` e devolve um `int` em `EAX`. O compilador pode vetorizar, eliminar a função, manter valores em registradores ou produzir código completamente diferente sob otimização."}, {"type": "heading", "level": 3, "text": "Memória, MMU, TLB e cache em uma leitura"}, {"type": "paragraph", "text": "O endereço usado pelo processo é **virtual**. A **MMU** (*Memory Management Unit*) consulta tabelas de páginas; a **TLB** (*Translation Lookaside Buffer*) é um cache dessas traduções. Depois, a hierarquia procura a linha em L1, L2 e LLC (último nível de cache), antes de recorrer à DRAM. Uma linha de cache é a unidade usual de transferência. Tamanho de página, número de níveis de cache, associatividade e coerência não são garantias do C++. **Localidade temporal** é reutilizar dados recentes; **localidade espacial** é acessar endereços próximos."}, {"type": "callout", "variant": "key", "title": "O que este livro assume", "text": "Quando um exemplo mostrar `%rdi`, ELF, Itanium ABI ou offsets de 8 bytes, a hipótese é **Linux x86-64, System V AMD64, GCC/Clang e ponteiros de 64 bits**. Quando uma regra vier do C++, ela será marcada como linguagem. A distinção evita transformar uma fotografia de uma implementação em uma lei universal."}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Você viu as três camadas que não podem ser misturadas — linguagem C++, ISA e microarquitetura —, o vocabulário de registradores e instruções x86-64, a diferença entre latência e throughput, e uma primeira passagem por MMU, TLB e cache. Esse vocabulário de baixo nível é o alicerce do livro inteiro: a Seção 2 usa exatamente essas camadas para separar \"duração de armazenamento\" (garantia do C++) de \"região de memória\" (implementação Linux/x86-64), e o caminho MMU→TLB→cache introduzido aqui é detalhado passo a passo na Seção 5."}, {"type": "heading", "level": 3, "text": "As quatro durações de armazenamento em C++"}, {"type": "paragraph", "text": "A duração estática cobre objetos que existem durante toda a execução; a duração thread_local cria uma instância por thread; a duração automática vale para objetos locais e parâmetros; a duração dinâmica acompanha a alocação e a liberação pela aplicação. Duração não é sinônimo de região física: o padrão da linguagem descreve tempo de vida e identidade, enquanto o sistema operacional decide páginas, pilhas, heaps e registradores."}, {"type": "code", "language": "cpp", "title": "Uma instância por thread", "code": "thread_local unsigned long requestsHandled = 0;\n\nvoid handleRequest() {\n    ++requestsHandled;\n}"}, {"type": "history", "name": "Bjarne Stroustrup", "shortBio": "Bjarne Stroustrup criou e evoluiu C++, inicialmente combinando abstração de alto nível com controle de recursos próximo ao hardware.", "insight": "A história ajuda a entender por que C++ preserva escolhas de desempenho, compatibilidade e abstração: o modelo da linguagem precisa conversar com compiladores, ABI e sistemas reais.", "image": {"src": "images/history-stroustrup.jpg", "alt": "Retrato de Bjarne Stroustrup"}}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "visao-geral", "number": "2", "title": "Visão geral e arquitetura de memória em C++", "blocks": [{"type": "paragraph", "text": "A ideia central é separar duas perguntas que costumam ser confundidas: **quanto tempo um objeto existe** e **em que região o programa normalmente armazena seus bytes**.", "lead": true}, {"type": "paragraph", "text": "A execução de um programa C++ nasce da interação entre o código da aplicação, o sistema operacional e a **ISA** (*Instruction Set Architecture*): a interface abstrata entre o processador e o código de máquina executável. Ao carregar um programa, o sistema operacional e a **MMU** (*Memory Management Unit*, o hardware que traduz endereços virtuais em físicos) criam um **VAS** (*Virtual Address Space*) exclusivo para o processo. A **memória virtual** é a abstração que dá a cada processo a ilusão de possuir um bloco contíguo e privado de endereços, isolando-o dos demais processos."}, {"type": "paragraph", "text": "Dentro do C++, esse espaço é ocupado seguindo as regras de **Storage Duration** — quando exatamente a memória de um objeto é alocada e liberada:"}, {"type": "mermaid", "code": "flowchart TD\n    A(\"Objeto em C++\") --> B{\"Storage Duration\"}\n    B --> C(\"Estática: existe do início ao fim do programa (globais, static)\")\n    B --> D(\"Automática: nasce ao entrar no escopo, morre ao sair (variáveis locais)\")\n    B --> E(\"Dinâmica: vive entre new/malloc e delete/free (controlada pelo programador)\")", "caption": "fluxo simplificado — as três durações de armazenamento", "accent": "pink"}, {"type": "callout", "variant": "key", "title": "Regra de leitura", "text": "Storage duration é uma propriedade semântica do programa; stack, heap e seções ELF são regiões ou mecanismos de implementação. Existe uma correspondência comum entre eles, mas ela não é uma equivalência obrigatória. Uma variável estática, por exemplo, pode ser implementada por uma seção diferente conforme o linker, e uma variável automática pode ser otimizada para um registrador."}, {"type": "paragraph", "text": "As três seções seguintes mapeiam essas durações para os locais mais comuns: seções do binário ELF, pilha e heap. Em seguida, a Seção 6 mostra como o próprio C++ — classes, herança e polimorfismo — é traduzido pelo compilador sobre essa base de baixo nível."}, {"type": "callout", "variant": "key", "title": "Onde o programa fica de verdade?", "text": "Stack e heap não são dois chips ou duas regiões físicas fixas da RAM. Eles são regiões de *endereços virtuais* no espaço do processo. Quando uma thread acessa um endereço, a CPU consulta a MMU: o número da página virtual é traduzido por tabelas de páginas para um *frame* físico, enquanto o deslocamento dentro da página permanece igual. Os frames podem estar espalhados pela RAM, compartilhados por processos, ainda não materializados ou temporariamente em swap. A RAM é o conjunto de frames físicos disponíveis ao sistema; o processo enxerga uma visão virtual, privada e contígua."}, {"type": "heading", "level": 3, "text": "Do código até a RAM: o caminho de um acesso"}, {"type": "paragraph", "text": "Considere `total = vetor[i]`. O compilador pode manter `i` e o endereço de `vetor` em registradores. A instrução de *load* calcula um endereço virtual; a TLB tenta encontrar a tradução recente; em um *hit*, o endereço físico é formado com o número do frame e o deslocamento. Em seguida, o núcleo procura a linha nas caches L1, L2 e LLC/L3. Só se a linha não estiver em nenhuma cache coerente ele precisa buscar na memória principal, normalmente DRAM. Se a página não estiver presente ou a permissão for inválida, ocorre um *page fault*; o kernel pode alocar um frame, trazer bytes de um arquivo/swap, fazer copy-on-write ou rejeitar o acesso com `SIGSEGV`."}, {"type": "mermaid", "code": "flowchart LR\n    C(\"CPU: registradores + instrução load\") --> V(\"endereço virtual\")\n    V --> T(\"TLB: tradução em cache\")\n    T -->|\"hit\"| P(\"permissões + frame físico\")\n    T -->|\"miss\"| PT(\"page tables / page walk\")\n    PT -->|\"presente\"| P\n    PT -->|\"ausente ou proibido\"| PF(\"page fault → kernel\")\n    P --> L1(\"L1 → L2 → LLC/L3\")\n    L1 --> D(\"DRAM / memória mapeada\")", "caption": "um load atravessando hardware, MMU e memória", "accent": "blue"}, {"type": "callout", "variant": "info", "title": "Distinção importante", "text": "A linguagem C++ garante duração, identidade e regras de acesso dos objetos; ela não garante MMU, TLB, RAM, tamanho de página, cache, ELF ou que uma variável automática use `%rsp`. As explicações de Linux/x86-64 neste guia são o mapeamento de uma implementação concreta, útil para entender o que ocorre, mas não devem ser tratadas como portabilidade da linguagem."}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Esta seção estabeleceu a distinção central do livro: tempo de vida de um objeto (Storage Duration, uma garantia do C++) não é o mesmo que a região de memória onde ele costuma morar (stack, heap, seções ELF — uma convenção de implementação Linux/x86-64). Essa distinção usa diretamente as três camadas apresentadas na Seção 1 (linguagem × ISA × microarquitetura) e é o fio condutor que a Seção 4 detalha visualmente e a Seção 5 desmonta região por região."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "toolchain", "number": "3", "title": "Da fonte ao processo: pré-processador, compilador, assembler, linker e loader", "blocks": [{"type": "paragraph", "lead": true, "text": "O comando `g++` não é apenas um compilador: é um **driver** que coordena etapas. O fluxo comum passa por pré-processamento, compilação, montagem e linkagem, mas LTO, assembler integrado, PCH, módulos e otimizações podem mudar as fronteiras visíveis. O padrão C++ define fases de tradução; não exige que cada fase seja um programa separado."}, {"type": "mermaid", "caption": "artefatos observáveis em um fluxo GCC/Clang típico", "accent": "blue", "code": "flowchart LR\n  S(\"main.cpp\") -->|\"-E\"| P(\"preprocessed.i\")\n  P -->|\"-S\"| A(\"assembly.s\")\n  A -->|\"-c\"| O(\"main.o ET_REL\")\n  O --> L(\"linker\")\n  L --> E(\"app ELF\")\n  E --> K(\"kernel + dynamic linker\")\n  K --> R(\"processo iniciado\")"}, {"type": "subsection", "id": "sec-preprocessador", "number": "3.1", "title": "Pré-processamento e unidade de tradução", "tag": "FRONT-END", "accent": "cyan", "blocks": [{"type": "paragraph", "text": "O **pré-processador** executa diretivas iniciadas por `#`, como `#include`, `#define` e `#if`. `#include` insere o conteúdo do header de forma recursiva; não procura uma função no linker. Macros são substituições de tokens e não entendem tipos, overload ou escopos. Depois dessas transformações, o resultado lógico é a **unidade de tradução**: o que o compilador C++ analisa como uma unidade."}, {"type": "code", "language": "cpp", "title": "Entrada", "code": "#define QUADRADO(x) ((x) * (x))\n#ifdef DEBUG\nconstexpr int modo = 1;\n#else\nconstexpr int modo = 0;\n#endif\nint y = QUADRADO(3 + 1);"}, {"type": "code", "language": "bash", "title": "Inspeção", "code": "g++ -E -P exemplo.cpp -o exemplo.i\n# -E para após o pré-processamento; -P remove marcadores de linha"}, {"type": "callout", "variant": "warning", "title": "Macro não é função", "text": "`QUADRADO(i++)` expande para `((i++) * (i++))` e altera `i` duas vezes. A macro não possui tipo nem avaliação única. Prefira função ou template quando a semântica exigir segurança."}]}, {"type": "subsection", "id": "sec-compilador", "number": "3.2", "title": "Compilador: análise, IR, otimização e geração", "tag": "COMPILADOR", "accent": "violet", "blocks": [{"type": "paragraph", "text": "O **front end** verifica sintaxe e semântica: tipos, escopos, templates, overload e regras de lifetime. Uma **IR** (*Intermediate Representation*, representação intermediária) registra operações em uma forma que facilita análises. O **back end** seleciona instruções do alvo, aloca registradores e emite assembly ou objeto. A otimização pode remover código morto, propagar constantes, vetorizar e fazer inline, desde que preserve o comportamento permitido pelo C++."}, {"type": "table", "header": ["Comando", "Ponto de parada", "Pergunta respondida"], "rows": [["`g++ -E`", "após pré-processador", "Qual texto e quais macros chegaram ao compilador?"], ["`g++ -S -O0`", "após geração de assembly", "Como uma tradução pouco otimizada expressa a função?"], ["`g++ -S -O2`", "após otimização", "Que trabalho o compilador eliminou, fundiu ou reordenou?"], ["`g++ -c`", "arquivo objeto ET_REL", "Quais símbolos e relocations ainda aguardam o linker?"], ["`-g`", "metadados DWARF", "Como depurador relaciona instruções a linhas e variáveis?"], ["`-flto`", "otimização entre unidades", "Como o linker participa de otimização global?"]]}]}, {"type": "subsection", "id": "sec-assembler", "number": "3.3", "title": "Assembler, objeto relocatable e símbolos", "tag": "ELF", "accent": "amber", "blocks": [{"type": "paragraph", "text": "O **assembler** traduz mnemônicos e diretivas para bytes, seções, símbolos e **relocations**. Uma relocation é uma receita que diz ao linker ou ao dynamic linker como preencher um campo quando o endereço definitivo for conhecido. O objeto `ET_REL` ainda não é um executável: uma chamada para `extern int f();` pode conter um símbolo indefinido e uma relocation relativa à chamada."}, {"type": "code", "language": "bash", "title": "Ferramentas de inspeção", "code": "g++ -c main.cpp -o main.o\nreadelf -h -S -s -r main.o\nnm -C main.o\nobjdump -drwC main.o"}, {"type": "table", "header": ["Termo", "Definição técnica", "Armadilha"], "rows": [["símbolo", "Nome associado a função, objeto, seção ou TLS; possui binding, tipo, visibilidade e índice de seção.", "Símbolo não é sempre um endereço final; pode estar indefinido ou ser relativo à seção."], ["local/global/weak", "Bindings que controlam alcance e preferência na resolução.", "`weak` não significa automaticamente “sem definição”; regras de escolha ainda importam."], ["`.symtab` / `.dynsym`", "Tabela completa de linkagem e tabela menor para linkagem dinâmica.", "`.symtab` pode ser removida de um executável sem impedir sua execução."], ["REL/RELA", "Relocation com addend no local ou addend explícito na entrada.", "A fórmula depende do tipo da arquitetura; não é um simples deslocamento."]]}]}, {"type": "subsection", "id": "sec-linker", "number": "3.4", "title": "Linker, bibliotecas e relocations", "tag": "LINK", "accent": "orange", "blocks": [{"type": "paragraph", "text": "O **linker** combina objetos e bibliotecas, resolve referências entre símbolos, organiza seções, aplica relocations que pode resolver e produz um executável ou *shared object*. Uma biblioteca estática `.a` é um arquivo de objetos; em geral o linker extrai apenas membros necessários, por isso a ordem `objetos bibliotecas` pode importar. Uma biblioteca compartilhada `.so` mantém trabalho para o carregamento dinâmico."}, {"type": "code", "language": "bash", "title": "Linkagem estática e dinâmica", "code": "g++ main.o math.o -o app\ng++ main.o -L./lib -lmath -o app\ng++ -static main.o -o app-static\nreadelf -l -d -s app\nldd app"}, {"type": "paragraph", "text": "Em código **PIC** (*Position-Independent Code*) e executáveis **PIE** (*Position-Independent Executable*), endereços podem ser resolvidos com base relativa ao `RIP`. A **GOT** (*Global Offset Table*) guarda endereços indiretos; a **PLT** (*Procedure Linkage Table*) oferece stubs para chamadas, inclusive com resolução lazy. `S`, `A`, `P` e `B` são símbolos usados em fórmulas de relocation, mas o tipo exato — por exemplo, relativo ao PC ou à base — pertence ao psABI da arquitetura."}, {"type": "callout", "variant": "key", "title": "API não é ABI", "text": "API é o contrato de código-fonte, como uma assinatura de função. ABI é o contrato binário: registradores, alinhamento, layout de tipos, mangling, exceções, símbolos e formato. `extern \"C\"` geralmente evita mangling C++, mas não torna tipos, alocação, calling convention ou bibliotecas automaticamente compatíveis."}]}, {"type": "subsection", "id": "sec-elf-loader", "number": "3.5", "title": "ELF, segmentos, loader e dynamic linker", "tag": "RUNTIME", "accent": "teal", "blocks": [{"type": "paragraph", "text": "ELF (*Executable and Linking Format*) oferece duas visões. **Seções** organizam material para linkagem e ferramentas, como `.text`, `.data`, `.symtab` e `.rela.*`. **Segmentos** descritos pela tabela de program headers dizem ao carregador como construir a imagem em memória; `PT_LOAD` é um segmento carregável e `PT_INTERP` identifica o interpretador dinâmico. Uma section header table pode ser removida sem destruir a capacidade de execução de um ELF bem formado."}, {"type": "mermaid", "caption": "quem faz o quê no início do processo", "accent": "teal", "code": "sequenceDiagram\n  participant K as kernel\n  participant D as dynamic linker\n  participant C as runtime C/C++\n  participant M as main\n  K->>K: execve e mapeia ELF\n  K->>D: PT_INTERP, se houver\n  D->>D: mapeia DT_NEEDED e aplica relocations\n  D->>C: executa inicializadores\n  C->>M: prepara e chama main"}, {"type": "paragraph", "text": "O kernel realiza o carregamento inicial após `execve`. Em um binário dinâmico, o `ld-linux.so` atua em espaço de usuário como **dynamic linker**: encontra dependências `DT_NEEDED`, calcula bases, resolve símbolos, aplica relocations, prepara GOT/PLT e executa inicializadores. O runtime chama `main`; o linker de build não é o componente que mapeia páginas no processo em execução."}, {"type": "code", "language": "bash", "title": "Perguntas respondidas por readelf", "code": "readelf -h app       # tipo ELF, arquitetura, entry point\nreadelf -l app       # segmentos e permissões\nreadelf -S app       # seções\nreadelf -d app       # dependências dinâmicas\nreadelf -r app       # relocations\nobjdump -M intel -d app"}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Você acompanhou o caminho completo do código-fonte até o processo em execução: pré-processador, front end/IR/back end do compilador, assembler gerando símbolos e relocations, linker resolvendo referências e combinando seções, e o par loader/dynamic linker montando a imagem final via ELF. Os conceitos de registrador e instrução da Seção 1 aparecem aqui como alvo da geração de código; os artefatos criados nesta seção (símbolos, seções ELF, PIC/PIE, GOT/PLT) são o que a Seção 4 visualiza como mapa de endereços e o que a Seção 7 revisita ao explicar PIE/ASLR e RELRO."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "pipeline", "number": "4", "title": "Compilador, linker e o formato ELF", "blocks": [{"type": "paragraph", "text": "O código C++ é transformado em binário pelo **Compiler Driver** (ex.: `g++`), que orquestra o pré-processador, o compilador propriamente dito, o montador (*assembler*) e o **linker** — o utilitário que combina arquivos-objeto em um executável final. O resultado segue o formato **ELF** (*Executable and Linking Format*), o padrão de binários em Linux/Unix, e respeita a **ABI** (*Application Binary Interface*) da plataforma: o contrato que padroniza layout de memória, convenções de chamada de função e alinhamento no nível de instrução de máquina."}, {"type": "mermaid", "code": "flowchart LR\n    S(\"código.cpp\") --> P(\"Pré-processador\")\n    P --> C(\"Compilador C++\")\n    C --> A(\"Montador (assembler)\")\n    A --> O(\"Arquivo-objeto .o\")\n    O --> L(\"Linker\")\n    L --> E(\"Executável ELF\")", "caption": "fluxo simplificado — do código-fonte ao executável", "accent": "blue"}, {"type": "paragraph", "text": "Conforme detalhado em *Computer Systems: A Programmer's Perspective* (CS:APP, caps. 7 e 9), o espaço de endereçamento virtual de um processo Linux organiza-se, da base ao topo, nas seções estáticas do ELF (`.text`, `.rodata`, `.data`, `.bss`) — que depois são agrupadas em segmentos ELF — e nas duas regiões dinâmicas — heap e stack — que crescem uma em direção à outra. O diagrama abaixo é a referência completa; as seções 5.1–5.6 o desmembram em blocos menores e mais fáceis de acompanhar."}, {"type": "details", "summary": "ver diagrama de referência completo do espaço de endereçamento virtual", "blocks": [{"type": "mermaid", "code": "flowchart TD\n    K(\"Memória do kernel — invisível ao processo em modo usuário\")\n    ST(\"Stack (pilha) — cresce para endereços menores ↓ · quadros de função, variáveis locais, %rsp/%rbp\")\n    GAP(\"Região de mapeamento (mmap) — bibliotecas compartilhadas, ASLR insere aqui deslocamentos aleatórios\")\n    HP(\"Heap (monte) — cresce para endereços maiores ↑ · alocações via new/malloc, ponteiro brk\")\n    BSS(\".bss — globais/estáticas não inicializadas, zero-fill on demand\")\n    DATA(\".data — globais/estáticas inicializadas com valor não-zero\")\n    RODATA(\".rodata — literais de string, jump tables, vtables (somente leitura)\")\n    TEXT(\".text — instruções de máquina (somente leitura e executável)\")\n\n    K --- ST\n    ST --> GAP\n    GAP --> HP\n    HP --- BSS\n    BSS --- DATA\n    DATA --- RODATA\n    RODATA --- TEXT\n\n    style K fill:#5b6672,color:#fff,stroke:#333\n    style ST fill:#a78bfa,color:#1a1024,stroke:#333\n    style GAP fill:#cfd6dc,color:#20262c,stroke:#333,stroke-dasharray: 4 3\n    style HP fill:#f2704f,color:#2a0f06,stroke:#333\n    style BSS fill:#8b98a5,color:#0d1114,stroke:#333\n    style DATA fill:#e8a33d,color:#2a1a02,stroke:#333\n    style RODATA fill:#2dd4bf,color:#04201c,stroke:#333\n    style TEXT fill:#5b93ff,color:#04122e,stroke:#333"}]}, {"type": "heading", "level": 3, "text": "Visualização: mapa de endereços proporcional"}, {"type": "paragraph", "text": "Um mapa de endereços é, no fundo, uma pergunta espacial — \"o que fica onde, e em que direção cresce\" — e um diagrama de fluxo (bom para *sequências de passos*) explica isso pior do que um mapa desenhado à escala. A visualização abaixo é um SVG customizado só para isso:"}, {"type": "svg", "svg": "<svg aria-labelledby=\"map-title map-desc\" class=\"diagram diagram-map\" role=\"img\" viewBox=\"0 0 860 560\" xmlns=\"http://www.w3.org/2000/svg\">\n<title id=\"map-title\">Mapa conceitual do espaço de endereçamento virtual</title>\n<desc id=\"map-desc\">Mapa vertical que relaciona endereços altos e baixos às regiões kernel, stack, mmap, heap, bss, data, rodata e text. A altura dos blocos não representa tamanho real.</desc>\n<defs><marker id=\"map-down\" markerHeight=\"9\" markerWidth=\"9\" orient=\"auto\" refX=\"7\" refY=\"4.5\"><path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#d8c9ff\"></path></marker><marker id=\"map-up\" markerHeight=\"9\" markerWidth=\"9\" orient=\"auto\" refX=\"7\" refY=\"4.5\"><path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#ffd1c4\"></path></marker></defs>\n<text fill=\"#e7edf3\" font-family=\"IBM Plex Mono, monospace\" font-size=\"14\" font-weight=\"600\" x=\"34\" y=\"28\">ESPAÇO DE ENDEREÇAMENTO VIRTUAL — mapa conceitual</text>\n<text fill=\"#aebdca\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"13\" x=\"34\" y=\"51\">endereços altos</text>\n<line marker-end=\"url(#map-down)\" stroke=\"#8293a1\" stroke-width=\"2\" x1=\"34\" x2=\"34\" y1=\"61\" y2=\"495\"></line>\n<text fill=\"#aebdca\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"13\" transform=\"rotate(-90 8 495)\" x=\"8\" y=\"495\">endereços diminuem ↓</text>\n<rect fill=\"#56636e\" height=\"44\" rx=\"7\" stroke=\"#aebdca\" stroke-width=\"1.5\" width=\"430\" x=\"130\" y=\"68\"></rect>\n<text fill=\"#f1f5f9\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"13\" font-weight=\"600\" x=\"148\" y=\"87\">KERNEL</text>\n<text fill=\"#d8e0e7\" font-family=\"IBM Plex Mono, monospace\" font-size=\"11\" x=\"148\" y=\"103\">reservado ao SO · não acessível em modo usuário</text>\n<rect fill=\"#806da9\" height=\"70\" rx=\"7\" stroke=\"#d8c9ff\" stroke-width=\"1.5\" width=\"430\" x=\"130\" y=\"120\"></rect>\n<text fill=\"#fffaff\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"14\" font-weight=\"700\" x=\"148\" y=\"143\">STACK</text>\n<text fill=\"#f1eaff\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"12\" x=\"148\" y=\"162\">quadros de função e variáveis automáticas</text>\n<text fill=\"#e0d6fa\" font-family=\"IBM Plex Mono, monospace\" font-size=\"11\" x=\"148\" y=\"179\">cresce ↓ para endereços menores</text>\n<rect fill=\"#26343f\" height=\"66\" rx=\"7\" stroke=\"#8fa0ac\" stroke-dasharray=\"7 5\" stroke-width=\"1.5\" width=\"430\" x=\"130\" y=\"198\"></rect>\n<text fill=\"#e7edf3\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"14\" font-weight=\"700\" x=\"148\" y=\"221\">mmap</text>\n<text fill=\"#c7d1da\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"12\" x=\"148\" y=\"240\">bibliotecas compartilhadas e mapeamentos de arquivos</text>\n<text fill=\"#aebdca\" font-family=\"IBM Plex Mono, monospace\" font-size=\"11\" x=\"148\" y=\"256\">posição sujeita ao ASLR</text>\n<rect fill=\"#d85f42\" height=\"66\" rx=\"7\" stroke=\"#ffd1c4\" stroke-width=\"1.5\" width=\"430\" x=\"130\" y=\"272\"></rect>\n<text fill=\"#2b1108\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"14\" font-weight=\"700\" x=\"148\" y=\"295\">HEAP</text>\n<text fill=\"#3a1710\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"12\" x=\"148\" y=\"314\">new / malloc · alocações dinâmicas</text>\n<text fill=\"#4c1e14\" font-family=\"IBM Plex Mono, monospace\" font-size=\"11\" x=\"148\" y=\"330\">cresce ↑ para endereços maiores</text>\n<rect fill=\"#8b98a5\" height=\"32\" rx=\"5\" width=\"430\" x=\"130\" y=\"346\"></rect>\n<text fill=\"#0d1114\" font-family=\"IBM Plex Mono, monospace\" font-size=\"12\" x=\"148\" y=\"367\">.bss · globais/estáticas zeradas</text>\n<rect fill=\"#e8a33d\" height=\"32\" rx=\"5\" width=\"430\" x=\"130\" y=\"384\"></rect>\n<text fill=\"#2a1a02\" font-family=\"IBM Plex Mono, monospace\" font-size=\"12\" x=\"148\" y=\"405\">.data · globais/estáticas inicializadas</text>\n<rect fill=\"#2dd4bf\" height=\"32\" rx=\"5\" width=\"430\" x=\"130\" y=\"422\"></rect>\n<text fill=\"#04201c\" font-family=\"IBM Plex Mono, monospace\" font-size=\"12\" x=\"148\" y=\"443\">.rodata · strings e dados somente leitura</text>\n<rect fill=\"#5b93ff\" height=\"32\" rx=\"5\" width=\"430\" x=\"130\" y=\"460\"></rect>\n<text fill=\"#04122e\" font-family=\"IBM Plex Mono, monospace\" font-size=\"12\" x=\"148\" y=\"481\">.text · instruções de máquina (r-x)</text>\n<line marker-end=\"url(#map-down)\" stroke=\"#d8c9ff\" stroke-width=\"2\" x1=\"625\" x2=\"625\" y1=\"145\" y2=\"245\"></line>\n<text fill=\"#e0d6fa\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"12\" x=\"650\" y=\"170\">stack desce</text>\n<text fill=\"#b9aee0\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"11\" x=\"650\" y=\"188\">endereços menores</text>\n<line marker-end=\"url(#map-up)\" stroke=\"#ffd1c4\" stroke-width=\"2\" x1=\"625\" x2=\"625\" y1=\"325\" y2=\"275\"></line>\n<text fill=\"#ffd9cf\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"12\" x=\"650\" y=\"307\">heap sobe</text>\n<text fill=\"#f4b9aa\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"11\" x=\"650\" y=\"325\">endereços maiores</text>\n<text fill=\"#91a0ad\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"11\" x=\"130\" y=\"531\">A altura dos blocos mostra ordem relativa, não tamanho real. PIE/ASLR deslocam as bases a cada execução.</text>\n</svg>", "alt": "Mapa conceitual do espaço de endereçamento virtual"}, {"type": "callout", "variant": "note", "text": "Não é uma escala real de tamanhos — é uma escala de **ordem e direção**, que é o que importa para entender por que stack e heap podem, em teoria, colidir se um crescer demais em direção ao outro."}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Este capítulo transformou os artefatos abstratos da Seção 3 (seções ELF, segmentos, heap/stack) em um mapa visual único do espaço de endereços, do topo até a base. Ele serve de referência para a Seção 5, que desmembra cada uma dessas regiões — `.text`, `.rodata`, `.data`, `.bss`, stack e heap — uma a uma, com código C++, assembly e explicação instrução a instrução."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "regioes", "number": "5", "title": "As regiões da memória virtual, uma a uma", "blocks": [{"type": "paragraph", "text": "Cada subseção abaixo segue o mesmo roteiro: o que a região guarda → um fluxo simplificado → um trecho de C++ → a tradução ilustrativa em `.text` (x86-64, sintaxe AT&T, sem otimizações — o que um compilador real gera varia por versão e nível de otimização, mas o padrão é este) → e a explicação instrução a instrução, tanto do lado C++ quanto do lado assembly."}, {"type": "subsection", "id": "sec-mapa-ram", "number": "5.0", "title": "O mapa real: regiões virtuais e frames físicos", "tag": "RAM / MMU", "accent": "slate", "blocks": [{"type": "paragraph", "text": "O processo não é copiado inteiro para uma faixa contínua da RAM. O kernel mantém um espaço de endereços virtual, dividido em páginas, e associa cada página virtual a um frame físico quando necessário. Assim, uma página de `.text` pode ser compartilhada entre processos; uma página anônima do heap pode nascer apenas na primeira escrita; e uma página da stack pode ser privada, copiada sob demanda ou recuperada sob pressão de memória."}, {"type": "table", "header": ["Região observada", "O que normalmente significa", "O que não significa"], "rows": [["`[stack]`", "VMA usada pela thread principal no Linux, com frames de chamadas e dados automáticos quando o compilador não os mantém em registradores.", "Não é uma faixa física contínua nem todo o limite já residente na RAM."], ["`[heap]`", "VMA tradicional associada ao program break da arena principal da libc.", "Não engloba necessariamente toda memória de `malloc`; alocações grandes podem vir de `mmap`."], ["`r-xp` de um ELF", "Mapping privado de páginas de código, normalmente file-backed, com leitura e execução.", "Não garante que cada byte já esteja na RAM; páginas podem ser carregadas sob demanda."], ["VMA anônima", "Espaço sem arquivo associado, usado por BSS, heap, stack, TLS e `mmap(MAP_ANONYMOUS)`.", "Não é sinônimo de memória física imediatamente alocada."]]}, {"type": "paragraph", "text": "Use `cat /proc/$PID/maps` para observar intervalos virtuais e permissões e `cat /proc/$PID/smaps` para comparar `Size`, `Rss`, `Pss` e `Swap`. `VmSize` mede espaço virtual; `VmRSS` mede páginas residentes. Nenhum dos dois é “o tamanho do programa na RAM” sem qualificação."}, {"type": "callout", "variant": "warning", "title": "Confusão comum", "text": "Uma page fault não significa necessariamente que houve leitura de disco. Ela pode apenas materializar uma página anônima zerada, estabelecer copy-on-write ou corrigir uma tradução ausente. Em uma página file-backed, o kernel pode usar o page cache; em outra situação, pode precisar buscar o arquivo ou o swap."}]}, {"type": "subsection", "id": "sec-text", "number": "5.1", "title": "Seção de texto (`.text`)", "tag": ".TEXT", "accent": "blue", "blocks": [{"type": "paragraph", "text": "Contém as instruções binárias que o processador busca (*fetch*), decodifica e executa. É marcada como somente leitura e executável (`r-x`) justamente para impedir que código malicioso reescreva instruções em tempo de execução."}, {"type": "mermaid", "code": "flowchart LR\n    PC(\"Program Counter (%rip)\") -->|\"busca instrução\"| TXT(\"Seção .text\")\n    TXT -->|\"decodifica e executa\"| CPU(\"Unidade de execução da CPU\")\n    CPU -->|\"avança\"| PC", "caption": "fluxo simplificado", "accent": "blue"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "int quadrado(int x) {\n    return x * x;\n}"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa em .text", "code": "quadrado:\n    push   %rbp             # prólogo\n    mov    %rsp, %rbp\n    mov    %edi, -4(%rbp)   # x chega em %edi (ABI System V), guardado na pilha\n    mov    -4(%rbp), %eax\n    imul   -4(%rbp), %eax   # %eax = x * x\n    pop    %rbp             # epílogo\n    ret"}, {"type": "table", "header": ["#", "C++ / instrução", "O que acontece"], "rows": [["1", "`int quadrado(int x)`", "o compilador cria o rótulo `quadrado:` dentro de `.text`; pela convenção de chamada (System V AMD64 ABI), o primeiro argumento inteiro chega no registrador `%edi`."], ["2", "`push %rbp`", "empilha o *frame pointer* do chamador, preservando-o para quando esta função retornar."], ["3", "`mov %rsp, %rbp`", "estabelece `%rbp` como referência fixa para este novo quadro de pilha."], ["4", "`mov %edi, -4(%rbp)`", "copia `x` do registrador para uma posição na pilha (variável local com duração automática)."], ["5", "`return x * x;`", "recarrega `x` em `%eax` e usa `imul` para multiplicar; o resultado de uma função inteira sempre volta em `%eax`/`%rax`, por convenção da ABI."], ["6", "`pop %rbp` / `ret`", "epílogo: restaura o `%rbp` do chamador e usa `ret` para saltar de volta ao endereço que a instrução `call` empilhou."]]}]}, {"type": "subsection", "id": "sec-rodata", "number": "5.2", "title": "Dados somente de leitura (`.rodata`)", "tag": ".RODATA", "accent": "teal", "blocks": [{"type": "paragraph", "text": "Guarda constantes imutáveis: literais de string, *jump tables* geradas por um `switch`, e — adiante na Seção 6.3 — as **vtables** do C++."}, {"type": "mermaid", "code": "flowchart LR\n    T(\".text: instrução usa o literal\") -->|\"endereçamento relativo a %rip\"| R(\"Seção .rodata\")\n    R --> S(\"bytes do literal, ex: string terminada em zero\")", "caption": "fluxo simplificado", "accent": "teal"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "const char* mensagem = \"memoria\";"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa", "code": "    .section .rodata\n.LC0:\n    .string \"memoria\"       # bytes ascii + terminador nulo\n\n    .section .data\nmensagem:\n    .quad .LC0              # o PONTEIRO fica em .data — ele mesmo não é zero\n\n    .section .text\n    lea    .LC0(%rip), %rax # carrega o endereço do literal (relativo ao PC)\n    mov    %rax, mensagem(%rip)"}, {"type": "table", "header": ["#", "C++ / instrução", "O que acontece"], "rows": [["1", "`\"memoria\"`", "o literal de string vira o símbolo `.LC0`, alocado em `.rodata`."], ["2", "`.string`", "diretiva do montador que grava os bytes ASCII seguidos do terminador nulo."], ["3", "`lea .LC0(%rip), %rax`", "`lea` (\"load effective address\") calcula o endereço de `.LC0` relativo ao *Program Counter* — endereçamento `%rip`-relativo, essencial para código independente de posição (PIE, ver Seção 3)."], ["4", "`char* mensagem = ...`", "o próprio ponteiro `mensagem` é uma variável global inicializada com valor não-zero (um endereço), por isso ele fica em `.data`, não em `.rodata`."]]}]}, {"type": "subsection", "id": "sec-data", "number": "5.3", "title": "Dados inicializados (`.data`)", "tag": ".DATA", "accent": "amber", "blocks": [{"type": "paragraph", "text": "Guarda variáveis globais e `static` que foram explicitamente inicializadas com um valor diferente de zero no código-fonte."}, {"type": "mermaid", "code": "flowchart LR\n    F(\"Arquivo ELF em disco: valor já gravado nos bytes\") --> L(\"Carregador do SO (execve)\")\n    L --> M(\"Seção .data em memória, já com o valor\")", "caption": "fluxo simplificado", "accent": "amber"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "int contador_global = 42;"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa", "code": "    .data\n    .globl contador_global\ncontador_global:\n    .long 42                        # 4 bytes, valor 42 já gravado no arquivo ELF\n\n    .text\n    mov    contador_global(%rip), %eax   # leitura em qualquer função"}, {"type": "table", "header": ["#", "C++ / instrução", "O que acontece"], "rows": [["1", "`int contador_global = 42;`", "o compilador emite um símbolo global direcionado a `.data`."], ["2", "`.long 42`", "reserva 4 bytes e grava o valor `42` diretamente nos bytes do executável no disco."], ["3", "carregamento via `execve`", "o kernel mapeia essa página do arquivo direto para a memória — o valor já chega pronto, sem nenhum código de inicialização em tempo de execução."], ["4", "`mov contador_global(%rip), %eax`", "qualquer leitura da variável usa endereçamento relativo ao `%rip`, o mesmo mecanismo do item 3 da seção anterior."]]}]}, {"type": "subsection", "id": "sec-bss", "number": "5.4", "title": "Dados não inicializados (`.bss`)", "tag": ".BSS", "accent": "gray", "blocks": [{"type": "paragraph", "text": "*Block Started by Symbol* — nome herdado de uma diretiva de montador da IBM. Reserva espaço para globais/estáticas sem inicializador (ou inicializadas com zero) sem ocupar espaço de dados dentro do arquivo executável em disco."}, {"type": "mermaid", "code": "flowchart LR\n    F2(\"Arquivo ELF: apenas o TAMANHO é registrado, nenhum byte de dado\") --> L2(\"Carregador do SO\")\n    L2 -->|\"preenche com zero (páginas anônimas)\"| M2(\"Seção .bss em memória\")", "caption": "fluxo simplificado", "accent": "gray"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "int acumulador_zero;"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa", "code": ".bss\n.globl acumulador_zero\n.zero 4                 # só o tamanho é reservado, nada é escrito no arquivo"}, {"type": "table", "header": ["#", "C++ / instrução", "O que acontece"], "rows": [["1", "`int acumulador_zero;`", "sem inicializador explícito → destino é `.bss`."], ["2", "`.zero 4`", "reserva 4 bytes de *tamanho* no cabeçalho ELF; nenhum byte de dado correspondente existe no arquivo — é por isso que `.bss` \"não ocupa espaço em disco\"."], ["3", "carregamento", "o kernel aloca páginas anônimas zeradas (`mmap` com `MAP_ANONYMOUS`) para cobrir essa região em DRAM."]]}, {"type": "callout", "variant": "tip", "title": "Detalhe fino", "text": "Mesmo uma variável escrita como `int x = 0;` (com `= 0` explícito) costuma ir parar em `.bss` também — o compilador reconhece que o valor final é zero e escolhe a representação mais barata, já que `.bss` não consome espaço em disco."}]}, {"type": "subsection", "id": "sec-stack", "number": "5.5", "title": "Pilha de execução (Stack)", "tag": "STACK", "accent": "violet", "blocks": [{"type": "paragraph", "text": "Região contígua usada para gerenciar chamadas de função e variáveis locais de duração automática. Em x86 e x86-64, a pilha cresce para **baixo** (endereços menores). Cada chamada aloca um **Stack Frame**, delimitado pelo **Stack Pointer** (`%rsp`) e pelo **Frame Pointer** (`%rbp`)."}, {"type": "mermaid", "code": "flowchart TD\n    C1(\"Chamada de função (call)\") --> P1(\"Empilha endereço de retorno + salva %rbp antigo\")\n    P1 --> L1(\"Reserva espaço para variáveis locais (sub %rsp)\")\n    L1 --> R1(\"Corpo da função executa\")\n    R1 --> E1(\"leave / pop: desfaz o quadro\")\n    E1 --> RT1(\"ret: volta ao chamador\")", "caption": "fluxo simplificado", "accent": "violet"}, {"type": "heading", "level": 4, "text": "Visualização: anatomia de um quadro de pilha"}, {"type": "svg", "svg": "<svg aria-labelledby=\"stack-title stack-desc\" class=\"diagram diagram-stack\" role=\"img\" viewBox=\"0 0 820 390\" xmlns=\"http://www.w3.org/2000/svg\">\n<title id=\"stack-title\">Anatomia de um quadro de pilha</title>\n<desc id=\"stack-desc\">Quadro de pilha em x86-64: argumentos e endereço de retorno ficam em endereços mais altos; variáveis locais ficam abaixo do rbp; o rsp marca o topo atual e a pilha cresce para endereços menores.</desc>\n<defs><marker id=\"stack-arrow\" markerHeight=\"9\" markerWidth=\"9\" orient=\"auto\" refX=\"7\" refY=\"4.5\"><path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#c4b5fd\"></path></marker></defs>\n<text fill=\"#e7edf3\" font-family=\"IBM Plex Mono, monospace\" font-size=\"14\" font-weight=\"600\" x=\"34\" y=\"28\">QUADRO DE PILHA — exemplo sem otimização</text>\n<text fill=\"#aebdca\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"13\" x=\"34\" y=\"51\">endereços maiores</text>\n<line marker-end=\"url(#stack-arrow)\" stroke=\"#8293a1\" stroke-width=\"2\" x1=\"34\" x2=\"34\" y1=\"60\" y2=\"320\"></line>\n<text fill=\"#aebdca\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"13\" transform=\"rotate(-90 8 347)\" x=\"8\" y=\"347\">direção de crescimento</text>\n<rect fill=\"#403765\" height=\"48\" rx=\"7\" stroke=\"#c4b5fd\" stroke-width=\"2\" width=\"340\" x=\"150\" y=\"68\"></rect>\n<text fill=\"#f4f0ff\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"14\" font-weight=\"600\" x=\"170\" y=\"89\">argumentos extras</text>\n<text fill=\"#ded6f7\" font-family=\"IBM Plex Mono, monospace\" font-size=\"11\" x=\"170\" y=\"107\">7º parâmetro em diante, quando houver</text>\n<rect fill=\"#514477\" height=\"48\" rx=\"7\" stroke=\"#c4b5fd\" stroke-width=\"2\" width=\"340\" x=\"150\" y=\"120\"></rect>\n<text fill=\"#f4f0ff\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"14\" font-weight=\"600\" x=\"170\" y=\"141\">endereço de retorno</text>\n<text fill=\"#ded6f7\" font-family=\"IBM Plex Mono, monospace\" font-size=\"11\" x=\"170\" y=\"159\">empilhado pela instrução call</text>\n<rect fill=\"#65548e\" height=\"48\" rx=\"7\" stroke=\"#c4b5fd\" stroke-width=\"2\" width=\"340\" x=\"150\" y=\"172\"></rect>\n<text fill=\"#fffaff\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"14\" font-weight=\"600\" x=\"170\" y=\"193\">%rbp salvo do chamador</text>\n<text fill=\"#eee8ff\" font-family=\"IBM Plex Mono, monospace\" font-size=\"11\" x=\"170\" y=\"211\">referência do quadro anterior</text>\n<rect fill=\"#806da9\" height=\"78\" rx=\"7\" stroke=\"#c4b5fd\" stroke-width=\"2\" width=\"340\" x=\"150\" y=\"224\"></rect>\n<text fill=\"#fffaff\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"14\" font-weight=\"600\" x=\"170\" y=\"247\">variáveis locais</text>\n<text fill=\"#f5f0ff\" font-family=\"IBM Plex Mono, monospace\" font-size=\"11\" x=\"170\" y=\"266\">total → -12(%rbp)</text>\n<text fill=\"#f5f0ff\" font-family=\"IBM Plex Mono, monospace\" font-size=\"11\" x=\"170\" y=\"284\">a → -4(%rbp) · b → -8(%rbp)</text>\n<line stroke=\"#c4b5fd\" stroke-width=\"2\" x1=\"495\" x2=\"570\" y1=\"196\" y2=\"196\"></line>\n<text fill=\"#e6defc\" font-family=\"IBM Plex Mono, monospace\" font-size=\"13\" font-weight=\"600\" x=\"585\" y=\"191\">%rbp</text>\n<text fill=\"#b9aee0\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"12\" x=\"585\" y=\"209\">base fixa do quadro</text>\n<line stroke=\"#c4b5fd\" stroke-width=\"2\" x1=\"495\" x2=\"570\" y1=\"302\" y2=\"302\"></line>\n<text fill=\"#e6defc\" font-family=\"IBM Plex Mono, monospace\" font-size=\"13\" font-weight=\"600\" x=\"585\" y=\"297\">%rsp</text>\n<text fill=\"#b9aee0\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"12\" x=\"585\" y=\"315\">topo atual da pilha</text>\n<text fill=\"#c4b5fd\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"13\" x=\"150\" y=\"342\">↓ endereços menores · o quadro cresce quando %rsp é decrementado</text>\n<text fill=\"#91a0ad\" font-family=\"IBM Plex Sans, sans-serif\" font-size=\"11\" x=\"150\" y=\"366\">Observação: registradores e layout exato variam com ABI, compilador e otimização.</text>\n</svg>", "alt": "Anatomia de um quadro de pilha"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "int soma(int a, int b) {\n    int total = a + b;\n    return total;\n}"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa", "code": "soma:\n    push   %rbp\n    mov    %rsp, %rbp\n    sub    $16, %rsp         # reserva 16 bytes (alinhamento de 16 exigido antes de calls)\n    mov    %edi, -4(%rbp)    # a\n    mov    %esi, -8(%rbp)    # b\n    mov    -4(%rbp), %edx\n    mov    -8(%rbp), %eax\n    add    %edx, %eax        # eax = a + b\n    mov    %eax, -12(%rbp)   # total\n    mov    -12(%rbp), %eax\n    leave                    # == mov %rbp,%rsp ; pop %rbp\n    ret"}, {"type": "table", "header": ["#", "C++ / instrução", "O que acontece"], "rows": [["1", "`push %rbp` / `mov %rsp, %rbp`", "prólogo padrão: guarda o quadro do chamador e cria o novo."], ["2", "`sub $16, %rsp`", "abre espaço para as variáveis locais movendo `%rsp` para um endereço menor."], ["3", "`int a, int b`", "chegam em `%edi` e `%esi` (convenção da ABI) e são copiados para a pilha."], ["4", "`int total = a + b;`", "vira `add`, com o resultado guardado em outra posição da pilha."], ["5", "`leave`", "uma única instrução que equivale a `mov %rbp, %rsp` seguido de `pop %rbp` — desfaz o quadro de uma vez."], ["6", "`ret`", "desempilha o endereço de retorno (empilhado pelo `call` do chamador) e salta para lá."]]}, {"type": "callout", "variant": "note", "title": "O que é hardware e o que é convenção?", "text": "Em x86-64, `call` empilha o endereço de retorno e `ret` o recupera; `%rsp` é um registrador real. Já “frame” é uma organização criada pelo compilador/ABI. `%rbp` pode ser omitido, variáveis podem viver em registradores e uma função pode sofrer inlining ou tail-call. A norma C++ não exige stack nem crescimento para endereços menores."}, {"type": "paragraph", "text": "O kernel protege o limite com uma guard page ou área equivalente. O acesso à página protegida gera uma exceção de proteção e costuma resultar em `SIGSEGV`. O tamanho nominal da stack de uma thread é principalmente espaço virtual; as páginas físicas são materializadas conforme são tocadas, sujeitas a limites, *overcommit* (o kernel prometer mais memória virtual do que fisicamente garante ter, apostando que nem tudo será usado ao mesmo tempo) e políticas de paginação."}]}, {"type": "subsection", "id": "sec-heap", "number": "5.6", "title": "Monte dinâmico (Heap)", "tag": "HEAP", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Região para alocação sob demanda em tempo de execução (duração dinâmica). Em mapas tradicionais, costuma crescer para **cima**, expandindo seu limite pelo ponteiro **Program Break** (`brk`) ou, para blocos grandes, por `mmap` — ambos geridos pelo kernel e por alocadores como `malloc` ou os operadores do C++."}, {"type": "mermaid", "code": "flowchart LR\n    N(\"operator new(n)\") -->|\"chama\"| M(\"malloc (brk ou mmap)\")\n    M --> B(\"bloco cru no Heap\")\n    B --> CT(\"construtor roda sobre o bloco\")\n    CT --> OBJ(\"objeto pronto\")", "caption": "fluxo simplificado", "accent": "orange"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "Base* obj = new Derivada(1, 100);"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa", "code": "mov    $16, %edi\ncall   operator_new@PLT      # passo 1: aloca 16 bytes crus (não constrói nada ainda)\nmov    %rax, %rbx            # %rbx guarda o endereço bruto\nmov    $1, %esi\nmov    $100, %edx\nmov    %rbx, %rdi            # 1º argumento implícito: this\ncall   _ZN8DerivadaC1Eii     # passo 2: construtor roda sobre o bloco\nmov    %rbx, obj(%rip)"}, {"type": "table", "header": ["#", "C++ / instrução", "O que acontece"], "rows": [["1", "`new Derivada(...)`", "o compilador o desmembra em duas chamadas distintas — nunca é uma operação atômica."], ["2", "`call operator_new@PLT`", "reserva 16 bytes crus no heap (internamente chama `malloc`). `@PLT` é a *Procedure Linkage Table*, o mecanismo que resolve chamadas para funções de bibliotecas compartilhadas."], ["3", "`mov %rbx, %rdi` / `call _ZN8Derivada...`", "o construtor de `Derivada` é chamado com o endereço recém-alocado como ponteiro `this` (ver Seção 6.2) — só agora o objeto passa a existir de fato."], ["4", "`delete obj;` (caminho inverso, não mostrado)", "chama primeiro o destrutor `obj->~T()` e só depois `operator delete(obj)`, que devolve a memória ao heap."]]}, {"type": "callout", "variant": "note", "title": "O caminho real do `new`", "text": "Uma *new-expression* obtém armazenamento por uma allocation function, depois constrói o objeto. Em uma implementação comum, `operator new` chega ao `malloc` da glibc; o allocator pode reutilizar um chunk em uma arena, expandir o program break com `brk`/`sbrk` ou criar uma VMA anônima com `mmap` para pedidos grandes. Isso é Linux/glibc, não uma garantia do C++."}, {"type": "paragraph", "text": "Mesmo depois de `delete`, a RAM não precisa diminuir imediatamente: o destrutor termina a vida do objeto, `operator delete` devolve o bloco ao allocator, e o allocator pode conservar páginas para reutilização. RSS, VmSize e bytes vivos de objetos são medidas diferentes."}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Você viu, região por região, o que cada parte do mapa de endereços da Seção 4 realmente guarda e por quê: `.text` (código, somente leitura), `.rodata`/`.data`/`.bss` (dados conforme inicialização), stack (frames e ponteiro `%rsp`) e heap (alocação sob demanda, `new` como alocação seguida de construção). Essas regiões de baixo nível são a base sobre a qual a Seção 6 constrói o modelo de objetos do C++: membros estáticos vão para `.data`/`.bss` exatamente como descrito aqui, e o `new` de um objeto polimórfico (visto na Seção 5.6) ganha vtable e vptr na Seção 6.3."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "objetos", "number": "6", "title": "O modelo de objetos do C++", "blocks": [{"type": "paragraph", "text": "Há uma diferença de perspectiva entre as duas fontes centrais desta seção: *CS:APP* descreve a memória do ponto de vista de C/binário puro; já **Inside the C++ Object Model** (Stanley B. Lippman) descreve como o compilador traduz classes, herança e polimorfismo sobre essa mesma base. As subseções abaixo seguem essa segunda perspectiva, ancoradas nos mesmos mecanismos de baixo nível já vistos."}, {"type": "subsection", "id": "sec-membros", "number": "6.1", "title": "Membros de dados: estáticos vs. não-estáticos", "tag": "OBJETOS", "accent": "pink", "blocks": [{"type": "paragraph", "text": "Membros não-estáticos ficam dentro do layout físico de cada instância (na Stack ou no Heap). Membros `static` são extraídos do objeto e alocados uma única vez, globalmente, em `.data` (se inicializados com valor ≠ 0) ou `.bss` (caso contrário)."}, {"type": "mermaid", "code": "flowchart LR\n    OBJ(\"cada instância\") --> NS(\"membros não-estáticos: dentro do objeto\")\n    CLS(\"a classe como um todo\") --> S(\"membros static: uma cópia só, em .data/.bss\")", "caption": "fluxo simplificado", "accent": "pink"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "class Contador {\npublic:\n    static int total_instancias;   // não fica dentro do objeto\n    int id;                        // fica dentro de cada objeto\n    Contador() { id = total_instancias++; }\n};\nint Contador::total_instancias = 0;"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa", "code": "    .bss                                 # valor final é 0 → vai para .bss, não .data\n_ZN8Contador16total_instanciasE:\n    .zero 4\n\n_ZN8ContadorC1Ev:                        # construtor Contador::Contador()\n    mov    _ZN8Contador16total_instanciasE(%rip), %eax\n    lea    1(%rax), %edx\n    mov    %edx, _ZN8Contador16total_instanciasE(%rip)  # incrementa o global\n    mov    %rdi, ...                     # this\n    mov    %eax, (%rdi)                  # this->id = valor antigo"}, {"type": "table", "header": ["#", "C++ / instrução", "O que acontece"], "rows": [["1", "`static int total_instancias;`", "não aumenta `sizeof(Contador)` — existe como um único símbolo global."], ["2", "`total_instancias++`", "compila para um incremento direto sobre o endereço global — não há indireção via `this`, ao contrário do que acontece com `id`."], ["3", "`int id;`", "membro não-estático: acessado como `(%rdi)`, ou seja, no deslocamento 0 a partir do ponteiro `this`."]]}]}, {"type": "subsection", "id": "sec-this", "number": "6.2", "title": "O ponteiro `this` e name mangling", "tag": "OBJETOS", "accent": "pink", "blocks": [{"type": "paragraph", "text": "O compilador transforma toda função membro não-estática em uma função livre comum, aplicando **name mangling** (para gerar um símbolo único no linker) e inserindo um primeiro argumento implícito: o ponteiro `this`. Funções membro `static` não recebem `this` (\"this-less\") e por isso não acessam membros não-estáticos diretamente."}, {"type": "mermaid", "code": "flowchart LR\n    CH(\"obj.mover(5)\") --> TR(\"compilador reescreve\")\n    TR --> FN(\"Ponto_mover(&obj, 5)\")", "caption": "fluxo simplificado", "accent": "pink"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "class Ponto {\npublic:\n    int x;\n    void mover(int dx) { x += dx; }\n};\np.mover(5);"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa", "code": "; nome decorado (Itanium C++ ABI): _ZN5Ponto5moverEi\n_ZN5Ponto5moverEi:\n    push   %rbp\n    mov    %rsp, %rbp\n    mov    %rdi, -8(%rbp)    # -8(%rbp) guarda THIS (1º arg. implícito)\n    mov    %esi, -12(%rbp)   # -12(%rbp) guarda dx\n    mov    -8(%rbp), %rax\n    mov    -12(%rbp), %edx\n    mov    (%rax), %ecx      # ecx = this->x (offset 0)\n    add    %edx, %ecx\n    mov    %ecx, (%rax)      # this->x = ecx\n    pop    %rbp\n    ret"}, {"type": "table", "header": ["#", "Elemento", "Significado"], "rows": [["1", "`_Z`", "prefixo que marca um nome decorado pelo compilador (padrão Itanium C++ ABI, usado por GCC e Clang)."], ["2", "`N5PontoE`", "`N...E` delimita um nome aninhado; `5Ponto` é \"tamanho 5 + Ponto\" — permite ao linker reconstituir o nome sem ambiguidade."], ["3", "`5mover` / `i`", "nome do método (com seu tamanho) seguido do código do tipo de cada parâmetro — `i` = `int`. É isso que permite *overload*: `mover(int)` e `mover(double)` geram símbolos diferentes."], ["4", "`%rdi` → `this`", "na chamada `p.mover(5)`, o endereço de `p` vai para o registrador do 1º argumento; `5` vai para o 2º (`%esi`)."], ["5", "`mov (%rax), %ecx`", "acessa `this->x`: como `x` é o primeiro (e único) membro, seu deslocamento dentro do objeto é 0."]]}]}, {"type": "subsection", "id": "sec-vtable", "number": "6.3", "title": "Funções virtuais: Vtable, Vptr e RTTI", "tag": "OBJETOS", "accent": "pink", "blocks": [{"type": "paragraph", "text": "Quando uma classe declara ou herda uma função virtual, uma implementação comum introduz duas peças. A **vtable** é uma estrutura binária associada a uma classe; o **vptr** é um ponteiro oculto no subobjeto polimórfico. Na Itanium C++ ABI, o vptr aponta para um **address point**, isto é, o endereço a partir do qual os slots de funções são indexados. Metadados como `offset-to-top` e `type_info` podem estar em endereços negativos relativos a esse ponto. O padrão C++ não exige nenhuma dessas peças. O **RTTI** (*Run-Time Type Information*) é o mecanismo relacionado que guarda esses metadados de tipo (como `type_info`) e permite consultá-los em tempo de execução via `dynamic_cast` e `typeid`."}, {"type": "mermaid", "code": "flowchart LR\n    O(\"objeto polimórfico\") -->|\"vptr\"| V(\"vtable da classe, em .rodata\")\n    V -->|\"slot da função\"| C(\"código da função, em .text\")", "caption": "fluxo simplificado", "accent": "pink"}, {"type": "heading", "level": 4, "text": "Visualização: layout do objeto + vtable (offsets Itanium ABI)"}, {"type": "svg", "svg": "<svg aria-labelledby=\"vtable-title vtable-desc\" class=\"diagram diagram-vtable\" role=\"img\" viewBox=\"0 0 920 430\" xmlns=\"http://www.w3.org/2000/svg\">\n<title id=\"vtable-title\">Objeto Derivada e grupo de vtable na Itanium C++ ABI</title>\n<desc id=\"vtable-desc\">Dois painéis. À esquerda, um objeto com vptr no offset zero, id_base no offset oito e dado_extra no offset doze. À direita, o address point é marcado em zero; metadados ficam antes dele em offsets negativos e funções virtuais depois dele em offsets positivos. Uma seta liga o vptr ao address point.</desc>\n<defs><marker id=\"vtable-arrow\" markerHeight=\"10\" markerWidth=\"10\" orient=\"auto\" refX=\"9\" refY=\"5\"><path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#f29ac2\"/></marker></defs>\n<rect fill=\"#101820\" height=\"430\" rx=\"14\" width=\"920\" x=\"0\" y=\"0\"/>\n<text fill=\"#f5d7e7\" font-family=\"sans-serif\" font-size=\"19\" font-weight=\"700\" x=\"28\" y=\"36\">Itanium C++ ABI — exemplo didático em x86-64</text>\n<text fill=\"#b9c7d3\" font-family=\"sans-serif\" font-size=\"13\" x=\"28\" y=\"59\">Hipótese: ponteiros de 8 bytes; offsets relativos ao address point da vtable.</text>\n<line stroke=\"#43515d\" stroke-width=\"2\" x1=\"460\" x2=\"460\" y1=\"82\" y2=\"398\"/>\n<text fill=\"#f7e1ef\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"700\" x=\"30\" y=\"91\">objeto Derivada</text>\n<text fill=\"#aebdca\" font-family=\"sans-serif\" font-size=\"12\" x=\"30\" y=\"110\">heap ou stack · layout de um subobjeto</text>\n<rect fill=\"#71345a\" height=\"54\" rx=\"8\" stroke=\"#f29ac2\" stroke-width=\"2\" width=\"370\" x=\"30\" y=\"128\"/>\n<text fill=\"#fff4fa\" font-family=\"monospace\" font-size=\"14\" font-weight=\"700\" x=\"48\" y=\"151\">offset +0</text><text fill=\"#fff4fa\" font-family=\"sans-serif\" font-size=\"14\" x=\"48\" y=\"171\">vptr → address point</text>\n<rect fill=\"#3f4653\" height=\"54\" rx=\"8\" stroke=\"#8695a3\" stroke-width=\"1.5\" width=\"370\" x=\"30\" y=\"190\"/>\n<text fill=\"#edf2f6\" font-family=\"monospace\" font-size=\"14\" x=\"48\" y=\"213\">offset +8</text><text fill=\"#edf2f6\" font-family=\"sans-serif\" font-size=\"14\" x=\"48\" y=\"233\">id_base (Base)</text>\n<rect fill=\"#334b52\" height=\"54\" rx=\"8\" stroke=\"#75d6ca\" stroke-width=\"1.5\" width=\"370\" x=\"30\" y=\"252\"/>\n<text fill=\"#e6fffb\" font-family=\"monospace\" font-size=\"14\" x=\"48\" y=\"275\">offset +12</text><text fill=\"#e6fffb\" font-family=\"sans-serif\" font-size=\"14\" x=\"48\" y=\"295\">dado_extra (Derivada)</text>\n<text fill=\"#aebdca\" font-family=\"sans-serif\" font-size=\"12\" x=\"30\" y=\"335\">O offset +12 é apenas ilustrativo:</text>\n<text fill=\"#aebdca\" font-family=\"sans-serif\" font-size=\"12\" x=\"30\" y=\"353\">padding e alinhamento podem alterar o layout.</text>\n<text fill=\"#c8f4ed\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"700\" x=\"490\" y=\"91\">virtual table de Derivada</text>\n<text fill=\"#aebdca\" font-family=\"sans-serif\" font-size=\"12\" x=\"490\" y=\"110\">grupo em área de dados somente leitura, conforme build</text>\n<rect fill=\"#26343f\" height=\"48\" rx=\"8\" stroke=\"#8fa0ac\" stroke-width=\"1.5\" width=\"390\" x=\"490\" y=\"124\"/>\n<text fill=\"#d7e1e9\" font-family=\"monospace\" font-size=\"13\" x=\"508\" y=\"145\">offset -16</text><text fill=\"#d7e1e9\" font-family=\"sans-serif\" font-size=\"13\" x=\"508\" y=\"163\">vbase/vcall offsets, se necessários</text>\n<rect fill=\"#26343f\" height=\"48\" rx=\"8\" stroke=\"#8fa0ac\" stroke-width=\"1.5\" width=\"390\" x=\"490\" y=\"178\"/>\n<text fill=\"#d7e1e9\" font-family=\"monospace\" font-size=\"13\" x=\"508\" y=\"199\">offset -8</text><text fill=\"#d7e1e9\" font-family=\"sans-serif\" font-size=\"13\" x=\"508\" y=\"217\">offset-to-top e type_info</text>\n<rect fill=\"#0d8f83\" height=\"56\" rx=\"8\" stroke=\"#9be8dc\" stroke-width=\"2\" width=\"390\" x=\"490\" y=\"232\"/>\n<text fill=\"#06231f\" font-family=\"monospace\" font-size=\"13\" font-weight=\"700\" x=\"508\" y=\"254\">address point = 0</text><text fill=\"#06231f\" font-family=\"sans-serif\" font-size=\"13\" x=\"508\" y=\"274\">vptr aponta aqui; slot virtual começa aqui</text>\n<rect fill=\"#176e68\" height=\"48\" rx=\"8\" stroke=\"#75d6ca\" stroke-width=\"1.5\" width=\"390\" x=\"490\" y=\"294\"/>\n<text fill=\"#e6fffb\" font-family=\"monospace\" font-size=\"13\" x=\"508\" y=\"315\">offset +8</text><text fill=\"#e6fffb\" font-family=\"sans-serif\" font-size=\"13\" x=\"508\" y=\"333\">Derivada::~Derivada() / variante ABI</text>\n<rect fill=\"#176e68\" height=\"48\" rx=\"8\" stroke=\"#75d6ca\" stroke-width=\"1.5\" width=\"390\" x=\"490\" y=\"348\"/>\n<text fill=\"#e6fffb\" font-family=\"monospace\" font-size=\"13\" x=\"508\" y=\"369\">offset +16</text><text fill=\"#e6fffb\" font-family=\"sans-serif\" font-size=\"13\" x=\"508\" y=\"387\">Derivada::processar()</text>\n<path d=\"M400,154 C440,154 442,258 490,258\" fill=\"none\" marker-end=\"url(#vtable-arrow)\" stroke=\"#f29ac2\" stroke-width=\"3\"/>\n<text fill=\"#f5c2dc\" font-family=\"sans-serif\" font-size=\"12\" font-weight=\"700\" text-anchor=\"middle\" x=\"433\" y=\"150\">vptr</text>\n</svg>", "alt": "Objeto Derivada à esquerda e virtual table à direita; o vptr aponta para o address point zero, enquanto metadados aparecem antes dele em offsets negativos."}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "struct Base {\n    virtual ~Base() {}\n    virtual void processar() { /*...*/ }\n};\nstruct Derivada : Base {\n    void processar() override { /*...*/ }\n};\nBase* p = new Derivada();\np->processar();   // chamada virtual"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa da chamada virtual", "code": "mov    (%rdi), %rax     # rax = vptr; this está em rdi\nmov    16(%rax), %rax    # exemplo: slot processar no address point +16\ncall   *%rax             # chamada indireta; slot exato depende da tabela/ABI"}, {"type": "table", "header": ["#", "Instrução", "O que acontece"], "rows": [["1", "`mov (%rdi), %rax`", "lê o *vptr*, que está no offset 0 do objeto — carrega o endereço da vtable de `Derivada`."], ["2", "`mov 16(%rax), %rax`", "O deslocamento é relativo ao address point e depende da ordem/entradas da tabela adotada. Não trate um único +16 como universal."], ["3", "`call *%rax`", "chamada indireta: o endereço de destino só é conhecido em tempo de execução — é isso que implementa o despacho dinâmico do polimorfismo."]]}, {"type": "callout", "variant": "info", "title": "Nota de precisão (Itanium C++ ABI)", "text": "Na especificação real, o vptr aponta para o **address point** da tabela, não necessariamente para seu primeiro byte. Entradas de metadados e offsets associados à hierarquia podem estar em posições negativas; slots de funções aparecem a partir do address point conforme o grupo de vtable. A ordem e a quantidade de entradas dependem da Itanium ABI e da classe concreta. Este desenho é uma leitura rotulada de uma implementação, não um layout imposto pelo C++."}]}, {"type": "subsection", "id": "sec-init", "number": "6.4", "title": "Construtores e inicialização estática", "tag": "OBJETOS", "accent": "pink", "blocks": [{"type": "paragraph", "text": "Para que a vtable já esteja pronta na primeira instrução do construtor do usuário, o compilador insere código adicional — termo de Lippman para esse trecho sintetizado, chamado de *augmentation* — logo após os construtores das classes-base: ele atribui o *vptr* do objeto antes de qualquer outra coisa. Para objetos **globais**, essa construção precisa acontecer antes de `main()` — via as seções especiais `.init_array`/`.fini_array` do ELF."}, {"type": "mermaid", "code": "flowchart TD\n    ST(\"antes de main()\") --> IA(\"runtime percorre .init_array\")\n    IA --> CT(\"construtores dos objetos globais executam\")\n    CT --> MN(\"main() executa\")\n    MN --> FA(\"ao sair: runtime percorre .fini_array\")\n    FA --> DT(\"destrutores dos objetos globais executam\")", "caption": "fluxo simplificado", "accent": "pink"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "struct Logger { Logger() { /* abre arquivo de log */ } };\nLogger g_logger;   // objeto global com construtor"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa", "code": "_GLOBAL__sub_I_arquivo.cpp:      # função geradora de inicialização estática\n    lea    g_logger(%rip), %rdi\n    call   _ZN6LoggerC1Ev        # Logger::Logger()\n    ret\n\n    .section .init_array,\"aw\"\n    .quad   _GLOBAL__sub_I_arquivo.cpp   # entra num ARRAY de ponteiros de função"}, {"type": "table", "header": ["#", "Elemento", "O que acontece"], "rows": [["1", "`Logger g_logger;`", "como é global e tem construtor não-trivial, o compilador não pode simplesmente gravar bytes em `.data` — precisa de código executado em tempo de carregamento."], ["2", "`_GLOBAL__sub_I_...`", "função sintetizada pelo compilador que chama o construtor de cada objeto global daquele arquivo-fonte."], ["3", "`.init_array`", "um *array* de ponteiros de função em `.data`/`.rodata`; o runtime do C (`crt1.o`) percorre esse array chamando cada entrada antes de saltar para `main()`."], ["4", "saída do programa", "`__cxa_atexit` registra o destrutor correspondente, disparado via `.fini_array` quando o processo termina."]]}]}, {"type": "subsection", "id": "sec-newdelete", "number": "6.5", "title": "`new`/`delete` vs. Placement `new`", "tag": "OBJETOS", "accent": "pink", "blocks": [{"type": "paragraph", "text": "Como já visto na Seção 5.6, `new T(args)` não é uma operação única — é **alocação** seguida de **construção**. O **Placement new** quebra esse par deliberadamente: recebe um ponteiro para memória *já existente* (na pilha, no heap ou em `.data`) e aplica só o construtor, sem alocar nada."}, {"type": "mermaid", "code": "flowchart LR\n    PN(\"placement new(ptr) T(args)\") --> SK(\"NÃO chama operator new\")\n    SK --> CT2(\"chama só o construtor, direto sobre ptr\")", "caption": "fluxo simplificado", "accent": "pink"}, {"type": "code", "language": "cpp", "title": "Código C++", "code": "alignas(Ponto) char buffer[sizeof(Ponto)];  // memória crua na stack\nPonto* p = new (buffer) Ponto();            // placement new"}, {"type": "code", "language": "asm", "title": "Tradução ilustrativa", "code": "lea    buffer(%rbp), %rdi   # this = endereço do buffer (já existe, na stack)\ncall   _ZN5PontoC1Ev        # só o construtor — repare: NENHUM call a operator_new@PLT\nlea    buffer(%rbp), %rax\nmov    %rax, p(%rbp)"}, {"type": "table", "header": ["#", "Instrução", "O que acontece"], "rows": [["1", "`char buffer[sizeof(Ponto)]`", "reserva bytes crus, aqui na stack (poderia ser heap ou `.data`)."], ["2", "`lea buffer(%rbp), %rdi`", "o endereço do buffer vira diretamente o `this` passado ao construtor."], ["3", "ausência de `call operator_new@PLT`", "é exatamente essa chamada que falta, comparado à Seção 5.6 — a diferença central entre `new` comum e *placement new*."]]}]}, {"type": "subsection", "id": "sec-competitive", "number": "6.6", "title": "Perspectiva da programação competitiva", "tag": "OBJETOS", "accent": "pink", "blocks": [{"type": "paragraph", "text": "Segundo o *Guia do Programador Competitivo* (Antti Laaksonen), a escolha entre Stack e Heap pode afetar a performance de código compilado com `-O2`. Estruturas estáticas (globais em `.bss`/`.data`, ou arrays na Stack) evitam a sobrecarga de chamadas repetidas ao alocador do heap — por isso é comum, em competições, declarar arrays globais de tamanho fixo em vez de `std::vector` alocado dinamicamente dentro de laços quentes. Isso não introduz um mecanismo de memória novo: é uma aplicação direta do que as Seções 5.1–5.6 já mostraram."}, {"type": "code", "language": "cpp", "title": "Alocação repetida dentro do laço (evite em código quente)", "code": "for (int caso = 0; caso < q; ++caso) {\n    int n; std::cin >> n;\n    std::vector<int> buffer(n);   // aloca no heap A CADA iteração\n    for (int i = 0; i < n; ++i) std::cin >> buffer[i];\n    resolver(buffer);\n}   // destrutor de buffer libera no heap A CADA iteração", "highlight": "", "lineNumbers": false}, {"type": "code", "language": "cpp", "title": "Buffer global reutilizado (idiomático em programação competitiva)", "code": "constexpr int MAXN = 200000;\nstd::array<int, MAXN> buffer;   // .bss: uma única alocação, tempo de vida do programa\n\nfor (int caso = 0; caso < q; ++caso) {\n    int n; std::cin >> n;\n    for (int i = 0; i < n; ++i) std::cin >> buffer[i];\n    resolver(buffer.data(), n);\n    // nada é alocado nem liberado entre os casos\n}", "highlight": "", "lineNumbers": false}, {"type": "table", "caption": "Custo de cada abordagem, em termos já vistos nas Seções 5.5–5.6", "header": ["#", "Trecho", "O que acontece"], "rows": [["1", "`std::vector<int> buffer(n);` dentro do laço", "chama `operator new` (Seção 5.6) a cada iteração — o alocador busca um bloco livre, possivelmente expandindo o heap com `brk`/`mmap`."], ["2", "fim do escopo do laço", "o destrutor de `buffer` chama `operator delete`; o bloco volta ao alocador, mas a página física não é necessariamente devolvida ao kernel (Seção 5.6)."], ["3", "`std::array<int, MAXN> buffer;` global", "vai para `.bss` (Seção 5.4) — uma única reserva de espaço, resolvida no carregamento do processo, sem nenhuma chamada a alocador em tempo de execução."], ["4", "laço reutilizando o buffer global", "cada iteração apenas sobrescreve posições já existentes na Stack/`.bss`; não há `call operator_new@PLT` nem `call operator_delete` repetidos."]]}, {"type": "callout", "variant": "tip", "title": "Quando isso importa de verdade", "text": "A diferença só é relevante quando o laço é **quente** — milhares de casos de teste ou uma DP com milhões de estados. Para poucas iterações, o custo de `operator new`/`operator delete` é irrelevante perto do resto do programa; otimizar isso cedo demais troca legibilidade por um ganho que não existe na prática. Meça antes de reescrever."}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "O modelo de objetos do C++ foi traduzido para os mecanismos de baixo nível já vistos: membros estáticos reaparecem em `.data`/`.bss` (Seção 5.3/5.4), o ponteiro `this` é o mesmo tipo de argumento implícito que a ABI já usava para passar parâmetros (Seções 1 e 3), e a chamada virtual é uma leitura de memória seguida de `call` indireto sobre a base explicada na Seção 5. A Seção 7 mostra como toolchains modernas endurecem exatamente esses pontos — vtable, heap e stack — contra ataques."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "modernizacoes", "number": "7", "title": "Modernizações e complementos atuais", "blocks": [{"type": "paragraph", "text": "O texto original desta referência segue de perto CS:APP e o livro de Lippman (1996). Desde então, toolchains passaram a combinar PIE, ASLR, proteções de fluxo de controle e novos recursos da linguagem. Esta seção atualiza o mapa sem transformar uma configuração comum em regra universal: flags, distribuição Linux, arquitetura e versão do compilador podem mudar o resultado."}, {"type": "mermaid", "code": "flowchart TD\n    BIN(\"Binário compilado hoje\") --> ASLR(\"ASLR + PIE: bases de carregamento aleatórias\")\n    BIN --> CAN(\"Stack canary: detecta overflow antes do ret\")\n    BIN --> REL(\"RELRO: GOT marcado somente-leitura após o linking\")\n    BIN --> CET(\"Intel CET / ARM PAC: shadow stack + branch tracking em hardware\")", "caption": "visão geral das mitigações modernas de memória", "accent": "orange"}, {"type": "heading", "level": 3, "text": "Sobre a Seção 5 (ELF) — PIE e ASLR"}, {"type": "paragraph", "text": "Desde por volta de 2017, GCC e Clang geram executáveis **PIE** (*Position-Independent Executable*) por padrão na maioria das distribuições Linux. Isso significa que `.text`, `.rodata`, `.data` e `.bss` — todo aquele bloco fixo do mapa de endereços da Seção 5 — carrega em uma **base aleatória** a cada execução (parte do **ASLR**, *Address Space Layout Randomization*), junto com a base do heap e da stack. O antigo endereço fixo `0x400000` só aparece hoje em binários não-PIE."}, {"type": "heading", "level": 3, "text": "Sobre a Seção 5.5 (Stack) — canário e Shadow Stack"}, {"type": "paragraph", "text": "Compiladores modernos (com `-fstack-protector-strong`, padrão em várias distros) inserem um valor aleatório — o **canário de pilha** — entre as variáveis locais e o `%rbp`/endereço de retorno salvos. Antes do `ret`, o valor é conferido; se um *buffer overflow* o corrompeu, o programa aborta em vez de saltar para um endereço controlado pelo atacante. Em hardware recente, o **Intel CET** (desde a geração Tiger Lake) adiciona uma **Shadow Stack**: uma cópia dos endereços de retorno mantida pelo próprio processador, verificada em todo `ret` — mesma ideia do canário, mas aplicada em hardware. Em ARM64, **Pointer Authentication (PAC)** cumpre um papel equivalente, assinando criptograficamente o endereço de retorno."}, {"type": "heading", "level": 3, "text": "Sobre a Seção 5.6 (Heap) — RELRO e a PLT/GOT"}, {"type": "paragraph", "text": "A chamada `operator_new@PLT` da Seção 5.6 passa por duas tabelas: a **PLT** (*Procedure Linkage Table*, em `.text`) e a **GOT** (*Global Offset Table*, que guarda os endereços reais resolvidos pelo linker dinâmico). Com **RELRO** total (*RELocation Read-Only*, padrão em builds modernos), a GOT é marcada somente-leitura logo depois de resolvida — fechando uma classe inteira de ataques que sobrescreviam entradas da GOT para sequestrar chamadas de função."}, {"type": "heading", "level": 3, "text": "Sobre a Seção 6.3 (Vtable) — CET/IBT contra sequestro de vtable"}, {"type": "paragraph", "text": "A chamada indireta `call *%rax` usada no despacho virtual é justamente o tipo de instrução que ataques de *vtable hijacking* exploram (sobrescrever o *vptr* de um objeto para apontar para uma vtable forjada). O componente **IBT** (*Indirect Branch Tracking*) do Intel CET exige que todo alvo válido de `call`/`jmp` indireto comece com uma instrução especial (`ENDBR64`); qualquer outro destino gera uma falha de proteção — uma defesa de hardware específica para esse padrão de ataque."}, {"type": "heading", "level": 3, "text": "Sobre a Seção 6.1/6.3 — layout de objeto e cache"}, {"type": "paragraph", "text": "C++17 introduziu `std::hardware_destructive_interference_size`, uma constante que expõe o tamanho típico de linha de cache do processador-alvo. Programadores de alto desempenho a usam para preencher (*pad*) o layout de uma classe deliberadamente, evitando que dois membros não-estáticos de threads diferentes caiam na mesma linha de cache (*false sharing*) — uma extensão direta da discussão de layout da Seção 6.1."}, {"type": "heading", "level": 3, "text": "Sobre a Seção 6.5 (new/delete) — pmr e coroutines"}, {"type": "paragraph", "text": "C++17 trouxe `std::pmr` (*polymorphic memory resources*): uma forma padronizada de redirecionar onde `new` efetivamente aloca — por exemplo, um `std::pmr::monotonic_buffer_resource` sobre um buffer na stack — sem escrever *placement new* manualmente toda vez."}, {"type": "paragraph", "text": "C++20 introduziu **coroutines**, que precisam de um \"quadro de coroutine\" guardando variáveis locais e o estado de suspensão entre retomadas. Por padrão, esse quadro é alocado no **heap** via `operator new` — um quadro de armazenamento associado à coroutine, mas não uma nova categoria de *storage duration*. Compiladores modernos podem aplicar **HALO** (*Heap Allocation eLision Optimization*): quando provam que o tempo de vida da coroutine está inteiramente contido no do chamador, o quadro pode ser colocado na *stack* do chamador — a alocação no heap simplesmente some, sem qualquer mudança no código-fonte."}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Esta seção atualizou, mitigação por mitigação, cada mecanismo apresentado nas Seções 3, 5 e 6: PIE/ASLR alteram o mapa fixo de endereços da Seção 5, o canário e a Shadow Stack protegem o quadro de pilha da Seção 5.5, RELRO protege a GOT/PLT do heap explicado na Seção 5.6, e o CET/IBT defende exatamente a chamada indireta da vtable vista na Seção 6.3. As novidades de linguagem (`pmr`, coroutines) mostram que até mecanismos modernos do C++20 continuam se apoiando na mesma distinção entre stack e heap ensinada desde a Seção 2 — a próxima seção fecha o livro com uma síntese intuitiva de todo esse percurso."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "resumo", "number": "8", "title": "Resumo intuitivo", "blocks": [{"type": "paragraph", "text": "A analogia do edifício ajuda a organizar o mapa, mas não substitui o modelo real: o processo enxerga endereços virtuais, e o sistema operacional pode reservar, remapear ou paginar regiões conforme a execução. Com essa ressalva, pense na memória do programa como um edifício de vários andares. No térreo fica o arquivo com o manual de instruções imutável que todo funcionário segue (`.text`). Nos andares seguintes há murais fixos com informações que nunca mudam ou que já chegam prontas (`.rodata` e `.data`) — e uma sala cujo conteúdo o zelador simplesmente zera todo dia de manhã, sem precisar de nenhum arquivo com instruções para isso (`.bss`). No topo do prédio há uma sala de arquivo temporário que cresce e esvazia rapidamente conforme as tarefas do dia chegam e terminam (a *Stack*). Em outro andar, um depósito expansível guarda materiais pedidos sob demanda durante o expediente (o *Heap*). Quando o C++ cria um objeto complexo com funções virtuais, ele guarda as peças do objeto no depósito e entrega ao funcionário uma ficha (o *vptr*) que aponta exatamente para a prateleira certa — a vtable — onde estão as instruções de qual ferramenta usar para cada tarefa daquele objeto específico."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "exercicios", "number": "9", "title": "Laboratório e exercícios de integração", "blocks": [{"type": "paragraph", "lead": true, "text": "Os exercícios seguem a mesma progressão do livro: primeiro observe uma implementação, depois explique-a, e só então generalize. Em cada resposta, declare alvo, compilador, flags, ABI e o que é garantia do C++. Uma saída de ferramenta é evidência sobre um build, não uma lei universal."}, {"type": "subsection", "id": "ex-montagem", "number": "9.1", "title": "Do fonte ao símbolo", "tag": "PRÁTICA", "accent": "blue", "blocks": [{"type": "code", "language": "cpp", "title": "arquivos", "code": "// add.cpp\nextern \"C\" int add(int a, int b) { return a + b; }\n\n// main.cpp\nextern \"C\" int add(int, int);\nint main() { return add(20, 22) != 42; }"}, {"type": "steps", "items": [{"title": "Pare no pré-processador", "text": "Execute `g++ -E -P main.cpp -o main.i` e explique por que a declaração de `add` não foi resolvida nessa etapa."}, {"title": "Observe o assembly", "text": "Execute `g++ -S -O0 -fno-asynchronous-unwind-tables main.cpp` e identifique argumentos, retorno, `call` e relocação provável."}, {"title": "Observe o objeto", "text": "Compile com `-c` e use `readelf -s -r main.o`; localize o símbolo indefinido e a relocation da chamada."}, {"title": "Linke e compare", "text": "Use `g++ main.o add.o -o app`, depois `readelf -l -d app`; explique por que o executável pode ter segmentos sem seção equivalente."}]}, {"type": "callout", "variant": "example", "title": "Resposta esperada", "text": "A resposta deve distinguir declaração de definição, símbolo, relocation e endereço final. Não basta dizer que o compilador “acha” a função: o assembler preserva a referência e o linker a resolve conforme a ABI e o formato ELF."}]}, {"type": "subsection", "id": "ex-objeto", "number": "9.2", "title": "Layout, lifetime e chamada virtual", "tag": "C++ ABI", "accent": "pink", "blocks": [{"type": "code", "language": "cpp", "title": "Experimento", "code": "struct Base { virtual ~Base() = default; virtual int f() const { return 1; } int b = 7; };\nstruct Derived : Base { int d = 9; int f() const override { return 2; } };\nint run(const Base& x) { return x.f(); }"}, {"type": "list", "style": "number", "items": ["Compile com `-std=c++20 -O0 -g -fdump-lang-class` quando o compilador oferecer a opção e compare `sizeof`, `alignof` e `offsetof` apenas para membros permitidos.", "Inspecione `nm -C`, `readelf -s` e `objdump -drwC` para localizar símbolos de `f`, destrutores e tabelas.", "Desenhe o objeto separando subobjeto `Base`, membro `b`, membro `d`, vptr e address point. Marque o desenho como hipótese Itanium ABI, não como regra ISO.", "Explique por que a herança múltipla pode exigir ajuste de `this` (o endereço do subobjeto-base pode diferir do endereço do objeto completo) e um *thunk* (uma pequena rotina gerada pelo compilador que corrige esse deslocamento antes de saltar para a função real), e por que uma chamada pode ser devirtualizada com otimização (o compilador prova em tempo de compilação qual implementação será chamada e substitui a chamada indireta por uma chamada direta)."]}, {"type": "callout", "variant": "warning", "title": "Limite do experimento", "text": "Não leia um suposto vptr com `reinterpret_cast` em código de produção. O experimento serve para observar uma ABI conhecida; aliasing, lifetime e layout de classes continuam sendo regras específicas."}]}, {"type": "subsection", "id": "ex-combinatoria", "number": "9.3", "title": "Enumeração de estados e complexidade", "tag": "COMBINATÓRIA", "accent": "teal", "blocks": [{"type": "paragraph", "text": "Projete uma programação dinâmica para o problema do caixeiro viajante com `n` cidades usando um estado `(mask, last)`. Prove que existem `n·2^n` estados no pior caso. Depois escreva um enumerador de subconjuntos e meça o ponto em que memória, cache e tempo tornam o método inviável."}, {"type": "code", "language": "cpp", "title": "Subconjuntos de um conjunto", "code": "for (std::uint64_t mask = 0; mask < (1ULL << n); ++mask) {\n    for (std::uint64_t bits = mask; bits; bits &= bits - 1) {\n        unsigned i = std::countr_zero(bits);\n        // elemento i pertence ao subconjunto\n    }\n}"}, {"type": "table", "header": ["Questão", "O que deve aparecer na solução"], "rows": [["Por que `mask` representa um subconjunto?", "Cada bit indica presença ou ausência de um elemento; isso requer n dentro da largura do tipo."], ["Qual a complexidade?", "Há `2^n` máscaras e, ao iterar bits, custo total proporcional à soma dos tamanhos dos subconjuntos."], ["Onde entra a memória?", "Tabela DP pode ter `n·2^n` valores; layout e localidade afetam tempo além da notação assintótica."], ["Qual risco C++?", "`1ULL << n` é inválido ou inadequado quando n excede a largura; contagens e índices precisam de limites explícitos."]]}]}, {"type": "subsection", "id": "ex-revisao", "number": "9.4", "title": "Checklist de revisão técnica", "tag": "AUTORREVISÃO", "accent": "orange", "blocks": [{"type": "list", "style": "check", "items": ["Defini todos os termos técnicos na primeira ocorrência e mantive a sigla acompanhada do nome completo?", "Separei máquina abstrata C++ de ABI, ISA, ELF, libc, linker e microarquitetura?", "Expliquei cada instrução assembly do exemplo: operandos, tamanho, endereço efetivo, flags e efeito na pilha?", "Declare o alvo e a sintaxe assembly quando mostrei offsets, registradores ou vtable?", "Diferenciei seção de segmento ELF, linker de loader e símbolo de endereço final?", "Nos diagramas, evitei arestas complexas e rótulos longos que quebram Mermaid?", "Toda afirmação de complexidade (número de estados, Big-O) foi deduzida, não apenas citada?", "Os exercícios pedem prova ou observação, em vez de apenas repetir uma definição?", "As referências estão na seção final com URLs autoritativas e citações numeradas?"]}]}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "glossario", "number": "10", "title": "Glossário, mapa de camadas e autorrevisão", "blocks": [{"type": "paragraph", "text": "Use este glossário como índice de retorno. Cada termo informa a camada em que a palavra faz sentido: **C++** (semântica portátil), **ABI/ELF** (contrato binário), **ISA** (instruções visíveis) ou **SO/hardware** (implementação de execução)."}, {"type": "table", "header": ["Termo", "Definição sem pressupor conhecimento anterior", "Camada"], "rows": [["ABI", "Application Binary Interface: contrato de chamadas, registradores, alinhamento, layout, símbolos, exceções e formato que permite componentes binários cooperarem.", "ABI"], ["ISA", "Instruction Set Architecture: conjunto de instruções, registradores arquiteturais, modos de endereçamento e efeitos visíveis ao software.", "ISA"], ["microarquitetura", "Implementação interna de uma ISA, incluindo pipeline, unidades de execução, caches, predição e renomeação.", "hardware"], ["unidade de tradução", "Resultado lógico das fases de tradução que o compilador analisa; costuma nascer de um `.cpp` após includes e macros.", "C++/toolchain"], ["relocation", "Registro que instrui linker ou dynamic linker a preencher um campo com fórmula dependente de símbolo e endereço.", "ELF"], ["segmento ELF", "Agrupamento descrito por program headers para criar mapeamentos em memória; não é sinônimo de seção.", "ELF/SO"], ["TLB", "Translation Lookaside Buffer: cache de traduções de páginas virtuais para frames físicos.", "hardware/SO"], ["lifetime", "Intervalo em que um objeto C++ existe como objeto de seu tipo; não é sinônimo de morar na stack.", "C++"], ["vptr/vtable", "Implementação comum de despacho virtual: ponteiro oculto e tabela binária. A posição exata pertence à ABI, não ao padrão.", "C++/ABI"], ["RTTI", "Run-Time Type Information: metadados (como `type_info`) que permitem consultar o tipo dinâmico de um objeto polimórfico em tempo de execução, usados por `dynamic_cast` e `typeid`.", "C++/ABI"], ["address point", "Endereço dentro de uma vtable para o qual o vptr aponta na Itanium ABI; metadados podem precedê-lo.", "ABI"], ["comportamento indefinido", "Situação em que a norma C++ não impõe requisitos; o compilador pode assumir que ela não ocorre.", "C++"], ["data race", "Acessos conflitantes não atômicos entre threads sem sincronização; em C++ resulta em comportamento indefinido.", "C++"]]}, {"type": "callout", "variant": "key", "title": "Perguntas para cada exemplo", "text": "Qual é a especificação que garante esta afirmação? O C++ exige isso, ou é a ABI? Estou descrevendo um segmento ou uma seção? O linker já decidiu o endereço, ou o loader ainda aplicará relocations? O diagrama mostra um address point ou o começo físico da tabela?"}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "referencias", "number": "11", "title": "Referências", "blocks": [{"type": "paragraph", "text": "As referências são pontos de verificação, não decoração. Para reproduzir um exemplo, registre compilador, versão, alvo, flags, linker e biblioteca. A saída de `readelf`, `objdump` e do assembly produzido pelo seu build tem precedência para aquele artefato."}, {"type": "list", "style": "bullet", "items": ["[C++ working draft — fases de tradução e memória](https://eel.is/c++draft/lex.phases) — especificação da linguagem.", "[C++ working draft — objetos, classes virtuais e lifetime](https://eel.is/c++draft/intro.object) — semântica portátil.", "[Intel 64 and IA-32 Architectures Software Developer Manuals](https://www.intel.com/content/www/us/en/developer/articles/technical/intel-sdm.html) — ISA, instruções e sistema.", "[AMD64 Architecture Programmer’s Manual](https://www.amd.com/system/files/TechDocs/24592.pdf) — arquitetura x86-64.", "[System V AMD64 ABI](https://gitlab.com/x86-psABIs/x86-64-ABI) — calling convention e ELF para x86-64.", "[ELF specification](https://refspecs.linuxfoundation.org/elf/elf.pdf) — formato, seções, segmentos e símbolos.", "[GCC overall options](https://gcc.gnu.org/onlinedocs/gcc/Overall-Options.html) — `-E`, `-S`, `-c`, LTO e driver.", "[GNU Binutils assembler](https://sourceware.org/binutils/docs/as.html) e [linker](https://sourceware.org/binutils/docs/ld.html) — montagem e linkagem.", "[Itanium C++ ABI](https://itanium-cxx-abi.github.io/cxx-abi/abi.html) — mangling, objetos, vtables, RTTI e exceções.", "[cppreference: virtual functions](https://en.cppreference.com/w/cpp/language/virtual) — polimorfismo e regras da linguagem.", "[OSTEP: Paging](https://pages.cs.wisc.edu/~remzi/OSTEP/vm-paging.pdf) — páginas, TLB e memória virtual.", "[Linux man-pages: ld.so](https://man7.org/linux/man-pages/man8/ld.so.8.html) — dynamic linker e busca de bibliotecas.", "[CS:APP](https://csapp.cs.cmu.edu/) — visão de sistemas e ligação de arquivos objeto."]}, {"type": "paragraph", "text": "A ordem de leitura recomendada é: fundamentos → visão geral → toolchain → pipeline → regiões → objetos/ABI → modernizações → resumo → exercícios → glossário."}]}], "imageRights": {"images/history-stroustrup.jpg": {"source": "Busca de imagens na internet; página de origem registrada no relatório de revisão", "license": "Direitos não determinados na fonte de busca; substituir antes de publicação comercial", "credit": "Fonte de imagem consultada", "retrievedAt": "2026-09-24"}}}, "combinatoria-computacao": {"manifest": {"schema": "books.package.v2", "kind": "book-package", "id": "combinatoria-computacao", "title": "Combinatória: fundamentos, provas e aplicações em computação", "description": "Percurso completo da combinatória elementar à universitária avançada, com definições, fórmulas provadas passo a passo, recorrências, grafos, probabilidade, algoritmos, simetria e exercícios.", "language": "pt-BR", "tags": ["combinatória", "matemática discreta", "algoritmos", "grafos", "probabilidade", "provas"], "header": "header.json", "sections": ["sections/fundamentos.json", "sections/permutacoes-combinacoes.json", "sections/provas-recorrencias.json", "sections/funcoes-geradoras.json", "sections/grafos-arvores.json", "sections/probabilidade.json", "sections/algoritmos-combinatoria.json", "sections/topicos-avancados.json", "sections/exercicios.json", "sections/referencias.json"]}, "header": {"schema": "books.header.v2", "kind": "book-header", "kicker": "livro técnico · matemática discreta / ciência da computação", "title": "Combinatória: fundamentos, provas e aplicações em computação", "subtitle": "Do primeiro princípio de contagem às estruturas e algoritmos de nível universitário", "guideTitle": "Como usar este livro", "guideText": "Leia em ordem. Cada fórmula é precedida por uma definição e seguida por uma prova passo a passo. Resolva os exercícios escrevendo o universo contado e verificando as hipóteses antes de substituir números.", "cover": {"src": "cover.jpg", "alt": "Capa abstrata com árvores, conjuntos e símbolos de contagem.", "ratio": "16:9"}, "legend": [{"label": "provas", "color": "blue"}, {"label": "grafos", "color": "teal"}, {"label": "probabilidade", "color": "orange"}], "footer": "Livro técnico em português; notação e hipóteses devem ser lidas junto das provas.", "id": "combinatoria-computacao-header"}, "sections": [{"schema": "books.section.v2", "kind": "book-section", "id": "fundamentos", "number": "1", "title": "Fundamentos: conjuntos, lógica e modelos de contagem", "blocks": [{"type": "paragraph", "text": "Combinatória estuda estruturas discretas: objetos que podem ser separados em casos, posições, relações ou estados. A pergunta “quantos?” só tem uma resposta quando o universo, a identidade dos objetos e as regras de equivalência estão definidos. Este livro começa com conjuntos e termina em aplicações de nível universitário, sempre provando as fórmulas antes de usá-las.", "lead": true}, {"type": "callout", "variant": "definition", "title": "Como ler uma afirmação combinatória", "text": "Em cada resultado, declare o conjunto contado, a função que representa uma configuração e se duas configurações são consideradas iguais. Ordem, repetição, simetria e restrições não são detalhes: são parte da definição."}, {"type": "subsection", "id": "comb-conjuntos", "number": "1.1", "title": "Conjuntos, funções e cardinalidade", "tag": "BASE", "accent": "blue", "blocks": [{"type": "paragraph", "text": "Um **conjunto** é uma coleção em que a pertinência é a única informação relevante. Uma **sequência** preserva posições e pode repetir elementos. Uma **função** associa cada elemento do domínio a exatamente um elemento do contradomínio. Para conjuntos finitos, a cardinalidade `|A|` é o número de elementos."}, {"type": "heading", "level": 3, "text": "Teorema: regra da soma"}, {"type": "paragraph", "text": "Se `A` e `B` são conjuntos finitos e disjuntos, então $|A \\cup B| = |A| + |B|$."}, {"type": "steps", "items": [{"title": "Passo 1 — particionar", "text": "Como $A \\cap B = \\varnothing$, cada elemento de $A \\cup B$ pertence a exatamente um dos dois conjuntos."}, {"title": "Passo 2 — construir a contagem", "text": "Liste primeiro todos os elementos de `A` e depois todos os elementos de `B`. Nenhum elemento aparece duas vezes."}, {"title": "Passo 3 — contar posições", "text": "A lista tem `|A|` posições vindas de `A` e `|B|` posições vindas de `B`; portanto tem `|A|+|B|` posições."}, {"title": "Conclusão", "text": "Como a lista contém cada elemento da união exatamente uma vez, $|A \\cup B|=|A|+|B|$."}]}, {"type": "heading", "level": 3, "text": "Teorema: regra do produto"}, {"type": "paragraph", "text": "Se uma configuração é formada por uma escolha em `A` seguida de uma escolha em `B`, então o número de configurações é $|A|\\cdot|B|$."}, {"type": "steps", "items": [{"title": "Passo 1 — representar", "text": "Represente cada configuração por um par ordenado `(a,b)`, com $a\\in A$ e $b\\in B$."}, {"title": "Passo 2 — contar para cada primeiro componente", "text": "Para cada um dos `|A|` valores de `a`, existem exatamente `|B|` escolhas de `b`."}, {"title": "Passo 3 — somar blocos iguais", "text": "Há `|A|` blocos, cada um com `|B|` pares. Pela regra da soma, o total é `|A|` repetido `|B|` vezes, isto é, $|A|\\cdot|B|$."}, {"title": "Conclusão", "text": "A correspondência entre configurações e pares é bijetiva; logo a fórmula conta exatamente as configurações."}]}, {"type": "math", "tex": "\\lvert A \\times B\\rvert = \\lvert A\\rvert\\,\\lvert B\\rvert", "caption": "cardinalidade do produto cartesiano"}, {"type": "paragraph", "text": "**Leitura da fórmula.** Leitura: o número de elementos do produto cartesiano de A e B é igual ao número de elementos de A multiplicado pelo número de elementos de B."}, {"type": "table", "header": ["Estrutura", "Ordem importa?", "Repetição?", "Exemplo"], "rows": [["conjunto", "não", "não por definição", "{a,b,c}"], ["sequência", "sim", "pode haver", "(a,b,a)"], ["subconjunto de tamanho k", "não", "não", "{a,c}"], ["função de [k] para A", "sim, por posição", "sim", "f(1)=a, f(2)=a"]]}]}, {"type": "subsection", "id": "comb-funcoes", "number": "1.2", "title": "Bijeções e princípio da casa dos pombos", "tag": "PROVAS", "accent": "teal", "blocks": [{"type": "paragraph", "text": "Uma **bijeção** é uma função simultaneamente injetiva (elementos diferentes têm imagens diferentes) e sobrejetiva (todo elemento do contradomínio é atingido). Se existe uma bijeção entre `A` e `B`, então os conjuntos têm a mesma cardinalidade."}, {"type": "heading", "level": 3, "text": "Prova do princípio da casa dos pombos"}, {"type": "paragraph", "text": "Se `n+1` objetos são colocados em `n` caixas, alguma caixa contém pelo menos dois objetos."}, {"type": "steps", "items": [{"title": "Supor o contrário", "text": "Suponha que nenhuma caixa contenha dois objetos."}, {"title": "Consequência da hipótese", "text": "Então cada caixa contém no máximo um objeto."}, {"title": "Contar o máximo possível", "text": "Com `n` caixas e no máximo um objeto em cada uma, cabem no máximo `n` objetos."}, {"title": "Contradição", "text": "A situação contém `n+1` objetos, que é maior que `n`; a hipótese é impossível."}, {"title": "Conclusão", "text": "Logo existe uma caixa com pelo menos dois objetos."}]}, {"type": "paragraph", "text": "A versão generalizada afirma que, ao colocar `N` objetos em `k` caixas, alguma caixa contém pelo menos $ceil(N/k)$ objetos. A prova segue dividindo `N` pela capacidade máxima `r`: se todas tivessem no máximo `r-1`, o total seria no máximo `k(r-1)`, contradizendo `N>k(r-1)`."}]}, {"type": "subsection", "id": "comb-modelagem", "number": "1.3", "title": "Da pergunta lógica ao modelo computacional", "tag": "PONTE", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Antes de escolher uma fórmula, transforme o problema em uma função de contagem. O domínio é o conjunto de entradas válidas; o contradomínio é o conjunto de configurações; a função deve ser injetiva quando duas representações diferentes não podem descrever a mesma configuração. Essa formalização é a ponte entre lógica e algoritmo."}, {"type": "steps", "items": [{"title": "Definir a identidade", "text": "Pergunte quais diferenças importam. Em um conjunto, trocar a ordem não cria outro objeto; em uma sequência, cria."}, {"title": "Escolher uma representação", "text": "Use tupla, sequência, subconjunto, bitmask, grafo ou função conforme o objeto. A representação precisa permitir testar validade."}, {"title": "Particionar casos", "text": "Crie casos mutuamente exclusivos. Em código, isso vira `if`, estados de uma DP ou ramos de uma prova."}, {"title": "Provar cobertura", "text": "Mostre que toda entrada válida cai em algum caso. Sem esta etapa, o algoritmo pode omitir soluções."}, {"title": "Provar não duplicação", "text": "Mostre que uma solução não aparece em dois caminhos. Sem esta etapa, a contagem e o algoritmo podem supercontar."}, {"title": "Extrair complexidade", "text": "Conte estados, transições e memória. A fórmula final informa se a implementação é polinomial, exponencial ou inviável."}]}, {"type": "callout", "variant": "example", "title": "Aplicação: configuração de compilação", "text": "Se um experimento combina 3 compiladores, 4 níveis de otimização e 2 arquiteturas, a regra do produto produz $3\\cdot4\\cdot2=24$ configurações. Se algumas combinações são incompatíveis, o conjunto deve ser particionado pelas restrições antes da multiplicação."}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Nesta seção você aprendeu a base de toda a combinatória: distinguir conjunto de sequência, provar a regra da soma e do produto, usar bijeções e o princípio da casa dos pombos, e traduzir um problema em uma função de contagem antes de aplicar qualquer fórmula. Os próximos capítulos reaproveitam diretamente esse vocabulário: a regra do produto reaparece na dedução de permutações e do teorema binomial (Seção 2), e a ideia de bijeção volta em quase toda prova do livro, incluindo estrelas-e-barras (2.3) e os números de Catalan (4.2)."}, {"type": "history", "name": "Leonhard Euler", "shortBio": "Leonhard Euler (1707–1783) foi um matemático suíço que contribuiu para a teoria dos grafos, análise e combinatória.", "insight": "O problema das pontes de Königsberg mostrou como abstrair uma situação física em vértices e arestas. Essa mudança de representação é uma das ideias centrais da combinatória aplicada.", "image": {"src": "images/history-euler.jpg", "alt": "Retrato de Leonhard Euler"}}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "permutacoes-combinacoes", "number": "2", "title": "Permutações, combinações e contagem com restrições", "blocks": [{"type": "paragraph", "text": "As fórmulas deste capítulo serão deduzidas por decisões sucessivas e por bijeções. Não use $n!$, $P(n,k)$ ou $\\binom{n}{k}$ antes de dizer se posições distinguem resultados.", "lead": true}, {"type": "subsection", "id": "comb-fatorial", "number": "2.1", "title": "Fatorial e permutações", "tag": "CONTAGEM", "accent": "blue", "blocks": [{"type": "paragraph", "text": "O fatorial é definido por $0!=1$ e $n!=n(n-1)!$ para $n\\ge1$."}, {"type": "heading", "level": 3, "text": "Teorema: permutações de n objetos distintos"}, {"type": "paragraph", "text": "O número de sequências que ordenam `n` objetos distintos é $n!$."}, {"type": "steps", "items": [{"title": "Primeira posição", "text": "Há `n` escolhas para a primeira posição."}, {"title": "Segunda posição", "text": "Depois da primeira escolha, restam `n-1` objetos."}, {"title": "Continuar", "text": "A terceira posição tem `n-2` escolhas, e assim por diante, até a última, que tem 1."}, {"title": "Aplicar a regra do produto", "text": "O total é $n(n-1)(n-2)…1=n!$."}, {"title": "Caso vazio", "text": "Para $n=0$, existe uma única sequência vazia; por isso $0!=1$, tornando a fórmula recursiva consistente."}]}, {"type": "math", "tex": "n! = \\prod_{i=1}^{n} i", "caption": "n objetos distintos em ordem"}, {"type": "paragraph", "text": "**Leitura da fórmula.** Leitura: n fatorial é o produto de todos os números inteiros de 1 até n; ele conta as ordens possíveis de n objetos distintos."}, {"type": "heading", "level": 3, "text": "Teorema: arranjos de k entre n"}, {"type": "paragraph", "text": "O número de sequências de comprimento `k` sem repetição escolhidas de `n` objetos é $P(n,k)=n!/(n-k)!$."}, {"type": "steps", "items": [{"title": "Escolher posições", "text": "A primeira posição tem `n` opções; a segunda `n-1`; a k-ésima `n-k+1`."}, {"title": "Escrever o produto", "text": "O total é `n(n-1)…(n-k+1)`."}, {"title": "Multiplicar e dividir", "text": "Multiplique o produto por `(n-k)!/(n-k)!`. O numerador vira $n!$ e o fator restante é `(n-k)!` no denominador."}, {"title": "Conclusão", "text": "$P(n,k)=n!/(n-k)!$."}]}, {"type": "code", "language": "cpp", "title": "Geração de permutações", "code": "std::sort(v.begin(), v.end());\ndo {\n    process(v);\n} while (std::next_permutation(v.begin(), v.end()));"}]}, {"type": "subsection", "id": "comb-binomial", "number": "2.2", "title": "Combinações e coeficientes binomiais", "tag": "CONTAGEM", "accent": "violet", "blocks": [{"type": "heading", "level": 3, "text": "Teorema: combinações sem repetição"}, {"type": "paragraph", "text": "O número de subconjuntos de tamanho `k` de um conjunto de `n` elementos é $\\binom{n}{k}=\\frac{n!}{k!(n-k)!}$."}, {"type": "steps", "items": [{"title": "Contar sequências primeiro", "text": "Escolha `k` elementos em ordem: existem $P(n,k)=n!/(n-k)!$ sequências."}, {"title": "Identificar a sobrecontagem", "text": "Cada subconjunto escolhido aparece `k!` vezes, uma para cada ordenação de seus elementos."}, {"title": "Dividir pela multiplicidade", "text": "Como cada subconjunto foi contado exatamente `k!` vezes, divida por `k!`."}, {"title": "Simplificar", "text": "$P(n,k)/k! = [n!/(n-k)!]/k! = n!/[k!(n-k)!]$."}, {"title": "Conclusão", "text": "A fórmula conta cada escolha sem ordem exatamente uma vez."}]}, {"type": "math", "tex": "\\binom{n}{k}=\\frac{n!}{k!(n-k)!}", "caption": "coeficiente binomial"}, {"type": "paragraph", "text": "**Leitura da fórmula.** Leitura: o número de maneiras de escolher k elementos entre n, sem considerar a ordem, é n fatorial dividido por k fatorial vezes n menos k fatorial."}, {"type": "heading", "level": 3, "text": "Prova da identidade de Pascal"}, {"type": "paragraph", "text": "Para `0<k<n`, $\\binom{n}{k}=\\binom{n-1}{k-1}+\\binom{n-1}{k}$."}, {"type": "steps", "items": [{"title": "Fixar um elemento", "text": "Escolha um elemento especial `x` do conjunto de `n` elementos."}, {"title": "Particionar os subconjuntos", "text": "Todo subconjunto de tamanho `k` contém `x` ou não contém `x`; os casos são disjuntos."}, {"title": "Contar o caso com x", "text": "Se contém `x`, faltam `k-1` elementos escolhidos entre os outros `n-1`: $\\binom{n-1}{k-1}$."}, {"title": "Contar o caso sem x", "text": "Se não contém `x`, todos os `k` elementos vêm dos outros `n-1`: $\\binom{n-1}{k}$."}, {"title": "Somar", "text": "A união dos dois casos é todo o conjunto de escolhas; pela regra da soma surge a identidade."}]}, {"type": "code", "language": "python", "title": "Triângulo de Pascal", "code": "def binomiais(n):\n    linha = [1]\n    for _ in range(n):\n        linha = [1] + [linha[i] + linha[i+1] for i in range(len(linha)-1)] + [1]\n    return linha"}]}, {"type": "subsection", "id": "comb-repeticao", "number": "2.3", "title": "Multiconjuntos, estrelas e barras e inclusão-exclusão", "tag": "RESTRIÇÕES", "accent": "orange", "blocks": [{"type": "heading", "level": 3, "text": "Teorema: soluções não negativas"}, {"type": "paragraph", "text": "O número de soluções inteiras não negativas de $x1+…+xk=n$ é $\\binom{n+k-1}{k-1}$."}, {"type": "steps", "items": [{"title": "Representar objetos", "text": "Escreva `n` estrelas, uma para cada unidade distribuída."}, {"title": "Separar caixas", "text": "Insira `k-1` barras para separar as k caixas; barras consecutivas representam uma caixa vazia."}, {"title": "Contar posições", "text": "Há `n+k-1` posições no total, ocupadas por `n` estrelas e `k-1` barras."}, {"title": "Escolher as barras", "text": "Escolher quais `k-1` posições são barras determina univocamente as quantidades `x1,…,xk`."}, {"title": "Conclusão", "text": "A bijeção com escolhas de `k-1` posições dá $\\binom{n+k-1}{k-1}$."}]}, {"type": "math", "tex": "\\#\\{(x_1,\\ldots,x_k)\\in\\mathbb{Z}_{\\ge0}^k: \\sum x_i=n\\}=\\binom{n+k-1}{k-1}", "caption": "estrelas e barras"}, {"type": "paragraph", "text": "**Leitura da fórmula.** Leitura: o número de k-uplas de inteiros não negativos cuja soma é n é igual ao número de maneiras de escolher k menos 1 separadores entre n objetos e esses separadores."}, {"type": "heading", "level": 3, "text": "Teorema: inclusão-exclusão para dois conjuntos"}, {"type": "paragraph", "text": "Para conjuntos finitos `A` e `B`, $|A\\cup B|=|A|+|B|-|A\\cap B|$."}, {"type": "steps", "items": [{"title": "Somar contagens individuais", "text": "Elementos apenas de A contam uma vez; elementos apenas de B contam uma vez; elementos da interseção contam duas."}, {"title": "Corrigir a duplicação", "text": "Subtraia $|A\\cap B|$; cada elemento da interseção passa de duas ocorrências para uma."}, {"title": "Verificar os três casos", "text": "Apenas A: 1−0=1; apenas B: 1−0=1; ambos: 1+1−1=1."}, {"title": "Conclusão", "text": "Cada elemento da união aparece exatamente uma vez na expressão."}]}]}, {"type": "subsection", "id": "comb-aplicacoes-contagem", "number": "2.4", "title": "Aplicações: testes, buscas e enumeração", "tag": "APLICACOES", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Permutações e combinações aparecem quando um algoritmo precisa explorar ordens ou subconjuntos. A distinção matemática determina se o algoritmo deve gerar $P(n,k)$ arranjos ou apenas $\\binom{n}{k}$ escolhas."}, {"type": "paragraph", "text": "Em testes de interação, escolher $k$ parâmetros entre $n$ sem ordem corresponde a uma combinação. Em escalonamento, ordenar tarefas corresponde a uma permutação. Em busca exaustiva, a quantidade contada é também um limite inferior para o número de candidatos que um algoritmo que testa todos os casos precisará examinar."}, {"type": "mermaid", "code": "flowchart LR\n A(\"problema\") --> B(\"ordem importa?\")\n B -->|\"sim\"| C(\"permutação / arranjo\")\n B -->|\"não\"| D(\"combinação\")\n C --> E(\"busca em ordens\")\n D --> F(\"seleção / cobertura\")", "caption": "decisão do modelo combinatório", "accent": "orange"}, {"type": "callout", "variant": "warning", "title": "Restrição muda o universo", "text": "Se duas tarefas não podem ser adjacentes, não use automaticamente $n!$. Primeiro conte as ordens válidas ou transforme a restrição em uma decomposição por casos; a fórmula sem a hipótese correta resolve outro problema."}, {"type": "heading", "level": 3, "text": "Teorema: permutações com duas tarefas proibidas de serem adjacentes"}, {"type": "paragraph", "text": "Sejam `n` tarefas distintas, das quais duas tarefas específicas `X` e `Y` não podem ficar em posições adjacentes na ordenação. O número de ordenações válidas é $n! - 2(n-1)!$."}, {"type": "steps", "items": [{"title": "Contar o universo sem restrição", "text": "Há `n!` ordenações de `n` tarefas distintas (Seção 2.1)."}, {"title": "Contar o complemento: X e Y adjacentes", "text": "Trate `X` e `Y` grudados como um único bloco. Há `n-1` objetos para ordenar (o bloco mais as `n-2` tarefas restantes): `(n-1)!` ordenações."}, {"title": "Contar as duas orientações do bloco", "text": "Dentro do bloco, `X` pode vir antes ou depois de `Y`: 2 formas. Pela regra do produto (Seção 1), há `2(n-1)!` ordenações com `X` e `Y` adjacentes."}, {"title": "Subtrair o complemento", "text": "O conjunto de ordenações válidas é o universo menos o complemento: $n! - 2(n-1)!$. Isso é inclusão-exclusão (Seção 2.3) aplicada a um único evento \"ruim\"."}, {"title": "Verificar com n pequeno", "text": "Para $n=3$: $3! - 2\\cdot2! = 6-4=2$. As 6 permutações de `{X,Y,Z}` são XYZ, XZY, YXZ, YZX, ZXY, ZYX; apenas XZY e YZX não têm X e Y adjacentes — bate com o resultado."}]}, {"type": "math", "tex": "n! - 2(n-1)!", "caption": "ordenações válidas com X e Y não adjacentes"}, {"type": "code", "language": "cpp", "title": "Verificação por força bruta (cobertura de teste combinatório)", "code": "int n = 3;\nstd::vector<int> v(n);\nstd::iota(v.begin(), v.end(), 0);   // 0=X, 1=Y, resto = outras tarefas\nint validas = 0, total = 0;\ndo {\n    ++total;\n    int posX = std::find(v.begin(), v.end(), 0) - v.begin();\n    int posY = std::find(v.begin(), v.end(), 1) - v.begin();\n    if (std::abs(posX - posY) != 1) ++validas;\n} while (std::next_permutation(v.begin(), v.end()));\n// total == n!  |  validas == n! - 2*(n-1)!", "highlight": "", "lineNumbers": false}, {"type": "heading", "level": 3, "text": "Exemplo: gerando as configurações da Seção 1.3 por código"}, {"type": "paragraph", "text": "A Seção 1.3 contou $3\\cdot4\\cdot2=24$ configurações de compilação (compilador × otimização × arquitetura) pela regra do produto. Gerar essas configurações explicitamente — em vez de apenas contá-las — é o primeiro passo de um teste combinatório: percorrer o produto cartesiano é enumerar candidatos; decidir *quais* combinações realmente testar (por exemplo, cobrindo todo par de valores ao menos uma vez, em vez das 24 completas) é o problema de cobertura por pares (*pairwise testing*) citado na Seção 7.3."}, {"type": "code", "language": "cpp", "title": "Enumerando o produto cartesiano de parâmetros", "code": "std::vector<std::string> compiladores = {\"gcc\", \"clang\", \"msvc\"};\nstd::vector<std::string> otimizacoes  = {\"O0\", \"O1\", \"O2\", \"O3\"};\nstd::vector<std::string> arquiteturas = {\"x86-64\", \"arm64\"};\n\nint total = 0;\nfor (auto& c : compiladores)\n    for (auto& o : otimizacoes)\n        for (auto& a : arquiteturas)\n            ++total;   // cada iteração é uma configuração distinta\n// total == 3*4*2 == 24, confirmando a regra do produto da Seção 1.3", "highlight": "", "lineNumbers": false}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Você viu como decisões sucessivas e bijeções produzem fatorial, arranjos, combinações, a identidade de Pascal, estrelas-e-barras e inclusão-exclusão para dois conjuntos — sempre partindo da regra do produto e da regra da soma definidas na Seção 1. A prova de permutações com restrição de adjacência aplicou inclusão-exclusão a um caso concreto, e o exemplo de geração do produto cartesiano mostrou como \"contar\" e \"enumerar de fato\" são passos diferentes — a base do teste combinatório citado na Seção 7. Essas fórmulas são a matéria-prima da Seção 3: lá elas reaparecem como exemplos de indução e dupla contagem, e a ideia de \"contar de duas formas e igualar\" generaliza o argumento usado aqui para provar Pascal."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "provas-recorrencias", "number": "3", "title": "Técnicas de prova e recorrências", "blocks": [{"type": "paragraph", "text": "A combinatória não é um catálogo de fórmulas. Uma prova explica por que a representação não perde nem duplica objetos. Este capítulo apresenta indução, invariantes, dupla contagem e recorrências, com cada hipótese explicitada.", "lead": true}, {"type": "subsection", "id": "comb-inducao", "number": "3.1", "title": "Indução matemática e estrutural", "tag": "PROVAS", "accent": "blue", "blocks": [{"type": "paragraph", "text": "Na indução matemática, prova-se uma proposição $P(n)$ mostrando o caso-base e que $P(n)$ implica $P(n+1)$. A indução forte permite usar todos os casos anteriores. Na indução estrutural, o passo acompanha como o objeto é construído, como árvores e expressões."}, {"type": "heading", "level": 3, "text": "Teorema: soma dos primeiros n inteiros"}, {"type": "paragraph", "text": "Para $n\\ge1$, $1+2+…+n=n(n+1)/2$."}, {"type": "steps", "items": [{"title": "Base", "text": "Para $n=1$, o lado esquerdo é 1 e o direito é $1\\cdot2/2=1$."}, {"title": "Hipótese", "text": "Suponha a igualdade para um `n` fixo: $1+…+n=n(n+1)/2$."}, {"title": "Passo", "text": "Some `n+1` aos dois lados: $1+…+n+(n+1)=n(n+1)/2+(n+1)$."}, {"title": "Fatorar", "text": "$n(n+1)/2+(n+1)=(n+1)(n/2+1)=(n+1)(n+2)/2$."}, {"title": "Conclusão", "text": "A igualdade vale para `n+1`; base e passo provam todos os $n\\ge1$."}]}, {"type": "heading", "level": 3, "text": "Prova por indução estrutural: folhas de uma árvore binária cheia"}, {"type": "paragraph", "text": "Se cada nó interno tem exatamente dois filhos, então uma árvore com `i` nós internos tem `i+1` folhas."}, {"type": "steps", "items": [{"title": "Base", "text": "Uma árvore sem nós internos tem uma folha; $0+1=1$."}, {"title": "Construção", "text": "Toda árvore não-base nasce de uma raiz interna e duas subárvores menores."}, {"title": "Aplicar hipótese", "text": "Se as subárvores têm `i1` e `i2` internos, suas folhas são `i1+1` e `i2+1`."}, {"title": "Somar", "text": "A árvore inteira tem $i=1+i1+i2$ internos e $(i1+1)+(i2+1)=i+1$ folhas."}, {"title": "Conclusão", "text": "A propriedade é preservada pela construção recursiva."}]}]}, {"type": "subsection", "id": "comb-dupla-contagem", "number": "3.2", "title": "Dupla contagem e identidades", "tag": "TECNICAS", "accent": "teal", "blocks": [{"type": "heading", "level": 3, "text": "Teorema: soma dos coeficientes binomiais"}, {"type": "paragraph", "text": "$\\sum_{k=0}^{n}\\binom{n}{k}=2^n$."}, {"type": "steps", "items": [{"title": "Definir o conjunto", "text": "Considere todos os subconjuntos de um conjunto com `n` elementos."}, {"title": "Contar por tamanho", "text": "Para cada `k`, existem $\\binom{n}{k}$ subconjuntos com exatamente `k` elementos; somar todos os k conta todos os subconjuntos."}, {"title": "Contar por decisões", "text": "Para cada elemento há duas decisões independentes: entra ou não entra. Pela regra do produto, existem $2\\cdot2…2=2^n$ subconjuntos."}, {"title": "Igualar contagens", "text": "As duas contagens descrevem o mesmo conjunto; portanto a soma é $2^n$."}]}, {"type": "math", "tex": "\\sum_{k=0}^{n}\\binom{n}{k}=2^n", "caption": "dupla contagem de subconjuntos"}, {"type": "paragraph", "text": "**Leitura da fórmula.** Leitura: a soma dos coeficientes binomiais para k de zero até n é igual a dois elevado a n, isto é, ao número de subconjuntos de um conjunto com n elementos."}, {"type": "heading", "level": 3, "text": "Teorema: identidade do aperto de mãos"}, {"type": "paragraph", "text": "Em qualquer grafo finito, a soma dos graus dos vértices é duas vezes o número de arestas."}, {"type": "steps", "items": [{"title": "Contar incidências", "text": "Uma incidência é um par (vértice, aresta) em que a aresta toca o vértice."}, {"title": "Contar por vértices", "text": "O vértice `v` participa de `deg(v)` incidências; a soma dos graus conta todas."}, {"title": "Contar por arestas", "text": "Cada aresta tem exatamente duas extremidades; logo contribui com duas incidências."}, {"title": "Igualar", "text": "As duas formas contam o mesmo conjunto de incidências: $\\sum_{v\\in V}\\operatorname{deg}(v)=2|E|$."}]}]}, {"type": "subsection", "id": "comb-recorrencias", "number": "3.3", "title": "Recorrências e análise passo a passo", "tag": "RECORRENCIAS", "accent": "violet", "blocks": [{"type": "paragraph", "text": "Uma recorrência precisa de equação, domínio e casos-base. Resolver uma recorrência significa encontrar uma expressão que satisfaz os três. Em algoritmos, ela surge quando um problema é dividido em subproblemas."}, {"type": "heading", "level": 3, "text": "Teorema: Fibonacci e tilings"}, {"type": "paragraph", "text": "O número de maneiras de cobrir uma faixa de comprimento `n` com peças de tamanho 1 e 2 satisfaz $T(n)=T(n-1)+T(n-2)$, com $T(0)=1$ e $T(1)=1$."}, {"type": "steps", "items": [{"title": "Observar a última peça", "text": "Toda cobertura termina com uma peça de tamanho 1 ou com uma peça de tamanho 2."}, {"title": "Caso 1", "text": "Se termina com 1, as posições anteriores formam uma cobertura de comprimento `n-1`: $T(n-1)$."}, {"title": "Caso 2", "text": "Se termina com 2, as posições anteriores formam uma cobertura de comprimento `n-2`: $T(n-2)$."}, {"title": "Disjunção", "text": "Os casos não se sobrepõem e cobrem todas as coberturas."}, {"title": "Somar", "text": "Logo $T(n)=T(n-1)+T(n-2)$. A faixa vazia tem uma cobertura vazia, por isso $T(0)=1$; uma faixa de tamanho 1 tem uma cobertura, por isso $T(1)=1$."}]}, {"type": "heading", "level": 3, "text": "Resolução por expansão"}, {"type": "steps", "items": [{"title": "Expandir", "text": "$T(n)=T(n-1)+T(n-2)$."}, {"title": "Expandir novamente", "text": "$T(n)=2T(n-2)+T(n-3)$ não é a forma mais conveniente; reorganize usando a árvore de chamadas ou matriz."}, {"title": "Árvore de chamadas", "text": "A versão ingênua repete subproblemas; memoização calcula cada $T(i)$ uma vez."}, {"title": "Complexidade", "text": "Com memoização há `n+1` estados e cada estado usa trabalho constante: tempo `Theta(n)` e memória `Theta(n)`."}]}]}, {"type": "subsection", "id": "comb-prova-algoritmo", "number": "3.4", "title": "Prova de correção como contrato de algoritmo", "tag": "LOGICA", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Uma prova combinatória e uma prova de correção têm a mesma disciplina: definir o universo, estabelecer uma correspondência e verificar que nenhuma possibilidade foi perdida ou duplicada. Em um algoritmo, a propriedade que permanece verdadeira durante o processamento é o **invariante**."}, {"type": "steps", "items": [{"title": "Inicialização", "text": "Prove que o invariante é verdadeiro antes do primeiro passo. Em uma DP, isso corresponde aos casos-base."}, {"title": "Manutenção", "text": "Prove que cada transição preserva o invariante. Em uma recorrência, é a justificativa de que os subproblemas representam exatamente os casos menores."}, {"title": "Terminação", "text": "Prove que a medida de tamanho diminui ou que a fila de estados se esgota."}, {"title": "Conclusão", "text": "Quando o algoritmo termina, combine o invariante com a condição de término para obter a propriedade desejada."}, {"title": "Complexidade", "text": "Conte quantas vezes a transição é executada; a prova de correção não substitui a análise de custo."}]}, {"type": "callout", "variant": "example", "title": "Aplicação: BFS", "text": "Na busca em largura, o invariante é que um vértice retirado da fila recebe sua menor distância da fonte. A prova depende da ordem FIFO e do fato de cada aresta aumentar a distância em no máximo uma unidade; a contagem de níveis explica o custo $O(|V|+|E|)$."}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Esta seção formalizou as técnicas de prova que sustentam o livro inteiro: indução (comum e estrutural), dupla contagem e recorrências com casos-base explícitos, terminando na ideia de que uma prova de correção de algoritmo segue a mesma disciplina de uma prova combinatória. A dupla contagem prova aqui a identidade do aperto de mãos e a soma dos binomiais — o mesmo coeficiente binomial definido na Seção 2. As recorrências deduzidas aqui (Fibonacci/tilings) são o ponto de partida da Seção 4, onde funções geradoras oferecem uma segunda ferramenta para resolvê-las."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "funcoes-geradoras", "number": "4", "title": "Funções geradoras e enumeração algébrica", "blocks": [{"type": "paragraph", "text": "Funções geradoras transformam sequências em séries formais. A variável `x` não precisa representar um número; ela marca tamanho. O coeficiente de $x^n$ continua sendo a quantidade de objetos de tamanho `n`.", "lead": true}, {"type": "subsection", "id": "comb-ogs", "number": "4.1", "title": "Definição e produtos", "tag": "SERIES", "accent": "teal", "blocks": [{"type": "paragraph", "text": "A função geradora ordinária de uma sequência `(a_n)` é $A(x)=\\sum_{n\\ge 0}a_nx^n$. Como série formal, operações são definidas coeficiente a coeficiente; não é necessário assumir convergência analítica."}, {"type": "heading", "level": 3, "text": "Teorema: produto de funções geradoras"}, {"type": "paragraph", "text": "Se uma configuração de tamanho `n` é formada por uma parte de tamanho `i` e outra de tamanho `n-i`, então o produto das funções geradoras soma corretamente essas possibilidades."}, {"type": "steps", "items": [{"title": "Escrever as séries", "text": "$A(x)=\\sum_i a_i x^i$ e $B(x)=\\sum_j b_j x^j$."}, {"title": "Multiplicar", "text": "$A(x)B(x)=\\sum_i\\sum_j a_i b_j x^{i+j}$."}, {"title": "Agrupar por tamanho", "text": "O coeficiente de $x^n$ reúne exatamente os pares com $i+j=n$: $\\sum_{i=0}^n a_i b_{n-i}$."}, {"title": "Interpretar", "text": "Para cada divisão de tamanho, há $a_i$ escolhas da primeira parte e `b_{n-i}` da segunda; a regra do produto dá o produto e a soma percorre todas as divisões."}, {"title": "Conclusão", "text": "O coeficiente do produto é a convolução que conta composições em duas partes."}]}, {"type": "math", "tex": "(A B)_n = [x^n]A(x)B(x)=\\sum_{i=0}^{n}a_i b_{n-i}", "caption": "coeficiente de produto"}, {"type": "paragraph", "text": "**Leitura da fórmula.** Leitura: o coeficiente de x elevado a n no produto A de x vezes B de x é a soma, para cada i de zero a n, do produto de a índice i por b índice n menos i."}, {"type": "heading", "level": 3, "text": "Exemplo: moedas de 1 e 2"}, {"type": "paragraph", "text": "Uma sequência de moedas de valores 1 e 2 tem função geradora $(1+x+x^2+…)(1+x^2+x^4+…)=1/[(1-x)(1-x^2)]$; o coeficiente de $x^n$ conta as soluções $a+2b=n$. A prova decorre da escolha independente da quantidade de moedas de cada tipo."}]}, {"type": "subsection", "id": "comb-racionais", "number": "4.2", "title": "Binômio, catalan e recorrências", "tag": "AVANCADO", "accent": "pink", "blocks": [{"type": "heading", "level": 3, "text": "Teorema binomial"}, {"type": "paragraph", "text": "$(x+y)^n=\\sum_{k=0}^n \\binom{n}{k}x^{n-k}y^k$."}, {"type": "steps", "items": [{"title": "Escolher um termo por fator", "text": "Ao expandir os `n` fatores `(x+y)`, escolha `x` ou `y` em cada fator."}, {"title": "Classificar por quantidade de y", "text": "Termos com exatamente `k` escolhas de `y` têm $x^{n-k}y^k$."}, {"title": "Contar escolhas", "text": "As posições dos `k` fatores que fornecem `y` podem ser escolhidas em $\\binom{n}{k}$ formas."}, {"title": "Somar classes", "text": "Somar $k=0,…,n$ reúne todos os termos e produz a fórmula."}]}, {"type": "heading", "level": 3, "text": "Números de Catalan"}, {"type": "paragraph", "text": "A quantidade $C_n$ de palavras balanceadas de n pares de parênteses satisfaz $C_0=1$ e $C_n=\\sum_{i=0}^{n-1}C_iC_{n-1-i}$."}, {"type": "steps", "items": [{"title": "Encontrar o primeiro fechamento", "text": "Em uma palavra não vazia balanceada, o parêntese que fecha o primeiro `(` divide a palavra em uma parte interna e uma parte restante."}, {"title": "Contar a parte interna", "text": "Se ela usa `i` pares, há $C_i$ possibilidades."}, {"title": "Contar a parte restante", "text": "Os `n-1-i` pares restantes podem ser organizados em `C_{n-1-i}` possibilidades."}, {"title": "Aplicar produto e soma", "text": "Para cada `i`, o produto conta os pares de partes; somar todos os i conta cada palavra uma vez."}, {"title": "Conclusão", "text": "A recorrência segue da decomposição única pelo primeiro fechamento."}]}, {"type": "steps", "items": [{"title": "Definir a função geradora", "text": "A recorrência de Catalan tem função geradora $C(x)=\\sum_{n\\ge 0}C_nx^n$. Separando o termo n=0 e usando a convolução da recorrência, obtemos $C(x)=1+xC(x)^2$."}, {"title": "Resolver a equação quadrática", "text": "Reorganize: $xC(x)^2-C(x)+1=0$. Pela fórmula quadrática, as soluções formais são $\\frac{1\\pm\\sqrt{1-4x}}{2x}$."}, {"title": "Escolher o ramo correto", "text": "Como $C(0)=1$, a série precisa ter termo constante finito. O ramo com $1+\\sqrt{1-4x}$ teria numerador tendendo a 2 e divisão por x; portanto escolhemos $C(x)=\\frac{1-\\sqrt{1-4x}}{2x}$."}, {"title": "Extrair o coeficiente", "text": "A expansão binomial formal de $(1-4x)^{1/2}$ mostra que o coeficiente de $x^n$ nessa série é $\\frac{1}{n+1}\\binom{2n}{n}$ para $n\\ge 0$; substituir na expressão de C(x) desloca o índice em uma posição."}, {"title": "Conclusão", "text": "Logo $C_n=\\frac{1}{n+1}\\binom{2n}{n}$. A identidade é consequência da recorrência, da função geradora e da escolha do ramo compatível com o caso-base; não é uma fórmula independente sem hipóteses."}]}, {"type": "math", "tex": "C_n=\\frac{1}{n+1}\\binom{2n}{n}", "caption": "fórmula fechada de Catalan"}, {"type": "paragraph", "text": "**Leitura da fórmula.** Leitura: o n-ésimo número de Catalan é o coeficiente binomial que escolhe n elementos entre 2n, dividido por n mais 1."}]}, {"type": "subsection", "id": "comb-ogs-computacao", "number": "4.3", "title": "Aplicação: recorrências de algoritmos e séries", "tag": "APLICACOES", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Funções geradoras não são apenas uma técnica para obter identidades. Elas permitem transformar uma recorrência de contagem em uma equação, resolver a equação e retornar ao coeficiente que representa o custo ou o número de configurações."}, {"type": "steps", "items": [{"title": "Modelar o algoritmo", "text": "Defina $a_n$ como o número de configurações ou o custo para entradas de tamanho $n$."}, {"title": "Derivar a recorrência", "text": "Divida a execução pelo primeiro passo, pela última peça ou por uma partição única; prove que os casos são disjuntos."}, {"title": "Codificar", "text": "Forme $A(x)=\\sum_{n\\ge 0}a_nx^n$."}, {"title": "Resolver", "text": "Use a equação algébrica obtida pela recorrência, escolhendo o ramo compatível com os casos-base."}, {"title": "Interpretar", "text": "Extraia o coeficiente e compare o crescimento com a memória e o tempo disponíveis."}]}, {"type": "callout", "variant": "example", "title": "Aplicação: análise de recursão", "text": "A expansão de uma árvore de chamadas conta quantas subchamadas são criadas. A função geradora oferece uma alternativa algébrica para algumas recorrências; a programação dinâmica, por sua vez, altera o algoritmo eliminando repetições. A mesma sequência pode descrever uma enumeração e uma complexidade."}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Funções geradoras transformaram as recorrências da Seção 3 em equações algébricas: você viu o teorema do produto de séries, a expansão binomial, e como a recorrência de Catalan — a mesma lógica de \"dividir em casos disjuntos e somar\" da Seção 1 — leva a uma equação quadrática cuja solução fecha a fórmula de Catalan. A Seção 7 retoma essa técnica ao analisar recorrências de algoritmos e programação dinâmica."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "grafos-arvores", "number": "5", "title": "Grafos, árvores e estruturas discretas", "blocks": [{"type": "paragraph", "text": "Grafos conectam combinatória a redes, compiladores, dependências, roteamento e análise de algoritmos. Cada teorema será acompanhado da contagem que o sustenta.", "lead": true}, {"type": "subsection", "id": "comb-grafos", "number": "5.1", "title": "Definições, caminhos e conectividade", "tag": "GRAFOS", "accent": "blue", "blocks": [{"type": "paragraph", "text": "Um grafo não dirigido é $G=(V,E)$, em que `V` é o conjunto de vértices e `E` é um conjunto de pares não ordenados de vértices. O grau `deg(v)` é o número de arestas incidentes em `v`. Um caminho é uma sequência de vértices adjacentes; um ciclo é um caminho fechado sem repetir vértices internos."}, {"type": "heading", "level": 3, "text": "Teorema: caracterizações de árvore"}, {"type": "paragraph", "text": "Para um grafo finito com `n` vértices, são equivalentes: ser conexo e acíclico; ter exatamente `n-1` arestas e ser conexo; e ter exatamente um caminho simples entre quaisquer dois vértices."}, {"type": "steps", "items": [{"title": "Árvore implica n−1 arestas", "text": "Induza em `n`. A árvore de um vértice tem 0 arestas. Toda árvore com mais de um vértice tem uma folha; remova-a e aplique a hipótese à árvore restante, obtendo $(n-2)+1=n-1$."}, {"title": "Conectividade e n−1 implica acíclico", "text": "Se houvesse um ciclo, remova uma aresta do ciclo: o grafo continuaria conexo, mas passaria a ter `n-2` arestas. Isso contradiz que um grafo conexo precisa de pelo menos `n-1` arestas."}, {"title": "Conectividade e aciclicidade implicam caminho único", "text": "Se o grafo é conexo e houvesse dois caminhos simples distintos entre os mesmos vértices, siga-os até a primeira divergência e até a primeira convergência; a união contém um ciclo."}, {"title": "Caminho único implica conectividade e aciclicidade", "text": "Há caminho entre todo par, logo é conexo. Um ciclo forneceria dois caminhos diferentes entre dois vértices do ciclo."}, {"title": "Conclusão", "text": "As propriedades se implicam mutuamente."}]}, {"type": "mermaid", "code": "graph TD\n A((\"raiz\")) --> B((\"subárvore\"))\n A --> C((\"subárvore\"))\n B --> D((\"folha\"))\n C --> E((\"folha\"))", "caption": "árvore como grafo conexo sem ciclos", "accent": "blue"}]}, {"type": "subsection", "id": "comb-dag", "number": "5.2", "title": "DAGs, ordenação topológica e fluxo", "tag": "ALGORITMOS", "accent": "teal", "blocks": [{"type": "paragraph", "text": "Um DAG é um grafo dirigido sem ciclos. Uma ordenação topológica coloca cada vértice antes de todos os seus sucessores; ela existe exatamente quando o grafo não tem ciclo."}, {"type": "heading", "level": 3, "text": "Prova por remoção de fonte"}, {"type": "steps", "items": [{"title": "Existência de fonte", "text": "Se todo vértice tivesse uma aresta entrando, comece em qualquer vértice e siga predecessores. Como o grafo é finito, algum vértice se repetiria, formando ciclo; contradição. Logo existe uma fonte."}, {"title": "Remover a fonte", "text": "Retire a fonte e suas arestas. O grafo restante continua sem ciclos."}, {"title": "Repetir", "text": "Aplique o mesmo argumento ao grafo restante até remover todos os vértices."}, {"title": "Preservar a ordem", "text": "Cada removido é colocado antes dos vértices que dependiam dele; portanto a lista obtida é topológica."}, {"title": "Algoritmo", "text": "Uma fila de fontes implementa o processo em $O(|V|+|E|)$ usando listas de adjacência."}]}, {"type": "heading", "level": 3, "text": "Teorema max-flow/min-cut — ideia de prova por aumento"}, {"type": "paragraph", "text": "Em uma rede com capacidades, o valor de qualquer fluxo é no máximo a capacidade de qualquer corte. Quando não existe caminho aumentante na rede residual, o corte formado pelos vértices alcançáveis a partir da fonte tem capacidade igual ao fluxo atual."}, {"type": "steps", "items": [{"title": "Limite superior", "text": "Toda unidade que sai da fonte e chega ao sumidouro precisa atravessar um corte; portanto fluxo ≤ capacidade do corte."}, {"title": "Rede residual", "text": "A rede residual registra quanto ainda pode ser enviado para frente e quanto pode ser desfeito por arestas reversas."}, {"title": "Sem caminho aumentante", "text": "Se não há caminho residual até o sumidouro, os alcançáveis formam um conjunto S e o restante forma T."}, {"title": "Saturação das arestas S→T", "text": "Se uma aresta S→T tivesse capacidade residual positiva, seu destino seria alcançável; logo todas estão saturadas."}, {"title": "Zero retorno útil T→S", "text": "Uma aresta residual T→S positiva representaria fluxo que poderia ser ajustado, mas não altera a capacidade líquida do corte."}, {"title": "Igualdade", "text": "O fluxo enviado é exatamente a soma das capacidades das arestas S→T; ele atinge a capacidade do corte. Junto ao limite superior, é máximo."}]}]}, {"type": "subsection", "id": "comb-buscas-caminhos", "number": "5.3", "title": "BFS, DFS e Dijkstra: explorar e otimizar caminhos", "tag": "ALGORITMOS", "accent": "orange", "blocks": [{"type": "paragraph", "text": "BFS, DFS e Dijkstra percorrem grafos, mas resolvem problemas diferentes. BFS explora por camadas e encontra distâncias mínimas em grafos não ponderados; DFS aprofunda uma possibilidade antes de voltar e é adequada para conectividade, ciclos, componentes e ordenação; Dijkstra mantém a melhor distância conhecida e funciona quando todos os pesos são não negativos."}, {"type": "heading", "level": 3, "text": "BFS: busca em largura"}, {"type": "paragraph", "text": "BFS mantém uma fila FIFO (first in, first out, isto é, o primeiro vértice descoberto é o primeiro a ser processado). Ao descobrir um vértice, registra sua distância como a distância do predecessor mais um. Como todos os passos têm custo unitário, nenhum caminho futuro pode alcançar esse vértice com menos passos depois que ele foi descoberto."}, {"type": "steps", "items": [{"title": "Inicializar", "text": "Coloque a origem s na fila, marque-a como visitada e defina $d(s)=0$. Para os demais vértices, use distância infinita."}, {"title": "Expandir uma camada", "text": "Retire o primeiro vértice u. Para cada vizinho v ainda não visitado, marque v, defina $d(v)=d(u)+1$ e coloque v no fim da fila."}, {"title": "Preservar o invariante", "text": "A fila contém vértices em ordem não decrescente de distância. Todos os vértices retirados antes de u estão a distância no máximo $d(u)$."}, {"title": "Concluir a distância mínima", "text": "Qualquer caminho para v precisa vir de um vizinho anterior. Como BFS processa todas as camadas menores antes da camada de v, o primeiro valor atribuído a v é mínimo."}, {"title": "Analisar custo", "text": "Com listas de adjacência, cada vértice entra na fila uma vez e cada aresta é examinada uma vez em cada sentido; o custo é $O(|V|+|E|)$ e a memória é $O(|V|)$."}]}, {"type": "code", "language": "cpp", "title": "BFS com distâncias", "code": "std::queue<int> q;\ndist[s] = 0;\nq.push(s);\nwhile (!q.empty()) {\n    int u = q.front(); q.pop();\n    for (int v : adj[u]) {\n        if (dist[v] == INF) {\n            dist[v] = dist[u] + 1;\n            parent[v] = u;\n            q.push(v);\n        }\n    }\n}"}, {"type": "heading", "level": 3, "text": "DFS: busca em profundidade"}, {"type": "paragraph", "text": "DFS usa uma pilha explícita ou a pilha de chamadas da recursão. Ela segue uma aresta até não haver vizinho novo; então retorna pelo caminho de predecessores e tenta a próxima aresta. A ordem depende da ordem da lista de adjacência, mas a propriedade de visitar cada vértice alcançável permanece."}, {"type": "steps", "items": [{"title": "Descobrir", "text": "Ao entrar em u, marque u como descoberto e registre seu tempo de entrada."}, {"title": "Aprofundar", "text": "Escolha cada vizinho v. Se v não foi descoberto, a aresta u→v é de árvore e DFS chama-se recursivamente em v."}, {"title": "Retornar", "text": "Quando todos os vizinhos forem tratados, registre o tempo de saída de u e retorne ao predecessor."}, {"title": "Detectar ciclos", "text": "Em grafo dirigido, encontrar uma aresta para um vértice descoberto mas ainda não finalizado indica uma aresta de retorno e um ciclo."}, {"title": "Aplicar", "text": "A mesma estrutura encontra componentes, classifica arestas, produz ordenação topológica por tempos de saída e identifica pontes com tempos baixos."}]}, {"type": "code", "language": "cpp", "title": "DFS recursivo com tempos de descoberta e término", "code": "int tempo = 0;\nstd::vector<int> disc(n, -1), fim(n, -1);\n\nvoid dfs(int u, int pai) {\n    disc[u] = ++tempo;\n    for (int v : adj[u]) {\n        if (v == pai) continue;      // não volta pela mesma aresta ao pai\n        if (disc[v] == -1) {\n            dfs(v, u);                // aresta de árvore\n        }\n        // disc[v] != -1 e v != pai: aresta de retorno (back edge)\n    }\n    fim[u] = ++tempo;\n}", "highlight": "", "lineNumbers": false}, {"type": "paragraph", "text": "O custo de DFS também é $O(|V|+|E|)$ com listas de adjacência. A profundidade da recursão pode chegar a $|V|$; em grafos muito profundos, uma pilha explícita evita estouro da pilha do processo."}, {"type": "heading", "level": 3, "text": "Dijkstra: caminhos mínimos com pesos não negativos"}, {"type": "paragraph", "text": "Dijkstra resolve o problema de menor custo em um grafo ponderado quando cada peso $w(u,v)\\ge 0$. Ele mantém uma estimativa $dist[v]$ e escolhe, entre os vértices ainda não finalizados, aquele com menor estimativa. A operação de relaxamento testa se passar por u melhora o caminho para v: se $dist[u]+w(u,v)<dist[v]$, atualiza a distância e o predecessor."}, {"type": "steps", "items": [{"title": "Inicializar", "text": "Defina $dist[s]=0$ e todas as outras distâncias como infinito. Nenhum vértice está finalizado."}, {"title": "Extrair o mínimo", "text": "Escolha o vértice u não finalizado com menor $dist[u]$. Esse valor se torna definitivo."}, {"title": "Justificar a escolha", "text": "Qualquer caminho alternativo até u que passe por um vértice ainda não finalizado teria de atravessar uma estimativa pelo menos tão grande quanto $dist[u]$; como os pesos não são negativos, não poderia chegar mais barato a u."}, {"title": "Relaxar", "text": "Para cada aresta u→v, compare o caminho conhecido com o caminho que chega a u e atravessa a aresta. Atualize v quando o segundo for menor."}, {"title": "Repetir e terminar", "text": "Continue até a fila de prioridade esvaziar ou até o destino ser finalizado. Os predecessores reconstruem o caminho ótimo."}, {"title": "Analisar custo", "text": "Com heap binário e listas de adjacência, o custo é $O((|V|+|E|)\\log |V|)$; com matriz e busca linear do mínimo, é $O(|V|^2)$."}]}, {"type": "code", "language": "cpp", "title": "Dijkstra com fila de prioridade", "code": "std::vector<int> dist(n, INF);\nstd::priority_queue<std::pair<int,int>,\n                     std::vector<std::pair<int,int>>,\n                     std::greater<>> pq;   // (distância, vértice)\ndist[s] = 0;\npq.push({0, s});\nwhile (!pq.empty()) {\n    auto [d, u] = pq.top(); pq.pop();\n    if (d > dist[u]) continue;        // entrada obsoleta, já superada\n    for (auto [v, peso] : adj[u]) {\n        if (dist[u] + peso < dist[v]) {\n            dist[v] = dist[u] + peso;\n            pq.push({dist[v], v});\n        }\n    }\n}", "highlight": "", "lineNumbers": false}, {"type": "callout", "variant": "warning", "title": "Limite essencial de Dijkstra", "text": "Uma aresta de peso negativo pode tornar falsa a decisão de finalizar o menor rótulo atual. Para pesos negativos, estude Bellman–Ford; para todos os pesos iguais a um, BFS é mais simples e linear."}, {"type": "table", "header": ["Algoritmo", "Estrutura", "Hipótese de peso", "Resultado"], "rows": [["BFS", "fila FIFO", "arestas sem peso ou peso unitário", "distância mínima em número de arestas"], ["DFS", "pilha ou recursão", "não depende de pesos", "exploração, ciclos e estrutura"], ["Dijkstra", "fila de prioridade", "todos os pesos não negativos", "menor custo de cada origem"]]}, {"type": "heading", "level": 4, "text": "Exemplo numérico: os três algoritmos no mesmo grafo"}, {"type": "paragraph", "text": "Considere o grafo não dirigido com vértices `A, B, C, D, E` e arestas `A–B`, `A–C`, `B–D`, `C–D`, `D–E` — um ciclo `A–B–D–C–A` com um \"apêndice\" `D–E`. Para Dijkstra, atribua pesos `A–B=2`, `A–C=5`, `B–D=1`, `C–D=1`, `D–E=3`. A listagem de adjacência de cada vértice segue a ordem em que aparece nas arestas acima (ex.: `A: [B, C]`, `D: [B, C, E]`)."}, {"type": "mermaid", "caption": "grafo de exemplo — ciclo A-B-D-C-A com apêndice D-E", "accent": "teal", "code": "flowchart LR\n  A((\"A\")) --- B((\"B\"))\n  A --- C((\"C\"))\n  B --- D((\"D\"))\n  C --- D\n  D --- E((\"E\"))"}, {"type": "table", "caption": "BFS, DFS e Dijkstra a partir de A, lado a lado", "header": ["Vértice", "BFS: ordem / distância (arestas)", "DFS: descoberta / término", "Dijkstra: ordem finalizada / distância"], "rows": [["A", "1ª / 0", "1 / 10", "1ª / 0"], ["B", "2ª / 1", "2 / 9", "2ª / 2"], ["C", "3ª / 1", "4 / 5", "4ª / 4"], ["D", "4ª / 2", "3 / 8", "3ª / 3"], ["E", "5ª / 3", "6 / 7", "5ª / 6"]]}, {"type": "callout", "variant": "note", "title": "Por que os números divergem", "text": "BFS mede distância em **número de arestas**, ignorando peso — por isso `C` chega em 2ª posição com distância 1. Dijkstra usa o **peso real**: como `A–C` pesa 5 mas `A–B–D–C` pesa `2+1+1=4`, `C` só é finalizado depois de `D`, com distância 4, não 5. DFS não mede distância nenhuma — `disc`/`fim` registram apenas a ordem de visita e retorno, o que é exatamente o que a Seção 5.1 (`low`) usa a seguir para achar pontes."}, {"type": "heading", "level": 4, "text": "Indo além: pontes e pontos de articulação com \"tempos baixos\" (low-link)"}, {"type": "paragraph", "text": "A frase \"identifica pontes com tempos baixos\", usada acima, se refere a uma extensão clássica do DFS (o algoritmo de **Tarjan** para pontes). Além de `disc[v]` (o tempo de descoberta), o algoritmo mantém `low[v]`: o menor `disc` alcançável a partir de `v` usando arestas de árvore seguidas de **no máximo uma** aresta de retorno. Formalmente, `low[v] = min(disc[v], min{disc[w] : (v,w) é aresta de retorno}, min{low[c] : c é filho de v na árvore de DFS})`."}, {"type": "steps", "items": [{"title": "Calcular disc e low", "text": "Execute o DFS normalmente. Ao descobrir `v`, defina `disc[v]=low[v]=tempo`. Ao retornar de um filho `c`, atualize `low[v] = min(low[v], low[c])`. Ao encontrar uma aresta de retorno para um ancestral `w` já visitado (e que não é o pai), atualize `low[v] = min(low[v], disc[w])`."}, {"title": "Testar a condição de ponte", "text": "A aresta de árvore `(v, c)` é uma **ponte** se, e somente se, `low[c] > disc[v]`: nenhum caminho a partir da subárvore de `c` consegue \"voltar\" para `v` ou para um ancestral de `v` sem usar essa aresta."}, {"title": "Ponto de articulação (ideia correlata)", "text": "Um vértice `v` (não raiz) é ponto de articulação se algum filho `c` satisfaz `low[c] >= disc[v]` — a condição é `>=` em vez de `>`, porque remover o vértice (não a aresta) já desconecta a subárvore de `c` mesmo que `low[c] == disc[v]`."}]}, {"type": "code", "language": "cpp", "title": "Pontes via DFS com low-link (Tarjan)", "code": "int tempo = 0;\nstd::vector<int> disc(n, -1), low(n, -1);\nstd::vector<std::pair<int,int>> pontes;\n\nvoid dfs(int u, int pai) {\n    disc[u] = low[u] = ++tempo;\n    for (int v : adj[u]) {\n        if (v == pai) continue;\n        if (disc[v] == -1) {\n            dfs(v, u);\n            low[u] = std::min(low[u], low[v]);\n            if (low[v] > disc[u])\n                pontes.push_back({u, v});      // condição de ponte\n        } else {\n            low[u] = std::min(low[u], disc[v]); // aresta de retorno\n        }\n    }\n}", "highlight": "", "lineNumbers": false}, {"type": "callout", "variant": "example", "title": "No grafo do exemplo acima", "text": "Com a árvore de DFS `A→B→D→C` (mais a aresta de retorno `C–A`) e o ramo `D→E`: `low[C]=min(disc[C]=4, disc[A]=1)=1`; `low[D]=min(disc[D]=3, low[C]=1, low[E]=6)=1`; `low[B]=min(disc[B]=2, low[D]=1)=1`. Testando cada aresta de árvore: `low[B]=1 > disc[A]=1`? Não — `A–B` não é ponte. `low[D]=1 > disc[B]=2`? Não — `B–D` não é ponte. `low[C]=1 > disc[D]=3`? Não — `D–C` não é ponte (as três estão no ciclo). Já `low[E]=6 > disc[D]=3`? **Sim** — `D–E` é a única ponte do grafo, exatamente o apêndice que não pertence a nenhum ciclo."}, {"type": "heading", "level": 4, "text": "Indo além: 0-1 BFS e outras variantes de fonte múltipla"}, {"type": "paragraph", "text": "Quando todo peso de aresta é `0` ou `1`, rodar Dijkstra completo ($O((|V|+|E|)\\log|V|)$) é desperdício: existe uma variante em $O(|V|+|E|)$ chamada **0-1 BFS**. A ideia: em vez de uma fila FIFO simples, use um `deque` (fila de duas pontas). Ao relaxar uma aresta de peso `0`, insira o vizinho na **frente** do deque (ele deve ser processado o quanto antes, pois não aumentou a distância); ao relaxar uma aresta de peso `1`, insira no **fim**. Isso mantém o deque sempre ordenado por distância não decrescente, como a fila do BFS comum mantinha — só que agora tolerando dois \"níveis\" de custo."}, {"type": "code", "language": "cpp", "title": "0-1 BFS com deque", "code": "std::vector<int> dist(n, INF);\nstd::deque<int> dq;\ndist[s] = 0;\ndq.push_front(s);\nwhile (!dq.empty()) {\n    int u = dq.front(); dq.pop_front();\n    for (auto [v, peso] : adj[u]) {   // peso é 0 ou 1\n        if (dist[u] + peso < dist[v]) {\n            dist[v] = dist[u] + peso;\n            if (peso == 0) dq.push_front(v);\n            else            dq.push_back(v);\n        }\n    }\n}", "highlight": "", "lineNumbers": false}, {"type": "paragraph", "text": "Duas outras variantes resolvem problemas específicos sem exigir um algoritmo novo: **BFS multi-fonte** coloca todos os vértices de origem na fila com distância 0 antes de começar (útil para \"distância até a fonte mais próxima dentre várias\", como em problemas de incêndio se espalhando a partir de vários pontos); **busca bidirecional** roda um BFS a partir da origem e outro a partir do destino simultaneamente, parando quando as duas fronteiras se encontram — reduz o espaço explorado de $O(b^d)$ para aproximadamente $O(2b^{d/2})$ em um grafo com fator de ramificação `b` e distância `d`, o que é significativo em grafos muito grandes (redes de estradas, redes sociais)."}]}, {"type": "subsection", "id": "comb-grafos-aplicacoes", "number": "5.4", "title": "Aplicações: compiladores, redes e escalonamento", "tag": "APLICACOES", "accent": "orange", "blocks": [{"type": "paragraph", "text": "A modelagem por grafos transforma relações em objetos que algoritmos conseguem percorrer. O tipo de grafo determina o teorema disponível: dependências acíclicas permitem ordenação topológica; ciclos indicam uma inconsistência ou uma dependência circular."}, {"type": "table", "header": ["Problema computacional", "Modelo", "Ferramenta combinatória"], "rows": [["ordem de compilação", "DAG de dependências", "ordenamento topológico"], ["rotas em uma rede", "grafo ponderado", "caminhos mínimos"], ["alocação de tarefas", "grafo bipartido", "emparelhamento (casamento máximo em grafo bipartido)"], ["capacidade de transporte", "rede capacitada", "fluxo máximo e corte mínimo"], ["conectividade de módulos", "grafo não dirigido", "BFS, DFS e árvores"]]}, {"type": "callout", "variant": "key", "title": "Como a prova orienta o código", "text": "O algoritmo não deve apenas produzir uma ordem ou fluxo. A prova identifica por que a estrutura existe, quais invariantes são preservados e em que condição a saída é ótima. Se o grafo violar a hipótese — por exemplo, contiver ciclo quando se exige um DAG — o código precisa detectar ou rejeitar a entrada."}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Grafos trouxeram um novo objeto combinatório, mas as ferramentas de prova continuam as mesmas: a equivalência entre árvore, n−1 arestas e caminho único é provada por indução (Seção 3), e a identidade do aperto de mãos (dupla contagem, também Seção 3) sustenta implicitamente a contagem de arestas. BFS, DFS e Dijkstra foram apresentados com invariante, prova de terminação e código — o mesmo roteiro de \"inicialização, manutenção, terminação\" da prova de correção de algoritmos (Seção 3.4) — e o exemplo numérico mostrou por que BFS, DFS e Dijkstra dão respostas diferentes no mesmo grafo (arestas × peso × ordem de visita). A extensão para pontes via low-link reaproveita exatamente disc/fim do DFS básico, e o 0-1 BFS mostra como uma restrição no problema (pesos só 0/1) permite trocar Dijkstra por algo mais simples e mais rápido — o mesmo tipo de raciocínio \"qual hipótese vale, e o que ela simplifica\" cobrado desde a Seção 1. Esses algoritmos retornam na Seção 7 como exemplos de programação dinâmica e análise de complexidade sobre estruturas discretas."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "probabilidade", "number": "6", "title": "Probabilidade discreta e método probabilístico", "blocks": [{"type": "paragraph", "text": "Probabilidade combina contagem com incerteza. O espaço amostral deve ser especificado antes da fórmula; “aleatório” sem distribuição não é um modelo.", "lead": true}, {"type": "subsection", "id": "comb-prob-basica", "number": "6.1", "title": "Espaço amostral, condicionamento e Bayes", "tag": "PROBABILIDADE", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Um espaço amostral $\\Omega$ contém resultados elementares; um evento `A` é um subconjunto de $\\Omega$; uma variável aleatória atribui números aos resultados. Em um espaço uniforme finito, $P(A)=|A|/|\\Omega|$."}, {"type": "heading", "level": 3, "text": "Teorema de Bayes"}, {"type": "paragraph", "text": "Para eventos `A` e `B` com probabilidades apropriadas, $P(A|B)=P(B|A)P(A)/P(B)$."}, {"type": "steps", "items": [{"title": "Definir condicional", "text": "$P(A|B)=P(A\\cap B)/P(B)$."}, {"title": "Trocar a ordem da interseção", "text": "A interseção é comutativa: $A\\cap B=B\\cap A$; então $P(A|B)=P(B\\cap A)/P(B)$."}, {"title": "Aplicar a outra condicional", "text": "De $P(B|A)=P(B\\cap A)/P(A)$, obtemos $P(B\\cap A)=P(B|A)P(A)$."}, {"title": "Substituir", "text": "Substitua no passo 2: $P(A|B)=P(B|A)P(A)/P(B)$."}]}, {"type": "heading", "level": 3, "text": "Independência"}, {"type": "paragraph", "text": "Eventos A e B são independentes quando $P(A\\cap B)=P(A)P(B)$. Isso é uma condição matemática; o fato de duas descrições usarem palavras diferentes não prova independência."}]}, {"type": "subsection", "id": "comb-esperanca", "number": "6.2", "title": "Indicadores, esperança e concentração", "tag": "METODO", "accent": "violet", "blocks": [{"type": "heading", "level": 3, "text": "Teorema: linearidade da esperança"}, {"type": "paragraph", "text": "Para variáveis aleatórias integráveis, $\\mathbb{E}[X+Y]=\\mathbb{E}[X]+\\mathbb{E}[Y]$, sem exigir independência."}, {"type": "steps", "items": [{"title": "Expandir pela definição", "text": "$\\mathbb{E}[X+Y]=\\sum_ω (X(ω)+Y(ω))P(ω)$."}, {"title": "Distribuir a soma", "text": "Como soma finita distribui, isso é $\\sum_ω X(ω)P(ω)+\\sum_ω Y(ω)P(ω)$."}, {"title": "Reconhecer expectativas", "text": "Os dois somatórios são $\\mathbb{E}[X]$ e $\\mathbb{E}[Y]$."}, {"title": "Concluir", "text": "Logo $\\mathbb{E}[X+Y]=\\mathbb{E}[X]+\\mathbb{E}[Y]$; repetir por indução dá a versão para n variáveis."}]}, {"type": "heading", "level": 3, "text": "Aplicação: número esperado de colisões"}, {"type": "paragraph", "text": "Lance `m` chaves em `b` baldes uniformes. Para cada par de chaves `i<j`, defina $I_ij=1$ se colidir. O número de colisões é $X=\\sum_{i<j} I_{ij}$."}, {"type": "steps", "items": [{"title": "Probabilidade de um par", "text": "Depois de fixar a primeira chave, a segunda coincide com seu balde com probabilidade `1/b`; portanto $\\mathbb{E}[I_ij]=1/b$."}, {"title": "Contar pares", "text": "Existem $\\binom{m}{2}$ pares de chaves."}, {"title": "Somar expectativas", "text": "Pela linearidade, $\\mathbb{E}[X]=\\sum\\mathbb{E}[I_ij]=\\binom{m}{2}/b$."}, {"title": "Observação", "text": "Os indicadores não precisam ser independentes para esta conclusão."}]}, {"type": "math", "tex": "\\mathbb{E}[X]=\\binom{m}{2}\\frac{1}{b}", "caption": "colisões esperadas"}, {"type": "paragraph", "text": "**Leitura da fórmula.** Leitura: o número esperado de colisões entre m chaves distribuídas uniformemente em b baldes é o número de pares de chaves, multiplicado pela probabilidade de um par colidir."}, {"type": "paragraph", "text": "Desigualdades de Markov, Chebyshev e Chernoff transformam esperança e variância em limites de cauda. Cada desigualdade deve ser aplicada apenas após verificar não negatividade, existência de momentos e independência quando a versão escolhida exigir."}]}, {"type": "subsection", "id": "comb-metodo-prob", "number": "6.3", "title": "Método probabilístico e algoritmos aleatorizados", "tag": "AVANCADO", "accent": "pink", "blocks": [{"type": "paragraph", "text": "O método probabilístico prova que um objeto existe mostrando que uma escolha aleatória tem probabilidade positiva de possuir a propriedade desejada. A demonstração pode não produzir um algoritmo construtivo; esse é um limite importante."}, {"type": "heading", "level": 3, "text": "Princípio da expectativa positiva"}, {"type": "paragraph", "text": "Se uma variável aleatória não negativa tem esperança positiva, existe pelo menos um resultado com valor positivo."}, {"type": "steps", "items": [{"title": "Supor o contrário", "text": "Suponha que todo resultado tenha valor 0."}, {"title": "Calcular a esperança", "text": "Se X é sempre 0, então $\\mathbb{E}[X]=0$ pela definição."}, {"title": "Contradizer", "text": "Isso contradiz $\\mathbb{E}[X]>0$."}, {"title": "Concluir", "text": "Logo algum resultado tem X>0; a estrutura correspondente existe."}]}, {"type": "paragraph", "text": "Em QuickSort aleatorizado, a escolha aleatória do pivô permite calcular a esperança sobre todas as ordens possíveis. Em hashing, a aleatoriedade reduz padrões adversariais. Sempre separe correção certa, correção com alta probabilidade, tempo esperado e pior caso."}]}, {"type": "subsection", "id": "comb-prob-aplicacoes", "number": "6.4", "title": "Aplicações: hashing, amostragem e sistemas aleatorizados", "tag": "APLICACOES", "accent": "orange", "blocks": [{"type": "paragraph", "text": "A probabilidade discreta permite analisar algoritmos cuja execução depende de escolhas aleatórias. A sequência lógica é: definir o espaço amostral, definir indicadores ou variáveis aleatórias, calcular a esperança ou uma probabilidade e interpretar o limite no comportamento do programa."}, {"type": "steps", "items": [{"title": "Hashing", "text": "Modele cada chave como uma escolha de balde. A casa dos pombos dá o limite inevitável; indicadores dão o número esperado de colisões."}, {"title": "Amostragem", "text": "Defina o conjunto de amostras e a distribuição. Sem distribuição uniforme ou ponderada explicitada, “amostra aleatória” não define uma probabilidade."}, {"title": "QuickSort aleatorizado", "text": "O pivô aleatório define uma distribuição sobre as partições. A análise calcula o custo esperado somando as probabilidades de cada par de elementos ser comparado."}, {"title": "Bloom filter", "text": "Cada hash ativa posições; a probabilidade de um bit continuar zero determina a taxa aproximada de falso positivo."}, {"title": "Garantia", "text": "Diferencie sempre pior caso, caso médio, esperança e probabilidade de falha. Uma esperança pequena não elimina execuções ruins."}]}, {"type": "callout", "variant": "warning", "title": "Hipóteses são parte do teorema", "text": "Independência, distribuição uniforme, limite de capacidade e tamanho do universo devem aparecer na prova. Remover uma hipótese pode invalidar a conclusão, mesmo que os primeiros testes pareçam iguais."}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "A probabilidade discreta reaproveitou a contagem das Seções 1–2 (espaço amostral uniforme = razão de cardinalidades), e a linearidade da esperança generalizou a regra da soma para variáveis aleatórias, sem exigir independência — a mesma cautela sobre hipóteses que a Seção 1 já cobrava ao definir universo e igualdade. O método probabilístico e o QuickSort aleatorizado preparam a Seção 7, onde hashing, Bloom filters e testes combinatórios aplicam essas mesmas ideias a algoritmos concretos."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "algoritmos-combinatoria", "number": "7", "title": "Aplicações em algoritmos e ciência da computação", "blocks": [{"type": "paragraph", "text": "A combinatória torna explícitos os estados que um algoritmo percorre, a memória que precisa armazenar e os limites que nenhuma implementação pode evitar. O objetivo é ligar prova de contagem a código executável.", "lead": true}, {"type": "paragraph", "text": "O capítulo deve ser lido como a aplicação dos capítulos anteriores: regras de contagem definem estados; bijeções justificam representações; recorrências descrevem transições; grafos representam dependências; probabilidade mede comportamento médio; e análise assintótica traduz a contagem em custo computacional."}, {"type": "subsection", "id": "comb-dp", "number": "7.1", "title": "Programação dinâmica e estados", "tag": "ALGORITMOS", "accent": "blue", "blocks": [{"type": "paragraph", "text": "Programação dinâmica resolve subproblemas sobrepostos guardando respostas. A prova de correção tem três partes: definir o estado, provar a transição e provar que a ordem de preenchimento respeita dependências."}, {"type": "heading", "level": 3, "text": "Exemplo: subconjuntos"}, {"type": "paragraph", "text": "Há $2^n$ subconjuntos de um conjunto de n elementos porque cada elemento tem duas decisões independentes: presente ou ausente."}, {"type": "steps", "items": [{"title": "Codificar", "text": "Use um bit por elemento; a máscara `mask` representa exatamente um subconjunto."}, {"title": "Provar unicidade", "text": "Duas máscaras diferentes têm algum bit diferente, logo representam escolhas diferentes."}, {"title": "Provar cobertura", "text": "Para qualquer subconjunto, marque 1 nos elementos presentes e 0 nos ausentes; a máscara correspondente existe."}, {"title": "Contar", "text": "A bijeção entre máscaras de n bits e subconjuntos dá $2^n$ estados."}, {"title": "Implicação", "text": "Uma DP sobre todos os subconjuntos pode consumir tempo ou memória exponencial; a fórmula é um limite estrutural, não um detalhe de implementação."}]}, {"type": "svg", "alt": "Multiplicação de matrizes: uma matriz A de m por n vezes uma matriz B de n por p produz uma matriz C de m por p; cada célula é o produto escalar de uma linha por uma coluna.", "caption": "Visualização: cada célula de C é uma soma de produtos; a dimensão n é a dimensão compartilhada.", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 980 360\" role=\"img\" aria-labelledby=\"matrix-title matrix-desc\" class=\"diagram diagram-matrix\"><title id=\"matrix-title\">Multiplicação de matrizes como soma de produtos</title><desc id=\"matrix-desc\">Matriz A de m por n ligada a matriz B de n por p produz matriz C de m por p. Uma célula de C destaca o produto de uma linha de A por uma coluna de B.</desc><defs><marker id=\"mat-arrow\" markerWidth=\"10\" markerHeight=\"10\" refX=\"9\" refY=\"5\" orient=\"auto\"><path d=\"M0 0L10 5L0 10Z\" fill=\"#74d3c8\"/></marker></defs><rect width=\"980\" height=\"360\" rx=\"18\" fill=\"#111a22\"/><text x=\"32\" y=\"38\" fill=\"#e5f8f4\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"700\">Produto matricial e programação dinâmica</text><text x=\"32\" y=\"64\" fill=\"#aab9c5\" font-family=\"sans-serif\" font-size=\"13\">A dimensão compartilhada n determina a soma; cada célula pode ser vista como um subproblema.</text><text x=\"86\" y=\"112\" fill=\"#f7c978\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"700\">A</text><text x=\"240\" y=\"112\" fill=\"#9ce8dd\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"700\">B</text><text x=\"735\" y=\"112\" fill=\"#91b9ff\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"700\">C = A·B</text><g stroke=\"#f7c978\" stroke-width=\"2\" fill=\"#2b3540\"><rect x=\"55\" y=\"130\" width=\"120\" height=\"150\" rx=\"8\"/><path d=\"M95 130v150M135 130v150M55 180h120M55 230h120\"/></g><g fill=\"#f7c978\" font-family=\"monospace\" font-size=\"16\" text-anchor=\"middle\"><text x=\"75\" y=\"163\">a₁₁</text><text x=\"115\" y=\"163\">a₁₂</text><text x=\"155\" y=\"163\">…</text><text x=\"75\" y=\"213\">a₂₁</text><text x=\"115\" y=\"213\">a₂₂</text><text x=\"155\" y=\"213\">…</text><text x=\"75\" y=\"263\">⋮</text><text x=\"115\" y=\"263\">⋮</text><text x=\"155\" y=\"263\">⋱</text></g><g stroke=\"#9ce8dd\" stroke-width=\"2\" fill=\"#2b3540\"><rect x=\"220\" y=\"130\" width=\"160\" height=\"150\" rx=\"8\"/><path d=\"M260 130v150M300 130v150M340 130v150M220 180h160M220 230h160\"/></g><g fill=\"#9ce8dd\" font-family=\"monospace\" font-size=\"16\" text-anchor=\"middle\"><text x=\"240\" y=\"163\">b₁₁</text><text x=\"280\" y=\"163\">b₁₂</text><text x=\"320\" y=\"163\">…</text><text x=\"360\" y=\"163\">b₁p</text><text x=\"240\" y=\"213\">b₂₁</text><text x=\"280\" y=\"213\">b₂₂</text><text x=\"320\" y=\"213\">…</text><text x=\"360\" y=\"213\">b₂p</text><text x=\"240\" y=\"263\">⋮</text><text x=\"280\" y=\"263\">⋮</text><text x=\"320\" y=\"263\">⋱</text><text x=\"360\" y=\"263\">bₙp</text></g><path d=\"M390 205h300\" stroke=\"#74d3c8\" stroke-width=\"3\" marker-end=\"url(#mat-arrow)\"/><text x=\"475\" y=\"190\" fill=\"#b8d8d3\" font-family=\"sans-serif\" font-size=\"13\">linha × coluna</text><g stroke=\"#91b9ff\" stroke-width=\"2\" fill=\"#2b3540\"><rect x=\"710\" y=\"130\" width=\"190\" height=\"150\" rx=\"8\"/><path d=\"M758 130v150M806 130v150M854 130v150M710 180h190M710 230h190\"/><rect x=\"710\" y=\"180\" width=\"48\" height=\"50\" fill=\"#31527c\" stroke=\"#b8d4ff\" stroke-width=\"3\"/></g><g fill=\"#b8d4ff\" font-family=\"monospace\" font-size=\"15\" text-anchor=\"middle\"><text x=\"734\" y=\"163\">c₁₁</text><text x=\"782\" y=\"163\">c₁₂</text><text x=\"830\" y=\"163\">…</text><text x=\"878\" y=\"163\">c₁p</text><text x=\"734\" y=\"213\">c₂₁</text><text x=\"782\" y=\"213\">c₂₂</text><text x=\"830\" y=\"213\">…</text><text x=\"878\" y=\"213\">c₂p</text><text x=\"734\" y=\"263\">⋮</text><text x=\"782\" y=\"263\">⋮</text><text x=\"830\" y=\"263\">⋱</text><text x=\"878\" y=\"263\">cₘp</text></g><text x=\"32\" y=\"324\" fill=\"#d5e4ed\" font-family=\"monospace\" font-size=\"14\">cᵢⱼ = Σₖ aᵢₖ bₖⱼ</text><text x=\"335\" y=\"324\" fill=\"#aab9c5\" font-family=\"sans-serif\" font-size=\"13\">m×n · n×p = m×p</text><text x=\"600\" y=\"324\" fill=\"#aab9c5\" font-family=\"sans-serif\" font-size=\"13\">A dimensão n é eliminada pela soma.</text></svg>"}, {"type": "svg", "alt": "Máscaras de bits: cada posição de um vetor corresponde a um elemento e o bit 1 indica que o elemento pertence ao subconjunto.", "caption": "Visualização: bijeção entre máscaras de n bits e subconjuntos.", "svg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 980 260\" role=\"img\" aria-labelledby=\"bits-title bits-desc\" class=\"diagram diagram-bitmask\"><title id=\"bits-title\">Máscara de bits como subconjunto</title><desc id=\"bits-desc\">Quatro bits 1, 0, 1, 1 correspondem aos elementos a, b, c, d; os bits 1 selecionam a, c e d.</desc><rect width=\"980\" height=\"260\" rx=\"18\" fill=\"#111a22\"/><text x=\"32\" y=\"38\" fill=\"#e5f8f4\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"700\">Bitmask ↔ subconjunto</text><text x=\"32\" y=\"64\" fill=\"#aab9c5\" font-family=\"sans-serif\" font-size=\"13\">A correspondência é bijetiva: cada bit decide presença ou ausência de um elemento.</text><text x=\"60\" y=\"105\" fill=\"#91b9ff\" font-family=\"monospace\" font-size=\"15\">elemento</text><text x=\"60\" y=\"180\" fill=\"#f7c978\" font-family=\"monospace\" font-size=\"15\">bit</text><g font-family=\"monospace\" font-size=\"18\" text-anchor=\"middle\"><rect x=\"170\" y=\"82\" width=\"130\" height=\"58\" rx=\"10\" fill=\"#25476d\" stroke=\"#91b9ff\" stroke-width=\"2\"/><rect x=\"310\" y=\"82\" width=\"130\" height=\"58\" rx=\"10\" fill=\"#243442\" stroke=\"#718493\" stroke-width=\"2\"/><rect x=\"450\" y=\"82\" width=\"130\" height=\"58\" rx=\"10\" fill=\"#25476d\" stroke=\"#91b9ff\" stroke-width=\"2\"/><rect x=\"590\" y=\"82\" width=\"130\" height=\"58\" rx=\"10\" fill=\"#25476d\" stroke=\"#91b9ff\" stroke-width=\"2\"/><text x=\"235\" y=\"118\" fill=\"#d7eaff\">a</text><text x=\"375\" y=\"118\" fill=\"#c3d0da\">b</text><text x=\"515\" y=\"118\" fill=\"#d7eaff\">c</text><text x=\"655\" y=\"118\" fill=\"#d7eaff\">d</text><rect x=\"170\" y=\"155\" width=\"130\" height=\"58\" rx=\"10\" fill=\"#6b4d20\" stroke=\"#f7c978\" stroke-width=\"2\"/><rect x=\"310\" y=\"155\" width=\"130\" height=\"58\" rx=\"10\" fill=\"#303942\" stroke=\"#718493\" stroke-width=\"2\"/><rect x=\"450\" y=\"155\" width=\"130\" height=\"58\" rx=\"10\" fill=\"#6b4d20\" stroke=\"#f7c978\" stroke-width=\"2\"/><rect x=\"590\" y=\"155\" width=\"130\" height=\"58\" rx=\"10\" fill=\"#6b4d20\" stroke=\"#f7c978\" stroke-width=\"2\"/><text x=\"235\" y=\"191\" fill=\"#fff0c7\">1</text><text x=\"375\" y=\"191\" fill=\"#c3d0da\">0</text><text x=\"515\" y=\"191\" fill=\"#fff0c7\">1</text><text x=\"655\" y=\"191\" fill=\"#fff0c7\">1</text></g><path d=\"M770 183h130\" stroke=\"#74d3c8\" stroke-width=\"3\" marker-end=\"url(#mat-arrow)\"/><text x=\"785\" y=\"164\" fill=\"#b8d8d3\" font-family=\"sans-serif\" font-size=\"13\">mask = 1101₂</text><text x=\"785\" y=\"208\" fill=\"#b8d8d3\" font-family=\"sans-serif\" font-size=\"13\">{a,c,d}</text></svg>"}, {"type": "code", "language": "cpp", "title": "Enumeração de submáscaras", "code": "for (std::uint64_t sub = mask; ; sub = (sub - 1) & mask) {\n    process(sub);\n    if (sub == 0) break;\n}"}]}, {"type": "subsection", "id": "comb-complexidade", "number": "7.2", "title": "Complexidade assintótica e limites", "tag": "ANALISE", "accent": "teal", "blocks": [{"type": "paragraph", "text": "$O(g(n))$ é um limite superior assintótico, $\\Omega(g(n))$ um limite inferior e $\\Theta(g(n))$ ambos. Eles descrevem crescimento para n grande, não segundos exatos. Constantes, hierarquia de memória, distribuição de entradas e paralelismo continuam relevantes."}, {"type": "heading", "level": 3, "text": "Prova: soma de 1 até n é Θ(n²)"}, {"type": "paragraph", "text": "Considere $T(n)=\\sum_{i=1}^n i$."}, {"type": "steps", "items": [{"title": "Limite superior", "text": "Cada termo é no máximo n; há n termos. Logo $T(n)\\le n\\cdot n=n^2$, portanto $T(n)=O(n²)$."}, {"title": "Limite inferior", "text": "Os últimos $\\lfloor n/2\\rfloor$ termos são pelo menos $n/2$; logo $T(n)\\ge \\lfloor n/2\\rfloor\\cdot(n/2)$, que é pelo menos uma constante vezes `n²` para n grande."}, {"title": "Concluir", "text": "Há constantes positivas c e C com $c n²\\le T(n)\\le C n²$; portanto $T(n)=\\Theta(n²)$."}]}, {"type": "heading", "level": 3, "text": "Cuidado com C++"}, {"type": "paragraph", "text": "Uma fórmula combinatória que cresce além de `uint64_t` não pode ser calculada ingenuamente. Overflow assinado é comportamento indefinido; overflow sem sinal é módulo $2^N$, que pode preservar a execução mas destruir o significado da contagem. Use limites, saturação, módulo ou inteiros arbitrários conforme o problema."}]}, {"type": "subsection", "id": "comb-info", "number": "7.3", "title": "Hashing, compressão, testes e cobertura", "tag": "APLICACOES", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Hashing distribui chaves em baldes; a casa dos pombos garante colisões quando há mais chaves que baldes. Bloom filters usam vários hashes e aceitam falsos positivos para economizar memória. Testes combinatórios selecionam combinações de parâmetros para cobrir interações de ordem dois ou maior."}, {"type": "table", "header": ["Aplicação", "Modelo combinatório", "Pergunta"], "rows": [["hashing", "ocupação de b baldes", "qual a probabilidade de colisão?"], ["Bloom filter", "bits e funções hash", "qual a taxa de falso positivo?"], ["compressão", "palavras e frequências", "quantos códigos prefixo-livre (nenhum código é prefixo de outro) existem?"], ["testes", "produto cartesiano de parâmetros", "quais combinações cobrem pares?"], ["compiladores", "DAG de dependências", "qual ordem topológica é válida?"]]}, {"type": "callout", "variant": "example", "title": "Exercício orientado", "text": "Para 10 chaves e 100 baldes, derive a probabilidade de nenhuma colisão. Comece contando sequências sem colisão, divida pelo número de sequências totais e explique cada fator."}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Esta seção uniu tudo: os estados de uma DP são contados com a regra do produto (Seção 1), a enumeração de submáscaras usa a mesma bijeção máscara↔subconjunto provada na Seção 1, e a análise assintótica formaliza o crescimento que já aparecia informalmente nas recorrências das Seções 3 e 4. Hashing e Bloom filters recuperam a casa dos pombos (Seção 1) e a esperança de colisões calculada na Seção 6. A Seção 8 continua essa aplicação com ferramentas ainda mais avançadas (Burnside, matroides) para os casos em que contagem direta superconta ou exige escolha gulosa."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "topicos-avancados", "number": "8", "title": "Tópicos avançados: simetria, partições e estruturas extremas", "blocks": [{"type": "paragraph", "text": "Este capítulo fecha o percurso com ferramentas usadas em cursos universitários avançados. As provas são apresentadas em escala compacta, mas cada passo identifica o objeto contado e a razão da igualdade.", "lead": true}, {"type": "subsection", "id": "comb-particoes", "number": "8.1", "title": "Partições e números de Stirling", "tag": "AVANCADO", "accent": "violet", "blocks": [{"type": "paragraph", "text": "Uma partição de um conjunto divide seus elementos em blocos não vazios, sem ordem entre os blocos. O número de Stirling de segunda espécie $S(n,k)$ conta partições de n elementos em k blocos."}, {"type": "heading", "level": 3, "text": "Recorrência de Stirling"}, {"type": "paragraph", "text": "$S(n,k)=S(n-1,k-1)+kS(n-1,k)$."}, {"type": "steps", "items": [{"title": "Fixar o novo elemento", "text": "Considere o elemento n."}, {"title": "Caso isolado", "text": "Se ele forma sozinho um bloco, os n-1 elementos restantes formam k-1 blocos: $S(n-1,k-1)$."}, {"title": "Caso não isolado", "text": "Se entra em um bloco existente, primeiro particione os n-1 elementos em k blocos e depois escolha um dos k blocos: $kS(n-1,k)$."}, {"title": "Disjunção e cobertura", "text": "Os casos são disjuntos e cobrem toda partição."}, {"title": "Conclusão", "text": "A soma dos casos produz a recorrência."}]}, {"type": "code", "language": "cpp", "title": "Tabela de Stirling via recorrência", "code": "std::vector<std::vector<long long>> S(n+1, std::vector<long long>(n+1, 0));\nS[0][0] = 1;\nfor (int i = 1; i <= n; ++i)\n    for (int k = 1; k <= i; ++k)\n        S[i][k] = S[i-1][k-1] + (long long)k * S[i-1][k];\n// S[i][k] agora contém S(i,k), na mesma estrutura do triângulo de Pascal (Seção 2.2)", "highlight": "", "lineNumbers": false}, {"type": "callout", "variant": "example", "title": "Conferindo S(4,2)", "text": "Particionar `{1,2,3,4}` em 2 blocos não vazios dá 7 partições: `{1}{234}`, `{2}{134}`, `{3}{124}`, `{4}{123}`, `{12}{34}`, `{13}{24}`, `{14}{23}`. Pela recorrência: $S(4,2)=S(3,1)+2\\cdot S(3,2)=1+2\\cdot3=7$ — bate com a contagem direta."}]}, {"type": "subsection", "id": "comb-simetria", "number": "8.2", "title": "Burnside e enumeração sob simetria", "tag": "SIMETRIA", "accent": "pink", "blocks": [{"type": "paragraph", "text": "Quando rotações ou renomeações tornam configurações equivalentes, contar diretamente superconta. Um grupo atua sobre as configurações; a órbita de uma configuração é o conjunto obtido por essas transformações."}, {"type": "heading", "level": 3, "text": "Lema de Burnside"}, {"type": "paragraph", "text": "O número de órbitas é a média, sobre os elementos do grupo, do número de configurações fixadas por cada elemento."}, {"type": "steps", "items": [{"title": "Contar pares fixos", "text": "Considere pares `(g,x)` em que a transformação g fixa a configuração x."}, {"title": "Contar por transformações", "text": "Para cada g, há $\\operatorname{Fix}(g)$ configurações fixadas; o total de pares é $\\sum_g \\operatorname{Fix}(g)$."}, {"title": "Contar por configurações", "text": "Uma configuração x é contada tantas vezes quanto o tamanho do seu estabilizador, o conjunto de transformações que a fixa."}, {"title": "Relacionar órbita e estabilizador", "text": "Pelo teorema órbita-estabilizador, $|órbita(x)|\\cdot|estabilizador(x)|=|G|$."}, {"title": "Somar por órbitas", "text": "Cada órbita contribui `|G|` pares: somando os estabilizadores de seus elementos."}, {"title": "Dividir", "text": "O número de pares é `|G|` vezes o número de órbitas. Dividir por `|G|` dá a média."}]}, {"type": "math", "tex": "\\#(X/G)=\\frac{1}{\\lvert G\\rvert}\\sum_{g\\in G}\\lvert Fix(g)\\rvert", "caption": "lema de Burnside"}, {"type": "paragraph", "text": "**Leitura da fórmula.** Leitura: o número de órbitas de X sob a ação de G é a soma, para cada transformação g, do número de configurações fixadas por g, dividida pela quantidade de transformações do grupo."}, {"type": "code", "language": "cpp", "title": "Verificação por força bruta: colares de 3 contas, 2 cores, sob rotação", "code": "int n = 3, cores = 2;\nlong long total_fix = 0;\nfor (int g = 0; g < n; ++g) {          // g = quantas posições a rotação desloca\n    int ciclos = std::gcd(g, n);        // std::gcd(0,n) == n: identidade tem n ciclos de tamanho 1\n    total_fix += (long long)std::pow(cores, ciclos);\n}\n// órbitas = total_fix / n  (lema de Burnside)", "highlight": "", "lineNumbers": false}, {"type": "callout", "variant": "example", "title": "Contando as órbitas à mão", "text": "Grupo cíclico de 3 rotações em um colar de 3 contas com 2 cores: a identidade fixa todas as $2^3=8$ colorações; cada uma das duas rotações não triviais só fixa colorações monocromáticas ($2^1=2$ cada, pois todo ciclo tem as 3 posições juntas). Pelo lema de Burnside, o número de colares distintos é $(8+2+2)/3=4$ — confirmável listando: todo-branco, todo-preto, uma-preta-duas-brancas, duas-pretas-uma-branca."}]}, {"type": "subsection", "id": "comb-matroides", "number": "8.3", "title": "Matroides, gulosos e teoria extremal", "tag": "ESTRUTURAS", "accent": "teal", "blocks": [{"type": "paragraph", "text": "Uma matroide abstrai uma família de conjuntos independentes que é hereditária e satisfaz a propriedade de aumento. Independência linear e florestas de um grafo são exemplos. O algoritmo guloso funciona em matroides porque uma escolha local pode ser trocada por uma escolha de uma solução ótima sem perder independência."}, {"type": "heading", "level": 3, "text": "Esqueleto da prova de correção gulosa"}, {"type": "steps", "items": [{"title": "Escolher o primeiro elemento guloso", "text": "Ordene elementos por peso e escolha o maior que mantém independência."}, {"title": "Comparar com uma solução ótima", "text": "Se a solução ótima já contém o elemento, nada muda."}, {"title": "Troca", "text": "Se não contém, a propriedade de aumento e a estrutura de matroide permitem substituir um elemento escolhido pela solução pelo elemento guloso, preservando independência."}, {"title": "Não piorar peso", "text": "Como o guloso escolheu um elemento não menor, o peso não diminui."}, {"title": "Induzir", "text": "Repita no conjunto restante; a solução gulosa alcança o valor ótimo."}]}, {"type": "callout", "variant": "note", "title": "Escopo", "text": "A afirmação de que “guloso sempre funciona” é falsa em geral. A prova depende da propriedade estrutural da matroide; em problemas arbitrários, uma escolha local pode bloquear a solução global."}, {"type": "code", "language": "cpp", "title": "Kruskal: o algoritmo guloso da Seção 8.3 aplicado à matroide gráfica", "code": "std::sort(arestas.begin(), arestas.end());   // por peso crescente\nUnionFind uf(n);\nlong long custo = 0;\nfor (auto& [peso, u, v] : arestas) {\n    if (uf.find(u) != uf.find(v)) {   // testa independência: não fecha ciclo\n        uf.unite(u, v);\n        custo += peso;\n    }\n}\n// o conjunto de arestas aceitas é a base de peso mínimo da matroide gráfica", "highlight": "", "lineNumbers": false}, {"type": "callout", "variant": "key", "title": "Por que Kruskal é o exemplo canônico", "text": "Os conjuntos independentes da matroide gráfica são exatamente as florestas (subconjuntos de arestas sem ciclo) — a mesma matroide citada na definição desta subseção. `uf.find(u) != uf.find(v)` testa independência (não cria ciclo); a propriedade de aumento garante que a escolha gulosa por peso crescente nunca precisa ser desfeita. É a mesma prova de correção gulosa apresentada acima, aplicada ao caso concreto de árvore geradora mínima."}]}, {"type": "callout", "variant": "key", "title": "Em síntese", "text": "Os números de Stirling generalizam a ideia de partição que a Seção 1 já explorava com subconjuntos, e a tabela por recorrência reaproveita exatamente a técnica do triângulo de Pascal (Seção 2.2). O lema de Burnside resolve \"contar sob simetria\" com a mesma técnica de dupla contagem de pares provada na Seção 3 — o exemplo dos colares mostra o lema batendo com uma contagem direta. E a prova de correção do algoritmo guloso em matroides, aplicada a Kruskal, segue o mesmo roteiro de troca e indução usado para provar propriedades de árvores na Seção 5, com o teste de independência reduzido a um simples union-find. Este capítulo fecha o percurso teórico do livro — os Exercícios (Seção 9) pedem para aplicar essas mesmas técnicas de ponta a ponta."}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "exercicios", "number": "9", "title": "Exercícios graduais e laboratório de provas", "blocks": [{"type": "paragraph", "text": "Resolva os exercícios escrevendo o conjunto contado, a decomposição em casos e a prova. Um resultado numérico sem justificativa não é considerado solução completa.", "lead": true}, {"type": "subsection", "id": "comb-ex-basico", "number": "9.1", "title": "Fundamentos e contagem", "tag": "EXERCICIOS", "accent": "blue", "blocks": [{"type": "list", "style": "number", "items": ["Prove por bijeção que o número de subconjuntos de um conjunto de n elementos é `2^n`.", "Conte strings binárias de comprimento n que não possuem dois 1 consecutivos; derive e prove a recorrência.", "Use estrelas e barras para contar soluções positivas de `x1+x2+x3+x4=20`.", "Prove a identidade `kC(n,k)=nC(n-1,k-1)` contando pares (subconjunto, elemento marcado)."]}]}, {"type": "subsection", "id": "comb-ex-prob", "number": "9.2", "title": "Probabilidade e algoritmos", "tag": "EXERCICIOS", "accent": "orange", "blocks": [{"type": "list", "style": "number", "items": ["Derive passo a passo a probabilidade de nenhuma colisão ao inserir m chaves em b baldes uniformes.", "Use indicadores para calcular o número esperado de vértices isolados em um grafo aleatório.", "Prove que uma árvore com n vértices tem n−1 arestas usando indução por remoção de folha.", "Projete uma DP para cobertura de tabuleiro e prove estado, transição, base e complexidade."]}, {"type": "callout", "variant": "key", "title": "Formato de uma solução completa", "text": "Uma solução deve conter: definição do universo; lema auxiliar, se necessário; contagem por casos; prova de que os casos são disjuntos; prova de que cobrem o universo; simplificação algébrica; e análise de limites ou hipóteses."}]}, {"type": "subsection", "id": "comb-ex-provas", "number": "9.3", "title": "Roteiro de autorrevisão", "tag": "METODO", "accent": "violet", "blocks": [{"type": "list", "style": "check", "items": ["A fórmula foi deduzida ou apenas citada?", "Cada transformação algébrica explica qual operação foi feita?", "Em uma indução, o caso-base e o passo usam exatamente a mesma proposição?", "Uma recorrência tem casos-base suficientes?", "Uma aplicação probabilística declarou distribuição e independência?", "Uma aplicação em C++ separou matemática do comportamento definido pela linguagem, overflow e representação?", "A notação foi definida antes de ser usada?"]}]}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "referencias", "number": "10", "title": "Referências e trilhas de aprofundamento", "blocks": [{"type": "paragraph", "text": "As referências abaixo sustentam o percurso do livro. Use-as para comparar definições, consultar provas alternativas e avançar para teoria de enumeração, probabilidade e algoritmos."}, {"type": "list", "style": "bullet", "items": ["[MIT 6.042J Mathematics for Computer Science](https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-fall-2010/) — lógica, provas, contagem, grafos e probabilidade.", "[MIT 18.226 Probabilistic Methods in Combinatorics](https://ocw.mit.edu/courses/18-226-probabilistic-methods-in-combinatorics-fall-2022/) — método probabilístico e combinatória avançada.", "[Applied Combinatorics — Mathematics LibreTexts](https://math.libretexts.org/Bookshelves/Combinatorics_and_Discrete_Mathematics/Applied_Combinatorics_(Kanade)) — enumeração, recorrências e estruturas.", "[Richard Stanley, Enumerative Combinatorics](https://math.mit.edu/~rstan/ec/) — funções geradoras e enumeração avançada.", "[Graham, Knuth e Patashnik, Concrete Mathematics](https://www.cs.cmu.edu/~ckingsf/bioinfo-lectures/concrete-math.pdf) — somas, recorrências e provas.", "[Diestel, Graph Theory](https://diestel-graph-theory.com/) — grafos e resultados estruturais.", "[Cormen et al., Introduction to Algorithms](https://mitpress.mit.edu/9780262046305/introduction-to-algorithms/) — programação dinâmica, grafos e análise.", "[NIST Digital Library of Mathematical Functions](https://dlmf.nist.gov/) — funções especiais e identidades matemáticas.", "[C++ working draft](https://eel.is/c++draft/) — máquina abstrata, tipos, representação e comportamento da linguagem para as aplicações em C++."]}, {"type": "callout", "variant": "info", "title": "Nota metodológica", "text": "As provas deste livro são apresentadas para as hipóteses declaradas. Quando uma fórmula tiver uma generalização, a generalização precisa de nova prova ou de uma referência explícita; não se deve extrapolar uma identidade apenas porque os primeiros casos coincidem."}]}], "imageRights": {"images/history-euler.jpg": {"source": "Busca de imagens na internet; página de origem registrada no relatório de revisão", "license": "Direitos não determinados na fonte de busca; substituir antes de publicação comercial", "credit": "Fonte de imagem consultada", "retrievedAt": "2026-09-24"}}}, "programacao-competitiva-cpp": {"manifest": {"schema": "books.package.v2", "kind": "book-package", "id": "programacao-competitiva-cpp", "title": "Programação Competitiva em C++: do básico ao avançado", "description": "Curso completo e moderno de programação competitiva em C++, com algoritmos, estruturas de dados, matemática, grafos, strings, DP, engenharia de contest e trilhas de prática.", "language": "pt-BR", "tags": ["c++", "programação competitiva", "algoritmos", "estruturas de dados", "ICPC", "CSES"], "header": "header.json", "sections": ["sections/cpp-e-analise-assintotica.json", "sections/fundamentos-e-metodo.json", "sections/cpp-moderno-stl.json", "sections/ordenacao-busca-gulosos.json", "sections/prefixos-janelas.json", "sections/dp.json", "sections/grafos-basicos.json", "sections/grafos-avancados.json", "sections/estruturas-arvore.json", "sections/strings.json", "sections/matematica.json", "sections/tecnicas-avancadas.json", "sections/engenharia-contest.json"]}, "header": {"schema": "books.header.v2", "kind": "book-header", "kicker": "curso completo · c++ / algoritmos / competições", "title": "Programação Competitiva em C++: do básico ao avançado", "subtitle": "Aprenda a modelar, provar, implementar e otimizar soluções — da primeira busca binária ao fluxo e às técnicas avançadas.", "guideTitle": "Como usar este livro", "guideText": "Leia as seções em ordem nas primeiras passagens. Depois use o sumário como referência: tente os exercícios do CSES ou de outra plataforma antes de consultar uma solução, escreva a prova em poucas linhas e faça testes adversariais.", "cover": {"src": "cover.svg", "alt": "Capa abstrata com uma grade de nós, arestas e símbolos de código", "ratio": "16:9"}, "legend": [{"label": "ideia", "color": "blue"}, {"label": "implementação", "color": "teal"}, {"label": "atenção", "color": "amber"}, {"label": "avançado", "color": "violet"}, {"label": "correção", "color": "red"}], "footer": "Material didático autoral em português, inspirado em referências públicas da comunidade. Consulte as licenças e links da seção final."}, "sections": [{"schema": "books.section.v2", "kind": "book-section", "id": "cpp-e-analise-assintotica", "number": "0", "title": "C++ essencial e eficiência assintótica", "blocks": [{"type": "paragraph", "text": "Antes de estudar algoritmos, domine o vocabulário da linguagem e aprenda a estimar custo. Uma solução correta que excede tempo ou memória também falha; eficiência é parte da especificação.", "lead": true}, {"type": "heading", "level": 3, "text": "Tipos, escopo e funções"}, {"type": "paragraph", "text": "Use `int` para índices e valores pequenos, `long long` para contagens e somas grandes, `size_t` com cuidado ao comparar com inteiros e `const` para declarar o que não deve ser alterado. Uma função deve ter uma responsabilidade clara e nomes que revelem a intenção."}, {"type": "code", "language": "cpp", "code": "#include <bits/stdc++.h>\nusing namespace std;\n\n// Retorna a soma dos elementos no intervalo [firstIndex, lastIndex).\nlong long sumRange(const vector<long long>& values, int firstIndex, int lastIndex) {\n    long long rangeSum = 0;\n    for (int currentIndex = firstIndex; currentIndex < lastIndex; ++currentIndex) {\n        rangeSum += values[currentIndex];\n    }\n    return rangeSum;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    int valueCount;\n    cin >> valueCount;\n    vector<long long> values(valueCount);\n    for (long long& value : values) cin >> value;\n    cout << sumRange(values, 0, valueCount) << \"\\n\";\n}", "lineNumbers": true, "title": "Função pura com nomes descritivos"}, {"type": "heading", "level": 3, "text": "Referências, ponteiros e classes"}, {"type": "paragraph", "text": "Uma referência é um apelido que deve referir-se a um objeto válido; uma referência constante evita cópia sem permitir alteração. Um ponteiro pode ser nulo e representa explicitamente a possibilidade de ausência. Classes agrupam estado e invariantes; em competições, structs simples costumam ser suficientes."}, {"type": "code", "language": "cpp", "code": "class Counter {\nprivate:\n    int currentValue;\n\npublic:\n    explicit Counter(int initialValue) : currentValue(initialValue) {}\n\n    void increment() { ++currentValue; }\n    int value() const { return currentValue; }\n};\n\nvoid addOne(int& mutableValue) { ++mutableValue; }\nvoid printIfPresent(const int* optionalValue) {\n    if (optionalValue != nullptr) cout << *optionalValue << \"\\n\";\n}", "lineNumbers": true, "title": "Encapsulamento e passagem por referência"}, {"type": "heading", "level": 3, "text": "Como medir tempo e memória"}, {"type": "paragraph", "text": "Conte operações dominantes em função do tamanho da entrada. Um laço simples é `O(n)`; dois laços aninhados, `O(n²)`; reduzir o intervalo pela metade, `O(log n)`; ordenar, geralmente `O(n log n)`. Para memória, conte arrays, tabelas, filas e a pilha de chamadas — não conte variáveis escalares como se fossem vetores."}, {"type": "table", "header": ["Código ou estrutura", "Tempo", "Memória adicional"], "rows": [["Uma passagem por vetor", "O(n)", "O(1)"], ["Duas passagens independentes", "O(n)", "O(1)"], ["Dois laços aninhados sobre n", "O(n²)", "O(1)"], ["Ordenar e depois percorrer", "O(n log n)", "depende do sort"], ["DP em tabela n×m", "O(nm)", "O(nm)"], ["BFS em grafo", "O(V+E)", "O(V)"]], "caption": "Como ler a ordem de crescimento"}, {"type": "math", "tex": "T(n)=2T(n/2)+O(n)=O(n\\log n)", "caption": "Exemplo de recorrência"}, {"type": "callout", "variant": "warning", "text": "Não use benchmarking de um único caso para “provar” complexidade. O computador, o compilador e a entrada mudam; a análise deve explicar o pior caso e o espaço ocupado.", "title": "Assintótico vem antes do cronômetro"}, {"type": "heading", "level": 3, "text": "Recursão e pilha"}, {"type": "code", "language": "cpp", "code": "// A profundidade é logarítmica porque o intervalo é dividido ao meio.\nint binarySearch(const vector<int>& sortedValues, int targetValue) {\n    int leftIndex = 0, rightIndex = (int)sortedValues.size() - 1;\n    while (leftIndex <= rightIndex) {\n        int middleIndex = leftIndex + (rightIndex - leftIndex) / 2;\n        if (sortedValues[middleIndex] == targetValue) return middleIndex;\n        if (sortedValues[middleIndex] < targetValue) leftIndex = middleIndex + 1;\n        else rightIndex = middleIndex - 1;\n    }\n    return -1;\n}", "lineNumbers": true, "title": "Busca binária iterativa e segura"}, {"type": "callout", "variant": "tip", "text": "Antes de otimizar, escreva uma tabela com: limite de entrada, complexidade de tempo, memória e justificativa. Essa disciplina evita escolher `O(n²)` quando o limite exige `O(n log n)`.", "title": "Ficha de complexidade"}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "fundamentos-e-metodo", "number": "1", "title": "Como pensar, estudar e medir soluções", "blocks": [{"type": "paragraph", "text": "Programação competitiva é a prática de transformar uma especificação em um algoritmo correto, eficiente e implementável sob limites rígidos de tempo e memória. Este livro começa pelo raciocínio e termina em técnicas que aparecem em finais nacionais e competições internacionais.", "lead": true}, {"type": "heading", "level": 3, "text": "O ciclo de uma solução"}, {"type": "paragraph", "text": "Leia o enunciado como um contrato: identifique a entrada, a saída, as restrições, a definição exata de cada termo e os casos extremos. Depois modele o problema, estime a complexidade, prove a ideia em poucas frases, implemente e teste adversarialmente."}, {"type": "list", "style": "number", "items": ["**Modelo:** reduza a história a objetos matemáticos — sequência, grafo, intervalo, estado ou fluxo.", "**Limites:** transforme `n ≤ 2·10^5` em uma meta de aproximadamente `O(n log n)`; `O(n²)` costuma ser inviável.", "**Invariante:** escreva o que permanece verdadeiro depois de cada iteração ou transição.", "**Validação:** teste mínimo, máximo, repetição, ordenação inversa, valores iguais e estruturas degeneradas."]}, {"type": "table", "header": ["Complexidade", "Quando costuma caber"], "rows": [["`O(1)`, `O(log n)`", "praticamente sempre"], ["`O(n)`, `O(n log n)`", "até milhões, conforme constante"], ["`O(n√n)`", "depende dos limites e da linguagem"], ["`O(n²)`", "tipicamente até alguns milhares"], ["`O(2^n)`", "somente `n` pequeno, cerca de 20–25"], ["`O(n!)`", "somente enumerações muito pequenas"]], "caption": "Orçamento assintótico aproximado"}, {"type": "code", "language": "cpp", "code": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    sort(a.begin(), a.end());\n    cout << a.front() << \"\\n\";\n}", "lineNumbers": true, "title": "Template C++17/20 mínimo"}, {"type": "callout", "variant": "warning", "text": "A complexidade assintótica é uma ferramenta de projeto, não uma garantia automática. Duas soluções `O(n log n)` podem diferir muito por constantes, alocações, cache e custo de I/O.", "title": "Não confunda ordem com desempenho"}, {"type": "subsection", "id": "prova-por-invariante", "number": "1.1", "title": "Prova curta antes do código", "tag": "PROVA", "accent": "violet", "blocks": [{"type": "paragraph", "text": "Uma prova competitiva não precisa ser formal como um artigo, mas deve responder: qual é a estrutura mantida? por que cada passo é seguro? por que o algoritmo termina? por que a resposta produzida é ótima ou exata?"}, {"type": "code", "language": "cpp", "code": "for (int i = 0; i < n; ++i) {\n    // Invariante: ans é a melhor resposta usando a[0..i-1].\n    ans = max(ans, a[i]);\n}", "lineNumbers": true, "title": "Exemplo de invariante"}]}, {"type": "subsection", "id": "pratica-e-debug", "number": "1.2", "title": "Treino deliberado", "tag": "TREINO", "accent": "amber", "blocks": [{"type": "paragraph", "text": "Resolva primeiro problemas introdutórios do [CSES Problem Set](https://cses.fi/problemset/) e use o [USACO Guide](https://usaco.guide/) para uma trilha graduada. Ao errar, classifique o erro: interpretação, prova, complexidade, implementação, overflow ou caso de borda."}, {"type": "list", "style": "check", "items": ["Leia editoriais somente depois de uma tentativa honesta.", "Reimplemente a ideia sem copiar o código.", "Mantenha um caderno de padrões e contraexemplos.", "Treine sob pressão com sessões cronometradas e depois faça pós-análise."]}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Leia `n` inteiros e informe mínimo, máximo e soma usando um tipo seguro.", "Dado `n`, compare três algoritmos para calcular a soma de `1..n` e explique a complexidade de cada um.", "Conte quantos valores de uma lista são pares, ímpares e múltiplos de 3.", "Faça um programa que leia vários casos até EOF e imprima uma resposta por linha."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}, {"type": "history", "name": "Edsger W. Dijkstra", "shortBio": "Edsger W. Dijkstra (1930–2002) foi um cientista da computação neerlandês conhecido por contribuições a algoritmos, linguagens e métodos de programação.", "insight": "A contribuição histórica relevante aqui é tratar correção, invariantes e simplicidade como parte do algoritmo, não como uma etapa posterior ao código.", "image": {"src": "images/history-dijkstra.jpg", "alt": "Retrato de Edsger W. Dijkstra"}}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "cpp-moderno-stl", "number": "2", "title": "C++ moderno e a biblioteca padrão", "blocks": [{"type": "paragraph", "text": "A biblioteca padrão é uma vantagem competitiva: containers testados, algoritmos genéricos e tipos numéricos expressivos reduzem bugs. O padrão usado nas competições varia; escreva preferencialmente em C++17 e conheça recursos de C++20 quando a plataforma aceitar.", "lead": true}, {"type": "heading", "level": 3, "text": "Containers que aparecem o tempo todo"}, {"type": "table", "header": ["Container", "Uso típico", "Custo típico"], "rows": [["`vector<T>`", "sequência contígua, acesso por índice", "acesso O(1), `push_back` amortizado O(1)"], ["`deque<T>`", "inserção nas duas pontas", "O(1) amortizado nas pontas"], ["`set` / `map`", "ordenação e busca por chave", "O(log n)"], ["`unordered_set` / `unordered_map`", "hash e acesso médio rápido", "O(1) médio; pior caso não garantido"], ["`priority_queue`", "maior/menor elemento dinâmico", "inserção/remoção O(log n)"], ["`bitset<N>`", "bits compactos e operações rápidas", "operações em palavras"]], "caption": "Escolha o container pela operação dominante"}, {"type": "code", "language": "cpp", "code": "vector<int> a = {4, 1, 7, 1};\nsort(a.begin(), a.end());\na.erase(unique(a.begin(), a.end()), a.end());\n\nmap<string, int> freq;\nfor (auto x : a) ++freq[to_string(x)];\n\npriority_queue<int, vector<int>, greater<int>> min_heap;\nmin_heap.push(3); min_heap.push(1);", "lineNumbers": true, "title": "Idiomas idiomáticos da STL"}, {"type": "heading", "level": 3, "text": "Iteradores, lambdas e ranges mentais"}, {"type": "paragraph", "text": "Algoritmos como `sort`, `lower_bound`, `accumulate`, `count_if` e `max_element` expressam a intenção. Uma lambda captura contexto explicitamente; prefira `const auto&` para não copiar objetos grandes. Em C++20, ranges tornam composições mais legíveis, mas não são necessários para resolver a maioria dos problemas."}, {"type": "code", "language": "cpp", "code": "sort(v.begin(), v.end(), [](const auto& x, const auto& y) {\n    if (x.first != y.first) return x.first < y.first;\n    return x.second > y.second;\n});\n\nauto comp = [](const auto& a, const auto& b) {\n    if (a.first != b.first) return a.first < b.first;\n    return a.second > b.second;\n};\nauto it = lower_bound(v.begin(), v.end(), x, comp);\nint pos = int(it - v.begin());", "lineNumbers": true, "title": "Comparador e busca binária"}, {"type": "callout", "variant": "danger", "text": "Atenção a invalidação de iteradores: `vector::push_back` pode realocar; depois de uma realocação, referências, ponteiros e iteradores antigos deixam de ser válidos.", "title": "Regra de segurança da STL"}, {"type": "subsection", "id": "numeros-e-overflow", "number": "2.1", "title": "Inteiros, overflow e precisão", "tag": "TIPO", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Use `long long` para somas, produtos e respostas que possam exceder 32 bits. Ainda assim, `long long` pode estourar: use `__int128` para produtos até cerca de 10^18 e converta a saída manualmente. Não use `double` para comparar inteiros grandes ou contar respostas exatas."}, {"type": "code", "language": "cpp", "code": "__int128 area = (__int128)a * b;\nif (area > (__int128)4000000000000000000LL) {\n    // trate conforme o problema\n}", "lineNumbers": true, "title": "Produto seguro"}]}, {"type": "subsection", "id": "strings-e-io", "number": "2.2", "title": "Texto e entrada/saída", "tag": "IMPLEMENTAÇÃO", "accent": "green", "blocks": [{"type": "paragraph", "text": "Para entradas grandes, sincronização desligada e `cin.tie(nullptr)` normalmente bastam. Use `getline` quando espaços fizerem parte dos dados. Para desempenho extremo, um scanner baseado em `fread` pode ajudar, mas só depois de medir."}, {"type": "code", "language": "cpp", "code": "ios::sync_with_stdio(false);\ncin.tie(nullptr);\n\nstring line;\ngetline(cin >> ws, line);", "lineNumbers": true, "title": "Entrada robusta"}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Remova duplicatas de um vetor e mantenha os valores em ordem crescente.", "Conte a frequência de palavras usando `map`.", "Use `priority_queue` para imprimir os três maiores valores.", "Ordene pares por primeira coordenada crescente e, em empate, segunda decrescente."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "ordenacao-busca-gulosos", "number": "3", "title": "Ordenação, busca e estratégias gulosas", "blocks": [{"type": "paragraph", "text": "Ordenar revela estrutura. Muitas soluções começam organizando eventos, coordenadas ou candidatos para que uma decisão local seja segura. A técnica gulosa só funciona quando há uma prova de troca, uma propriedade de matroide, ou uma decomposição que torne escolhas locais globalmente ótimas.", "lead": true}, {"type": "heading", "level": 3, "text": "Busca binária sobre resposta"}, {"type": "paragraph", "text": "Quando a pergunta “é possível atingir pelo menos X?” possui monotonicidade, transforme otimização em decisão. Mantenha um intervalo em que a resposta está e reduza-o até o primeiro valor viável."}, {"type": "code", "language": "cpp", "code": "long long lo = 0, hi = 1e18;\nwhile (lo < hi) {\n    long long mid = lo + (hi - lo) / 2;\n    if (can(mid)) hi = mid;\n    else lo = mid + 1;\n}\ncout << lo << \"\\n\";", "lineNumbers": true, "title": "Primeiro valor viável"}, {"type": "heading", "level": 3, "text": "Intervalos e eventos"}, {"type": "paragraph", "text": "Para selecionar o maior número de intervalos sem sobreposição, ordene pelo fim crescente e aceite o próximo compatível. Para problemas de cobertura, eventos ou salas, transforme começos e fins em eventos ordenados ou use uma fila de prioridades."}, {"type": "code", "language": "cpp", "code": "sort(intervals.begin(), intervals.end(), [](auto a, auto b) {\n    return a.second < b.second;\n});\nint last = numeric_limits<int>::min();\nint answer = 0;\nfor (auto [l, r] : intervals) {\n    if (l >= last) ++answer, last = r;\n}", "lineNumbers": true, "title": "Seleção de atividades"}, {"type": "callout", "variant": "warning", "text": "Contraexemplo é parte da prova: se você não consegue justificar a escolha local, tente construir uma instância pequena em que outra escolha pareça melhor. Se ela existir, a estratégia gulosa precisa ser abandonada ou refinada.", "title": "Guloso sem prova é palpite"}, {"type": "subsection", "id": "compressao-coordenadas", "number": "3.1", "title": "Compressão de coordenadas", "tag": "TÉCNICA", "accent": "cyan", "blocks": [{"type": "paragraph", "text": "Quando os valores são grandes, mas só importam ordem e igualdade, ordene os valores distintos e substitua cada valor por sua posição. Isso converte coordenadas de até 10^18 em índices de `0..m-1`, abrindo espaço para Fenwick, segment tree e arrays."}, {"type": "code", "language": "cpp", "code": "vector<long long> xs = a;\nsort(xs.begin(), xs.end());\nxs.erase(unique(xs.begin(), xs.end()), xs.end());\nfor (auto& x : a) x = lower_bound(xs.begin(), xs.end(), x) - xs.begin();", "lineNumbers": true}]}, {"type": "subsection", "id": "sort-estavel", "number": "3.2", "title": "Ordenação estável e comparadores", "tag": "CORREÇÃO", "accent": "red", "blocks": [{"type": "paragraph", "text": "Um comparador deve ser uma ordem fraca estrita: não pode dizer que `a < b` e `b < a` ao mesmo tempo, nem depender de estado mutável. Se você ordenar por várias chaves, compare a primeira diferente; `stable_sort` preserva a ordem anterior quando as chaves empatam."}, {"type": "list", "style": "bullet", "items": ["Não subtraia inteiros no comparador: `return a.x - b.x < 0` pode estourar.", "Use `tie(a.x, a.y) < tie(b.x, b.y)` ou comparações explícitas.", "Depois de ordenar, use `equal_range` para obter o intervalo de iguais."]}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Verifique se duas listas possuem algum elemento em comum.", "Encontre a primeira posição de um valor em um vetor ordenado.", "Selecione o maior número de intervalos não sobrepostos.", "Dado um limite de páginas, divida livros contíguos entre estudantes minimizando a maior soma."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "prefixos-janelas", "number": "4", "title": "Prefixos, janelas e técnicas de sequência", "blocks": [{"type": "paragraph", "text": "Muitas perguntas sobre subarrays deixam de ser quadráticas quando acumulamos informação. A soma prefixada transforma intervalo em diferença; duas pontas exploram monotonicidade; diferenças e eventos transformam muitas atualizações em poucas operações.", "lead": true}, {"type": "heading", "level": 3, "text": "Somas prefixadas"}, {"type": "code", "language": "cpp", "code": "vector<long long> pref(n + 1);\nfor (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + a[i];\n// soma do intervalo [l, r)\nlong long sum = pref[r] - pref[l];", "lineNumbers": true, "title": "Intervalos em O(1)"}, {"type": "paragraph", "text": "Para contar subarrays com soma K, mantenha frequências de prefixos anteriores: `pref[j] - pref[i] = K` equivale a procurar `pref[j] - K`. A técnica funciona com números negativos, onde a janela deslizante usual falha."}, {"type": "code", "language": "cpp", "code": "unordered_map<long long, long long> cnt;\ncnt[0] = 1;\nlong long pref = 0, ans = 0;\nfor (long long x : a) {\n    pref += x;\n    ans += cnt[pref - K];\n    ++cnt[pref];\n}", "lineNumbers": true, "title": "Subarrays com soma K"}, {"type": "heading", "level": 3, "text": "Janela deslizante"}, {"type": "paragraph", "text": "Use duas pontas quando, ao expandir a direita, o mínimo ou máximo de uma condição muda de forma monotônica e remover a esquerda nunca reverte o problema de maneira inesperada. O padrão clássico mantém a menor janela que satisfaz uma condição."}, {"type": "code", "language": "cpp", "code": "int l = 0;\nfor (int r = 0; r < n; ++r) {\n    add(a[r]);\n    while (invalid()) remove(a[l++]);\n    answer = max(answer, r - l + 1);\n}", "lineNumbers": true, "title": "Janela com invariante"}, {"type": "subsection", "id": "array-diferenca", "number": "4.1", "title": "Atualizações em intervalo", "tag": "INTERVALOS", "accent": "teal", "blocks": [{"type": "paragraph", "text": "Para adicionar X a todo `[l,r]`, faça `diff[l] += X` e `diff[r+1] -= X`. Uma passagem de prefixo recupera o valor final. Em duas dimensões, quatro cantos codificam cada retângulo."}, {"type": "code", "language": "cpp", "code": "vector<long long> diff(n + 1);\ndiff[l] += x;\nif (r + 1 < n) diff[r + 1] -= x;\nfor (int i = 1; i < n; ++i) diff[i] += diff[i - 1];", "lineNumbers": true}]}, {"type": "subsection", "id": "two-pointers", "number": "4.2", "title": "Dois ponteiros e ordenação", "tag": "PADRÃO", "accent": "violet", "blocks": [{"type": "paragraph", "text": "Para encontrar pares com soma alvo em uma lista ordenada, mova a esquerda quando a soma é pequena e a direita quando é grande. O argumento de correção é que cada movimento elimina definitivamente uma faixa de candidatos."}, {"type": "code", "language": "cpp", "code": "sort(a.begin(), a.end());\nint l = 0, r = n - 1;\nwhile (l < r) {\n    long long s = a[l] + a[r];\n    if (s == target) { /* par encontrado */ ++l; --r; }\n    else if (s < target) ++l;\n    else --r;\n}", "lineNumbers": true}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Responda somas de intervalos com prefixos.", "Encontre o maior subarray com soma positiva em uma lista de valores 0/1.", "Conte pares com soma igual a `K` em uma lista pequena.", "Encontre a menor janela contendo todos os caracteres de uma palavra-alvo."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "dp", "number": "5", "title": "Programação dinâmica: estados, transições e otimização", "blocks": [{"type": "paragraph", "text": "Programação dinâmica (DP) é enumeração inteligente de estados sobre subproblemas sobrepostos. A receita é: definir o estado com precisão, listar transições, escolher uma ordem acíclica de cálculo, identificar casos-base e provar que toda solução ótima passa por uma transição considerada.", "lead": true}, {"type": "heading", "level": 3, "text": "DP 1D e mochila"}, {"type": "paragraph", "text": "Na mochila 0/1, `dp[w]` representa o melhor valor usando itens já processados com capacidade até `w`. Percorra a capacidade de trás para frente para não reutilizar o mesmo item na mesma etapa."}, {"type": "code", "language": "cpp", "code": "vector<long long> dp(W + 1, 0);\nfor (int i = 0; i < n; ++i) {\n    for (int w = W; w >= weight[i]; --w) {\n        dp[w] = max(dp[w], dp[w - weight[i]] + value[i]);\n    }\n}", "lineNumbers": true, "title": "Mochila 0/1 em O(nW)"}, {"type": "heading", "level": 3, "text": "DP em grade e subsequência"}, {"type": "code", "language": "cpp", "code": "vector<vector<int>> dp(n + 1, vector<int>(m + 1));\nfor (int i = 1; i <= n; ++i) {\n    for (int j = 1; j <= m; ++j) {\n        if (a[i - 1] == b[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;\n        else dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);\n    }\n}", "lineNumbers": true, "title": "LCS — maior subsequência comum"}, {"type": "callout", "variant": "definition", "text": "DP não é “guardar tudo em uma tabela”. O estado deve conter exatamente a informação do passado que influencia o futuro. Se duas histórias têm o mesmo estado, o restante da decisão é idêntico e pode ser compartilhado.", "title": "Princípio de suficiência do estado"}, {"type": "subsection", "id": "dp-em-grafos", "number": "5.1", "title": "DP em DAG e memoização", "tag": "ESTADOS", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Se as transições formam um grafo acíclico, uma ordem topológica calcula cada estado uma vez. Com ciclos, use memoização apenas se o estado recursivo realmente for acíclico; em jogos e problemas de caminho, explicite a dimensão de tempo ou o número de movimentos."}, {"type": "code", "language": "cpp", "code": "long long solve(int v) {\n    if (memo[v] != -1) return memo[v];\n    long long best = 0;\n    for (int to : g[v]) best = max(best, 1 + solve(to));\n    return memo[v] = best;\n}", "lineNumbers": true}]}, {"type": "subsection", "id": "otimizacoes-dp", "number": "5.2", "title": "Otimizações: rolagem, monotonicidade e convexidade", "tag": "OTIMIZAÇÃO", "accent": "violet", "blocks": [{"type": "paragraph", "text": "Reduza memória quando a transição usa apenas a linha anterior. Para limites maiores, procure propriedades: monotone queue, divide and conquer optimization, Knuth, Li Chao ou Convex Hull Trick. Essas otimizações exigem provas adicionais sobre a forma das funções ou dos argmin."}, {"type": "list", "style": "check", "items": ["Primeiro prove a DP ingênua.", "Meça a dimensão que domina tempo e memória.", "Só aplique uma otimização cuja hipótese esteja demonstrada."]}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Calcule Fibonacci com memoização e depois com duas variáveis.", "Resolva escada com passos 1 ou 2.", "Calcule o valor máximo de uma mochila com `n≤30` e capacidade pequena.", "Encontre o tamanho da maior subsequência crescente estrita."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}, {"type": "divider"}, {"type": "subsection", "id": "problema-elevator-rides", "number": "5.3", "title": "Problema difícil guiado: Elevator Rides com bitmask DP", "tag": "WALKTHROUGH", "accent": "violet", "blocks": [{"type": "paragraph", "text": "**Problema.** Há `n` pessoas com pesos conhecidos e um elevador com capacidade `X`. Todos devem subir, em qualquer ordem. Minimize o número de viagens; entre soluções com o mesmo número de viagens, minimize o peso usado na última viagem."}, {"type": "heading", "level": 3, "text": "1. Por que o estado guarda dois valores"}, {"type": "paragraph", "text": "Para cada subconjunto `mask`, guardamos um par `(rides, lastWeight)`. Ele significa: melhor forma de transportar exatamente as pessoas de `mask`, usando o menor número de viagens; em empate, a menor carga na última viagem. Comparar apenas o peso seria errado, pois uma carga menor com mais viagens não é melhor."}, {"type": "heading", "level": 3, "text": "2. Transição modular"}, {"type": "code", "language": "cpp", "code": "using RideState = pair<int, long long>; // viagens, peso da última viagem\n\nRideState addPerson(RideState currentState, long long personWeight, long long capacity) {\n    auto [rideCount, lastRideWeight] = currentState;\n    if (lastRideWeight + personWeight <= capacity) return {rideCount, lastRideWeight + personWeight};\n    return {rideCount + 1, personWeight};\n}\n\nRideState solveElevator(const vector<long long>& personWeights, long long capacity) {\n    int personCount = static_cast<int>(personWeights.size());\n    if (personCount >= 63) throw invalid_argument(\"personCount deve ser menor que 63\");\n    for (long long weight : personWeights) if (weight > capacity) throw invalid_argument(\"pessoa acima da capacidade\");\n    size_t subsetCount = size_t(1ULL) << personCount;\n    const RideState impossible = {personCount + 1, capacity + 1};\n    vector<RideState> bestState(subsetCount, impossible);\n    bestState[0] = {1, 0};\n    for (size_t mask = 0; mask < subsetCount; ++mask) {\n        for (int personIndex = 0; personIndex < personCount; ++personIndex) {\n            if (mask & (size_t(1) << personIndex)) continue;\n            size_t nextMask = mask | (size_t(1) << personIndex);\n            RideState candidate = addPerson(bestState[mask], personWeights[personIndex], capacity);\n            bestState[nextMask] = min(bestState[nextMask], candidate);\n        }\n    }\n    return bestState.back();\n}", "lineNumbers": true, "title": "Transição separada da enumeração de máscaras"}, {"type": "heading", "level": 3, "text": "3. Prova por indução"}, {"type": "paragraph", "text": "A base `mask=0` representa uma viagem vazia. Suponha que `bestState[mask]` contém a melhor dupla para `mask`. Qualquer solução para `nextMask` termina adicionando alguma pessoa `p` a uma solução de `mask=nextMask\\p`; a função `addPerson` calcula exatamente o efeito de colocá-la na última viagem ou abrir uma nova. Como testamos todas as pessoas finais, a melhor candidata é escolhida."}, {"type": "heading", "level": 3, "text": "4. Complexidade"}, {"type": "paragraph", "text": "Há `2^n` máscaras e até `n` transições por máscara: `O(n·2^n)` tempo e `O(2^n)` memória. A técnica é adequada quando `n` é aproximadamente até 20, e não quando `n` cresce para centenas."}, {"type": "heading", "level": 3, "text": "5. Exemplo de entrada e saída"}, {"type": "code", "language": "text", "code": "4 10\n4 8 6 2", "lineNumbers": true, "title": "Entrada"}, {"type": "code", "language": "text", "code": "3", "lineNumbers": true, "title": "Saída"}]}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "grafos-basicos", "number": "6", "title": "Grafos I: representação, busca e componentes", "blocks": [{"type": "paragraph", "text": "Um grafo modela entidades e relações: cidades e estradas, estados e transições, páginas e links. Escolha lista de adjacência para grafos esparsos e matriz apenas quando `n` for pequeno ou as consultas exigirem acesso constante entre todos os pares.", "lead": true}, {"type": "heading", "level": 3, "text": "BFS e DFS"}, {"type": "code", "language": "cpp", "code": "vector<vector<int>> g(n);\nvector<int> dist(n, -1);\nqueue<int> q;\ndist[source] = 0; q.push(source);\nwhile (!q.empty()) {\n    int v = q.front(); q.pop();\n    for (int to : g[v]) if (dist[to] == -1) {\n        dist[to] = dist[v] + 1;\n        q.push(to);\n    }\n}", "lineNumbers": true, "title": "BFS — menores distâncias sem pesos"}, {"type": "paragraph", "text": "DFS é natural para componentes, detecção de ciclos, pontes, articulações e ordenação topológica. Em grafos muito profundos, a pilha recursiva pode estourar; use uma versão iterativa ou aumente a cautela conforme a plataforma."}, {"type": "heading", "level": 3, "text": "DSU / Union-Find"}, {"type": "code", "language": "cpp", "code": "struct DSU {\n    vector<int> p, sz;\n    DSU(int n): p(n), sz(n, 1) { iota(p.begin(), p.end(), 0); }\n    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }\n    bool unite(int a, int b) {\n        a = find(a); b = find(b);\n        if (a == b) return false;\n        if (sz[a] < sz[b]) swap(a, b);\n        p[b] = a; sz[a] += sz[b]; return true;\n    }\n};", "lineNumbers": true, "title": "União por tamanho + compressão"}, {"type": "callout", "variant": "warning", "text": "Em um grafo não direcionado, uma BFS/DFS visita exatamente a componente conexa alcançável. Em um grafo direcionado, “alcançável de u” e “alcança u” são perguntas diferentes; não transfira intuições sem verificar a direção das arestas.", "title": "Direção importa"}, {"type": "subsection", "id": "toposort", "number": "6.1", "title": "Ordenação topológica", "tag": "DEPENDÊNCIAS", "accent": "teal", "blocks": [{"type": "paragraph", "text": "Uma ordenação topológica existe exatamente quando o grafo direcionado é acíclico. O algoritmo de Kahn mantém o grau de entrada e libera vértices que se tornam independentes."}, {"type": "code", "language": "cpp", "code": "queue<int> q;\nfor (int v = 0; v < n; ++v) if (indeg[v] == 0) q.push(v);\nvector<int> order;\nwhile (!q.empty()) {\n    int v = q.front(); q.pop(); order.push_back(v);\n    for (int to : g[v]) if (--indeg[to] == 0) q.push(to);\n}\nif ((int)order.size() < n) cout << \"ciclo\\n\";", "lineNumbers": true}]}, {"type": "subsection", "id": "bipartido", "number": "6.2", "title": "Bipartição e coloração", "tag": "COLORAÇÃO", "accent": "amber", "blocks": [{"type": "paragraph", "text": "Um grafo é bipartido quando seus vértices podem ser coloridos com duas cores sem aresta monocromática. BFS/DFS detecta conflito; a mesma técnica resolve componentes e fornece uma partição para problemas de “duas equipes”."}, {"type": "code", "language": "cpp", "code": "vector<int> color(n, -1);\nfor (int s = 0; s < n; ++s) if (color[s] == -1) {\n    queue<int> q; q.push(s); color[s] = 0;\n    while (!q.empty()) {\n        int v = q.front(); q.pop();\n        for (int to : g[v]) {\n            if (color[to] == -1) color[to] = color[v] ^ 1, q.push(to);\n            else if (color[to] == color[v]) ok = false;\n        }\n    }\n}", "lineNumbers": true}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Conte componentes conexas em um grafo não direcionado.", "Verifique se um grafo é bipartido.", "Calcule a distância mínima em um labirinto sem pesos.", "Detecte se um grafo direcionado possui ciclo usando três cores."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}, {"type": "divider"}, {"type": "subsection", "id": "problema-labirinto-explicado", "number": "6.3", "title": "Problema difícil guiado: labirinto com caminho mínimo e reconstrução", "tag": "WALKTHROUGH", "accent": "red", "blocks": [{"type": "paragraph", "text": "**Problema.** Dada uma grade com `#` (parede), `.` (célula livre), `A` (início) e `B` (destino), encontre o menor caminho e imprima a sequência de movimentos. Se não existir, imprima `IMPOSSIBLE`. O ponto difícil não é apenas descobrir a distância: é recuperar o caminho sem guardar uma string inteira em cada estado.", "lead": true}, {"type": "heading", "level": 3, "text": "1. Intuição e modelagem"}, {"type": "paragraph", "text": "Cada célula livre é um vértice e cada movimento ortogonal é uma aresta de custo 1. Logo, BFS visita as células em camadas de distância crescente. A primeira vez que chegamos em `B` já temos uma distância mínima. Para reconstruir, guardamos em cada célula o predecessor e o movimento que levou até ela."}, {"type": "heading", "level": 3, "text": "2. Invariante"}, {"type": "paragraph", "text": "Quando uma célula entra na fila, `distância[célula]` é a menor distância possível desde `A`. Isso vale porque BFS só expande uma camada depois de terminar a anterior e todas as arestas têm o mesmo peso."}, {"type": "heading", "level": 3, "text": "3. Código modular"}, {"type": "code", "language": "cpp", "code": "struct Cell { int row, column; };\n\nstring reconstructPath(Cell startCell, Cell targetCell,\n                       const vector<vector<Cell>>& predecessor,\n                       const vector<vector<char>>& moveUsed) {\n    string reversedPath;\n    Cell currentCell = targetCell;\n    while (!(currentCell.row == startCell.row && currentCell.column == startCell.column)) {\n        reversedPath.push_back(moveUsed[currentCell.row][currentCell.column]);\n        currentCell = predecessor[currentCell.row][currentCell.column];\n    }\n    reverse(reversedPath.begin(), reversedPath.end());\n    return reversedPath;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int rowCount, columnCount;\n    cin >> rowCount >> columnCount;\n    vector<string> grid(rowCount);\n    for (string& row : grid) cin >> row;\n\n    Cell startCell{-1, -1}, targetCell{-1, -1};\n    for (int row = 0; row < rowCount; ++row) {\n        for (int column = 0; column < columnCount; ++column) {\n            if (grid[row][column] == 'A') startCell = {row, column};\n            if (grid[row][column] == 'B') targetCell = {row, column};\n        }\n    }\n\n    vector<vector<int>> distance(rowCount, vector<int>(columnCount, -1));\n    vector<vector<Cell>> predecessor(rowCount, vector<Cell>(columnCount, {-1, -1}));\n    vector<vector<char>> moveUsed(rowCount, vector<char>(columnCount, 0));\n    const int rowDelta[4] = {-1, 1, 0, 0};\n    const int columnDelta[4] = {0, 0, -1, 1};\n    const char moveName[4] = {'U', 'D', 'L', 'R'};\n    queue<Cell> pendingCells;\n    distance[startCell.row][startCell.column] = 0;\n    pendingCells.push(startCell);\n\n    while (!pendingCells.empty()) {\n        Cell currentCell = pendingCells.front();\n        pendingCells.pop();\n        for (int direction = 0; direction < 4; ++direction) {\n            int nextRow = currentCell.row + rowDelta[direction];\n            int nextColumn = currentCell.column + columnDelta[direction];\n            bool insideGrid = 0 <= nextRow && nextRow < rowCount && 0 <= nextColumn && nextColumn < columnCount;\n            if (!insideGrid || grid[nextRow][nextColumn] == '#' || distance[nextRow][nextColumn] != -1) continue;\n            distance[nextRow][nextColumn] = distance[currentCell.row][currentCell.column] + 1;\n            predecessor[nextRow][nextColumn] = currentCell;\n            moveUsed[nextRow][nextColumn] = moveName[direction];\n            pendingCells.push({nextRow, nextColumn});\n        }\n    }\n\n    if (distance[targetCell.row][targetCell.column] == -1) { cout << \"IMPOSSIBLE\\n\"; return 0; }\n    string path = reconstructPath(startCell, targetCell, predecessor, moveUsed);\n    cout << \"YES\\n\" << path.size() << \"\\n\" << path << \"\\n\";\n}", "lineNumbers": true, "title": "Solução completa, com funções nomeadas e comentários implícitos por etapas"}, {"type": "heading", "level": 3, "text": "4. Complexidade"}, {"type": "paragraph", "text": "Cada célula entra na fila no máximo uma vez e examina quatro direções. Portanto o tempo é `O(R·C)` e a memória também é `O(R·C)`. Guardar predecessores é o preço da reconstrução; se só a distância fosse necessária, bastaria `distance`."}, {"type": "heading", "level": 3, "text": "5. Como generalizar"}, {"type": "list", "style": "bullet", "items": ["Pesos 0/1: troque a fila por deque e use 0–1 BFS.", "Pesos positivos variados: use Dijkstra e predecessor.", "Várias fontes: inicialize a fila com todas elas e distância 0.", "Caminho lexicograficamente mínimo: controle a ordem de expansão ou reconstrua com uma regra adicional."]}, {"type": "heading", "level": 3, "text": "6. Exemplo de entrada e saída"}, {"type": "code", "language": "text", "code": "5 8\n########\n#A...B.#\n#.##.#.#\n#......#\n########", "lineNumbers": true, "title": "Entrada"}, {"type": "code", "language": "text", "code": "YES\n4\nRRRR", "lineNumbers": true, "title": "Saída possível"}]}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "grafos-avancados", "number": "7", "title": "Grafos II: caminhos, árvores e fluxo", "blocks": [{"type": "paragraph", "text": "Depois de BFS e DFS, a escolha do algoritmo depende das propriedades dos pesos: não negativos, negativos, todos iguais, ou estrutura acíclica. A maior fonte de erro é aplicar um algoritmo correto em um cenário diferente de suas hipóteses.", "lead": true}, {"type": "heading", "level": 3, "text": "Caminhos mínimos"}, {"type": "table", "header": ["Algoritmo", "Hipótese", "Complexidade"], "rows": [["BFS", "pesos unitários", "O(V+E)"], ["0–1 BFS", "pesos 0 ou 1", "O(V+E)"], ["Dijkstra", "pesos não negativos", "O((V+E) log V)"], ["Bellman–Ford", "aceita negativos; detecta ciclo negativo", "O(VE)"], ["Floyd–Warshall", "todos os pares, `V` pequeno", "O(V³)"]], "caption": "Escolha orientada pelas hipóteses"}, {"type": "code", "language": "cpp", "code": "using P = pair<long long,int>;\nconst long long INF = (1LL << 62);\nvector<long long> d(n, INF);\npriority_queue<P, vector<P>, greater<P>> pq;\nd[source] = 0; pq.push({0, source});\nwhile (!pq.empty()) {\n    auto [du, v] = pq.top(); pq.pop();\n    if (du != d[v]) continue;\n    for (auto [to, w] : g[v]) if (d[to] > du + w) {\n        d[to] = du + w; pq.push({d[to], to});\n    }\n}", "lineNumbers": true, "title": "Dijkstra com descarte de entradas antigas"}, {"type": "heading", "level": 3, "text": "Árvores e LCA"}, {"type": "paragraph", "text": "Uma árvore tem caminho simples único entre dois vértices. Pré-calcule ancestrais em potências de dois (binary lifting) para responder LCA e subir k níveis em `O(log n)` depois de uma DFS."}, {"type": "code", "language": "cpp", "code": "const int LOG = 20;\nvector<array<int, LOG>> up(n);\nvector<int> depth(n);\n// up[v][j] = 2^j-ésimo ancestral de v\nfor (int j = 1; j < LOG; ++j)\n    up[v][j] = up[up[v][j - 1]][j - 1];", "lineNumbers": true, "title": "Binary lifting"}, {"type": "heading", "level": 3, "text": "MST e fluxo"}, {"type": "paragraph", "text": "Kruskal combina arestas em ordem crescente com DSU e produz uma árvore geradora mínima. Prim expande uma fronteira com prioridade. Em fluxo máximo, residual e caminho aumentante são o modelo mental; Dinic é uma escolha geral para limites médios."}, {"type": "subsection", "id": "scc-e-pontes", "number": "7.1", "title": "SCC, pontes e articulações", "tag": "LOW-LINK", "accent": "orange", "blocks": [{"type": "paragraph", "text": "Kosaraju usa duas passagens de DFS para componentes fortemente conexas; Tarjan faz isso em uma passagem com low-link. Em grafos não direcionados, `low[to] > tin[v]` identifica uma ponte, enquanto a condição de articulação depende de raiz e filhos."}, {"type": "mermaid", "code": "flowchart LR\n  A[\"DFS: tin\"] --> B[\"low\"] --> C[\"ponte / articulação\"]", "caption": "Relação entre tempos de descoberta e low-link", "accent": "orange"}]}, {"type": "subsection", "id": "maxflow", "number": "7.2", "title": "Fluxo máximo e corte mínimo", "tag": "FLUXO", "accent": "red", "blocks": [{"type": "paragraph", "text": "O teorema max-flow min-cut diz que o valor do maior fluxo é igual à capacidade do menor corte que separa fonte e sumidouro. Modele capacidade, conservação e, quando necessário, divisões de vértices para impor capacidade em nós."}, {"type": "callout", "variant": "key", "text": "Sempre use `long long` para capacidades se a soma das arestas puder exceder 32 bits. Depois do fluxo, vértices alcançáveis na rede residual a partir da fonte identificam um corte mínimo.", "title": "Diagnóstico do corte"}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Calcule menores distâncias em grafo com pesos 0/1.", "Construa uma MST com Kruskal.", "Responda o ancestral comum mais baixo em uma árvore pequena por subida ingênua.", "Detecte se existem ciclos negativos alcançáveis usando Bellman–Ford."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}, {"type": "divider"}, {"type": "subsection", "id": "problema-voo-desconto", "number": "7.3", "title": "Problema difícil guiado: menor rota com um desconto", "tag": "WALKTHROUGH", "accent": "orange", "blocks": [{"type": "paragraph", "text": "**Problema.** Em um grafo direcionado com preços não negativos, encontre o menor custo de `1` até `n` podendo aplicar 50% de desconto em exatamente uma aresta. O insight é transformar “usei o desconto?” em uma dimensão do estado."}, {"type": "heading", "level": 3, "text": "1. Estado e transições"}, {"type": "paragraph", "text": "Use dois estados por vértice: `discountUsed = 0` ou `1`. Ao atravessar uma aresta `(u,v,w)`, sempre podemos pagar `w` mantendo o estado; se ainda não usamos o desconto, também podemos ir para `(v,1)` pagando `w/2`. Como todos os custos continuam não negativos, Dijkstra permanece válido."}, {"type": "code", "language": "cpp", "code": "struct State { long long cost; int vertex; int discountUsed; };\nstruct StateOrder {\n    bool operator()(const State& left, const State& right) const { return left.cost > right.cost; }\n};\n\nvector<vector<long long>> shortestCost(\n    int vertexCount, const vector<vector<pair<int, long long>>>& graph, int sourceVertex) {\n    const long long infinity = (1LL << 62);\n    vector<vector<long long>> minimumCost(vertexCount, vector<long long>(2, infinity));\n    priority_queue<State, vector<State>, StateOrder> pendingStates;\n    minimumCost[sourceVertex][0] = 0;\n    pendingStates.push({0, sourceVertex, 0});\n\n    while (!pendingStates.empty()) {\n        State currentState = pendingStates.top();\n        pendingStates.pop();\n        if (currentState.cost != minimumCost[currentState.vertex][currentState.discountUsed]) continue;\n        for (auto [nextVertex, edgeCost] : graph[currentState.vertex]) {\n            int sameState = currentState.discountUsed;\n            if (currentState.cost + edgeCost < minimumCost[nextVertex][sameState]) {\n                minimumCost[nextVertex][sameState] = currentState.cost + edgeCost;\n                pendingStates.push({minimumCost[nextVertex][sameState], nextVertex, sameState});\n            }\n            if (!currentState.discountUsed) {\n                long long discountedCost = currentState.cost + edgeCost / 2;\n                if (discountedCost < minimumCost[nextVertex][1]) {\n                    minimumCost[nextVertex][1] = discountedCost;\n                    pendingStates.push({discountedCost, nextVertex, 1});\n                }\n            }\n        }\n    }\n    return minimumCost;\n}", "lineNumbers": true, "title": "Dijkstra em grafo de estados"}, {"type": "heading", "level": 3, "text": "2. Fórmula e correção"}, {"type": "math", "tex": "dp[v][s] = menor custo para chegar a v usando s descontos,\\quad s\\in\\{0,1\\}"}, {"type": "paragraph", "text": "Toda rota válida pode ser decomposta no último salto. Se o desconto não foi usado, o salto custa `w` e mantém `s=0`; se foi aplicado nele, custa `floor(w/2)` e muda para `s=1`. Dijkstra relaxa essas duas possibilidades e, por indução no menor rótulo extraído, fixa cada estado com seu menor custo."}, {"type": "heading", "level": 3, "text": "3. Complexidade e variações"}, {"type": "paragraph", "text": "O grafo duplicou o número de estados, mas ainda tem `2V` vértices e `2E` transições efetivas: `O((V+E) log V)`. Com `k` cupons, substitua a dimensão binária por `0..k`; com cupons de tipos diferentes, o estado passa a representar a máscara ou o inventário permitido."}, {"type": "heading", "level": 3, "text": "4. Exemplo de entrada e saída"}, {"type": "code", "language": "text", "code": "3 3\n1 2 10\n2 3 10\n1 3 25", "lineNumbers": true, "title": "Entrada"}, {"type": "code", "language": "text", "code": "15", "lineNumbers": true, "title": "Saída"}]}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "estruturas-arvore", "number": "8", "title": "Estruturas de dados para consultas dinâmicas", "blocks": [{"type": "paragraph", "text": "Quando os dados mudam entre consultas, prefixos estáticos não bastam. Fenwick, segment tree, sparse table e treaps oferecem diferentes compromissos entre operações suportadas, memória e complexidade de implementação.", "lead": true}, {"type": "heading", "level": 3, "text": "Fenwick / BIT"}, {"type": "code", "language": "cpp", "code": "struct Fenwick {\n    int n; vector<long long> bit;\n    Fenwick(int n): n(n), bit(n + 1) {}\n    void add(int i, long long v) {\n        for (++i; i <= n; i += i & -i) bit[i] += v;\n    }\n    long long sumPrefix(int i) const {\n        long long r = 0;\n        for (; i > 0; i -= i & -i) r += bit[i];\n        return r;\n    }\n    long long sum(int l, int r) const { return sumPrefix(r) - sumPrefix(l); }\n};", "lineNumbers": true, "title": "Fenwick: atualização pontual e soma de prefixo"}, {"type": "heading", "level": 3, "text": "Segment tree"}, {"type": "paragraph", "text": "Uma segment tree representa intervalos por decomposição binária. Ela suporta consulta de monóide — soma, mínimo, máximo, gcd, ou composição — em `O(log n)`. Com lazy propagation, atualizações em intervalo também cabem em `O(log n)` quando a operação tem ação composável."}, {"type": "code", "language": "cpp", "code": "void update(int p, int l, int r, int pos, long long val) {\n    if (r - l == 1) { tree[p] = val; return; }\n    int m = (l + r) / 2;\n    if (pos < m) update(2*p, l, m, pos, val);\n    else update(2*p+1, m, r, pos, val);\n    tree[p] = tree[2*p] + tree[2*p+1];\n}", "lineNumbers": true, "title": "Atualização recursiva de ponto"}, {"type": "table", "header": ["Estrutura", "Consulta", "Atualização"], "rows": [["Prefix sum", "O(1)", "O(n) ou O(1) amortizado com diferença"], ["Fenwick", "O(log n)", "O(log n)"], ["Segment tree", "O(log n)", "O(log n)"], ["Sparse table", "O(1) para idempotentes", "pré-processamento O(n log n), sem atualização"]], "caption": "Mapa de decisão"}, {"type": "callout", "variant": "definition", "text": "Defina o operador e o elemento neutro antes de escrever a árvore. Se a combinação não é associativa, a decomposição em qualquer ordem pode mudar o resultado.", "title": "Monóide"}, {"type": "subsection", "id": "lazy-e-lichao", "number": "8.1", "title": "Lazy propagation e Li Chao", "tag": "AVANÇADO", "accent": "violet", "blocks": [{"type": "paragraph", "text": "Lazy propagation guarda uma atualização que ainda não foi empurrada aos filhos. Li Chao mantém a melhor reta em cada intervalo do domínio e responde mínimos/máximos em `O(log C)`; é útil em DP com transições lineares."}, {"type": "code", "language": "cpp", "code": "long long f(Line line, long long x) { return line.m * x + line.b; }\n// Em cada nó, mantenha a reta atualmente melhor em algum ponto.\n// Compare no meio e recursione onde a reta antiga pode vencer.", "lineNumbers": true, "title": "Esqueleto conceitual de Li Chao"}]}, {"type": "subsection", "id": "randomized", "number": "8.2", "title": "Hashing e estruturas aleatorizadas", "tag": "ROBUSTEZ", "accent": "gray", "blocks": [{"type": "paragraph", "text": "Treap combina BST por chave com prioridade aleatória; a altura esperada é logarítmica. Hashing de strings pode acelerar comparação de substrings, mas colisões são possíveis: use dois módulos, 64 bits com cuidado, ou estruturas determinísticas quando a correção exigir."}, {"type": "paragraph", "text": "Lembre-se de semear aleatoriedade de forma reprodutível durante o debug e evite depender de comportamento indefinido."}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Implemente Fenwick para soma de prefixo.", "Responda mínimo em intervalos sem atualizações com sparse table.", "Implemente segment tree para soma e atualização pontual.", "Conte inversões usando compressão e Fenwick."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}, {"type": "divider"}, {"type": "subsection", "id": "problema-inversions", "number": "8.3", "title": "Problema difícil guiado: contar inversões com Fenwick", "tag": "WALKTHROUGH", "accent": "cyan", "blocks": [{"type": "paragraph", "text": "**Problema.** Conte pares `(i,j)` com `i<j` e `a[i]>a[j]`. O desafio é transformar uma condição sobre posições e valores em consultas prefixadas."}, {"type": "heading", "level": 3, "text": "1. Varredura da direita para a esquerda"}, {"type": "paragraph", "text": "Ao visitar `a[i]`, os elementos já inseridos são exatamente os que ficam à direita. Queremos saber quantos deles são menores que `a[i]`. Após compressão de coordenadas, isso vira uma soma de frequências no prefixo `rank(a[i])-1`."}, {"type": "code", "language": "cpp", "code": "long long countInversions(vector<long long> values) {\n    vector<long long> compressedValues = values;\n    sort(compressedValues.begin(), compressedValues.end());\n    compressedValues.erase(unique(compressedValues.begin(), compressedValues.end()), compressedValues.end());\n    Fenwick frequencyTree(compressedValues.size());\n    long long inversionCount = 0;\n    for (int index = (int)values.size() - 1; index >= 0; --index) {\n        int valueRank = lower_bound(compressedValues.begin(), compressedValues.end(), values[index]) - compressedValues.begin();\n        inversionCount += frequencyTree.sum(0, valueRank);\n        frequencyTree.add(valueRank, 1);\n    }\n    return inversionCount;\n}", "lineNumbers": true, "title": "Varredura + compressão + Fenwick"}, {"type": "heading", "level": 3, "text": "2. Prova da consulta"}, {"type": "paragraph", "text": "Antes de inserir `a[i]`, a árvore contém uma ocorrência para cada posição `j>i`. A soma nos ranks menores que `a[i]` conta exatamente os `j` que formam inversão com `i`. Cada par é contado uma vez, quando o índice esquerdo é processado."}, {"type": "heading", "level": 3, "text": "3. Exemplo de entrada e saída"}, {"type": "code", "language": "text", "code": "5\n2 4 1 3 5", "lineNumbers": true, "title": "Entrada"}, {"type": "code", "language": "text", "code": "3", "lineNumbers": true, "title": "Saída: (2,1), (4,1), (4,3)"}]}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "strings", "number": "9", "title": "Strings: prefixos, padrões e palíndromos", "blocks": [{"type": "paragraph", "text": "Strings escondem grafos e automatos. A escolha entre hash, Z, KMP, trie e Aho–Corasick depende de quantos padrões existem, se há atualizações e se você precisa de garantias determinísticas.", "lead": true}, {"type": "heading", "level": 3, "text": "Prefix function / KMP"}, {"type": "paragraph", "text": "A função prefixo `pi[i]` é o tamanho do maior prefixo próprio de `s[0..i]` que também é sufixo. Ela permite buscar um padrão em texto em tempo linear, reaproveitando bordas após uma falha."}, {"type": "code", "language": "cpp", "code": "vector<int> prefix_function(const string& s) {\n    vector<int> pi(s.size());\n    for (int i = 1; i < (int)s.size(); ++i) {\n        int j = pi[i - 1];\n        while (j && s[i] != s[j]) j = pi[j - 1];\n        if (s[i] == s[j]) ++j;\n        pi[i] = j;\n    }\n    return pi;\n}", "lineNumbers": true, "title": "Prefix function em O(n)"}, {"type": "heading", "level": 3, "text": "Z-function e suffix array"}, {"type": "paragraph", "text": "A Z-function mede o maior prefixo que começa em cada posição e resolve ocorrências e periodicidade com uma janela `[l,r]`. Para ordenação lexicográfica de todos os sufixos, suffix array e LCP transformam problemas de substrings em problemas sobre um array ordenado."}, {"type": "code", "language": "cpp", "code": "vector<int> z_function(const string& s) {\n    int n = s.size(); vector<int> z(n);\n    for (int i = 1, l = 0, r = 0; i < n; ++i) {\n        if (i <= r) z[i] = min(r - i + 1, z[i - l]);\n        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) ++z[i];\n        if (i + z[i] - 1 > r) l = i, r = i + z[i] - 1;\n    }\n    return z;\n}", "lineNumbers": true, "title": "Z-function"}, {"type": "subsection", "id": "trie", "number": "9.1", "title": "Trie e dicionários de prefixos", "tag": "PREFIXOS", "accent": "teal", "blocks": [{"type": "paragraph", "text": "Uma trie armazena caracteres em caminhos, permitindo prefixos em tempo proporcional ao comprimento da palavra. Para alfabeto grande, use `map` ou vetor comprimido; para muitas palavras e poucos caracteres, arrays são mais rápidos."}, {"type": "code", "language": "cpp", "code": "struct Node { array<int, 26> next; bool terminal = false; Node() { next.fill(-1); } };\nvector<Node> trie(1);\nvoid add(const string& s) {\n    int v = 0;\n    for (char c : s) {\n        int x = c - 'a';\n        if (trie[v].next[x] == -1) trie[v].next[x] = trie.size(), trie.emplace_back();\n        v = trie[v].next[x];\n    }\n    trie[v].terminal = true;\n}", "lineNumbers": true}]}, {"type": "subsection", "id": "palindromos", "number": "9.2", "title": "Palíndromos e Manacher", "tag": "PADRÃO", "accent": "pink", "blocks": [{"type": "paragraph", "text": "Manacher calcula todos os raios de palíndromos centrados em posições e entre posições em `O(n)`. Uma alternativa mais simples é DP ou expansão de centro quando `n` é pequeno. Escolha a técnica cuja prova e implementação sejam proporcionais ao limite."}, {"type": "list", "style": "check", "items": ["Palíndromo de uma consulta: hash reverso ou expansão.", "Muitas consultas: Manacher, eertree ou hash com verificação.", "Muitos padrões: Aho–Corasick."]}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Imprima a função prefixo de uma string.", "Encontre todas as ocorrências de um padrão usando KMP.", "Insira palavras em uma trie e consulte prefixos.", "Verifique se uma string é palíndromo ignorando espaços e maiúsculas."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "matematica", "number": "10", "title": "Matemática para competições", "blocks": [{"type": "paragraph", "text": "A matemática competitiva recompensa reconhecer estruturas: módulo, gcd, inversos, primos, combinatória, exponenciação e teoria dos números. Escreva hipóteses e limites antes de escolher tipos e fórmulas.", "lead": true}, {"type": "heading", "level": 3, "text": "Aritmética modular"}, {"type": "code", "language": "cpp", "code": "long long modpow(long long a, long long e, long long mod) {\n    if (mod <= 0 || e < 0) throw invalid_argument(\"mod deve ser positivo e expoente não negativo\");\n    a %= mod;\n    long long r = 1 % mod;\n    while (e) {\n        if (e & 1) r = (__int128)r * a % mod;\n        a = (__int128)a * a % mod;\n        e >>= 1;\n    }\n    return r;\n}", "lineNumbers": true, "title": "Exponenciação binária segura"}, {"type": "paragraph", "text": "Quando `p` é primo e `a` não é divisível por `p`, o inverso modular é `a^(p-2) mod p`. Para módulos não necessariamente primos, use Euclides estendido quando `gcd(a,m)=1`."}, {"type": "code", "language": "cpp", "code": "long long extgcd(long long a, long long b, long long& x, long long& y) {\n    if (!b) { x = 1; y = 0; return a; }\n    long long x1, y1;\n    long long g = extgcd(b, a % b, x1, y1);\n    x = y1; y = x1 - (a / b) * y1;\n    return g;\n}", "lineNumbers": true, "title": "Euclides estendido"}, {"type": "heading", "level": 3, "text": "Crivo e combinatória"}, {"type": "code", "language": "cpp", "code": "vector<bool> prime(n + 1, true);\nif (n >= 0) prime[0] = false;\nif (n >= 1) prime[1] = false;\nfor (int p = 2; 1LL * p * p <= n; ++p)\n    if (prime[p])\n        for (long long x = 1LL * p * p; x <= n; x += p) prime[x] = false;", "lineNumbers": true, "title": "Crivo de Eratóstenes"}, {"type": "paragraph", "text": "Para muitas combinações módulo primo, pré-calcule fatoriais e fatoriais inversos. Se o módulo não for primo ou os expoentes forem relevantes, considere fatoração, Lucas, CRT ou técnicas específicas de p-ádicos."}, {"type": "subsection", "id": "probabilidade", "number": "10.1", "title": "Probabilidade e expectativa", "tag": "MODELO", "accent": "amber", "blocks": [{"type": "paragraph", "text": "Defina a variável aleatória e use linearidade da esperança: `E[X+Y] = E[X] + E[Y]` mesmo quando X e Y não são independentes. Em processos, escreva equações de estado e verifique se há absorção ou ciclos."}, {"type": "math", "tex": "E[X+Y]=E[X]+E[Y]", "caption": "Linearidade da esperança"}, {"type": "math", "tex": "P(A\\mid B)=\\frac{P(A\\cap B)}{P(B)}", "caption": "Probabilidade condicional"}]}, {"type": "subsection", "id": "geometria", "number": "10.2", "title": "Geometria computacional", "tag": "GEOMETRIA", "accent": "cyan", "blocks": [{"type": "paragraph", "text": "Use produto vetorial para orientação: sinal de `(b-a) × (c-a)` distingue esquerda, direita e colinearidade. Compare com `long long` ou `__int128`; use epsilon somente quando a entrada for realmente real."}, {"type": "code", "language": "cpp", "code": "struct Point { long long x, y; };\n__int128 cross(Point a, Point b, Point c) {\n    return (__int128)(b.x-a.x)*(c.y-a.y) - (__int128)(b.y-a.y)*(c.x-a.x);\n}", "lineNumbers": true, "title": "Orientação robusta"}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Calcule `a^b mod m` por exponenciação binária.", "Liste os primos até `n` com crivo.", "Calcule `gcd` de todos os elementos de uma lista.", "Conte combinações módulo um primo usando fatoriais pré-calculados."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "tecnicas-avancadas", "number": "11", "title": "Técnicas avançadas e modelagem de problemas difíceis", "blocks": [{"type": "paragraph", "text": "Problemas avançados raramente pedem apenas “implemente X”. Eles combinam uma modelagem com uma estrutura de dados ou uma transformação matemática. A habilidade central é reconhecer o núcleo depois de remover a narrativa.", "lead": true}, {"type": "heading", "level": 3, "text": "Divide and conquer e meet-in-the-middle"}, {"type": "paragraph", "text": "Divida o espaço de busca em metades quando `2^n` é grande demais, mas `2^(n/2)` é aceitável. Gere todas as somas de cada metade, ordene uma lista e faça busca binária ou two pointers."}, {"type": "code", "language": "cpp", "code": "vector<long long> sums(const vector<long long>& a) {\n    vector<long long> r = {0};\n    for (auto x : a) {\n        int old = r.size();\n        for (int i = 0; i < old; ++i) r.push_back(r[i] + x);\n    }\n    return r;\n}", "lineNumbers": true, "title": "Gerar subconjuntos de uma metade"}, {"type": "heading", "level": 3, "text": "Bitmask DP e submáscaras"}, {"type": "code", "language": "cpp", "code": "for (int mask = 0; mask < (1 << n); ++mask) {\n    for (int sub = mask; sub; sub = (sub - 1) & mask) {\n        int rest = mask ^ sub;\n        // transição sobre uma partição sub/rest\n    }\n}", "lineNumbers": true, "title": "Enumerar submáscaras"}, {"type": "paragraph", "text": "A enumeração de todas as submáscaras custa `O(3^n)` no total sobre todas as máscaras. Use-a apenas para `n` pequeno e procure simetrias, transformada de soma sobre subconjuntos (SOS DP) ou uma reformulação."}, {"type": "heading", "level": 3, "text": "Jogos e minimax"}, {"type": "paragraph", "text": "Em jogos imparciais, o estado pode ser vencedor/perdedor e a transição segue “existe um movimento para um perdedor”. Em jogos com pontuação, minimax alterna max e min; poda alfa-beta ajuda na prática, mas a correção vem da enumeração completa do estado relevante."}, {"type": "subsection", "id": "flow-modeling", "number": "11.1", "title": "Modelagem: transforme a história", "tag": "MODELAGEM", "accent": "red", "blocks": [{"type": "paragraph", "text": "Casamentos, tarefas e atribuição viram matching; restrições de precedência viram DAG; capacidade de corte vira fluxo; “escolher itens sem conflitos” pode virar caminho máximo, matching ou DP. Antes de codar, desenhe o grafo e identifique o que cada vértice e aresta representam."}, {"type": "list", "style": "number", "items": ["Pergunte qual é o objeto mínimo que descreve uma decisão.", "Procure conservação, monotonicidade, equivalência e simetria.", "Verifique se pesos negativos, ciclos ou multiplicidade quebram o algoritmo escolhido."]}]}, {"type": "subsection", "id": "offline-queries", "number": "11.2", "title": "Consultas offline e Mo", "tag": "CONSULTAS", "accent": "violet", "blocks": [{"type": "paragraph", "text": "Se as consultas podem ser reordenadas, processe-as offline. Ordenação por bloco leva Mo a cerca de `O((n+q)√n)` movimentos em muitos problemas; sweep line e eventos ordenados podem reduzir uma dimensão inteira."}, {"type": "code", "language": "cpp", "code": "sort(queries.begin(), queries.end(), [&](Query a, Query b) {\n    int ba = a.l / block, bb = b.l / block;\n    if (ba != bb) return ba < bb;\n    return (ba & 1) ? a.r > b.r : a.r < b.r;\n});", "lineNumbers": true, "title": "Ordenação de Mo com alternância"}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Enumere subconjuntos de até 20 elementos.", "Resolva subset sum com meet-in-the-middle para `n≤40`.", "Calcule Grundy de um jogo simples de retirar pedras.", "Processe consultas de soma offline ordenando por limite."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "engenharia-contest", "number": "12", "title": "Engenharia de contest: correção, desempenho e pós-análise", "blocks": [{"type": "paragraph", "text": "Conhecer algoritmos não basta: submissões falham por I/O, índices, overflow, estado não reinicializado, recursão profunda e interpretação. Uma rotina operacional reduz falhas sem tornar o código ilegível.", "lead": true}, {"type": "heading", "level": 3, "text": "Checklist antes de enviar"}, {"type": "list", "style": "check", "items": ["O tipo numérico comporta a maior soma, produto e multiplicidade?", "Há arrays limpos entre casos de teste?", "A resposta para `n=0`, `n=1`, todos iguais e valores extremos está definida?", "A complexidade cabe no pior caso, incluindo ordenações e alocações?", "A saída tem exatamente o formato pedido, sem debug?", "A prova depende de uma hipótese que o código realmente garante?"]}, {"type": "heading", "level": 3, "text": "Testes adversariais"}, {"type": "code", "language": "cpp", "code": "mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());\nfor (int tc = 0; tc < 10000; ++tc) {\n    int n = rng() % 8 + 1;\n    // compare solução otimizada com força bruta\n}", "lineNumbers": true, "title": "Stress testing conceitual"}, {"type": "paragraph", "text": "Para criar um validador, gere casos pequenos aleatórios, execute a solução rápida e uma solução lenta obviamente correta e compare saídas. Reduza o caso que falha até obter um contraexemplo mínimo; ele normalmente revela o invariante quebrado."}, {"type": "heading", "level": 3, "text": "Undefined behavior e portabilidade"}, {"type": "list", "style": "bullet", "items": ["Não acesse fora do vetor, mesmo que “a memória pareça funcionar”.", "Não dependa de overflow assinado; ele é comportamento indefinido em C++.", "Use `long long` e `__int128` explicitamente nas expressões.", "Evite recursão profunda em grafos de até centenas de milhares de vértices.", "Não assuma que a ordem de iteração de `unordered_map` é estável."]}, {"type": "callout", "variant": "key", "text": "O melhor código competitivo é curto porque a ideia foi simplificada antes, não porque detalhes importantes foram escondidos. Nomeie estados, isolе funções de prova e mantenha o template como ferramenta, não como superstição.", "title": "Clareza vence micro-otimização"}, {"type": "subsection", "id": "roadmap", "number": "12.1", "title": "Roteiro de progressão", "tag": "PLANO", "accent": "green", "blocks": [{"type": "paragraph", "text": "Uma progressão sustentável é mais valiosa que uma lista infinita de tópicos. Refaça problemas após uma semana, resolva variações e escreva a prova em português antes de olhar a implementação de terceiros."}, {"type": "list", "style": "number", "items": ["**Etapa 1:** C++ básico, complexidade, STL, ordenação, prefixos e busca binária.", "**Etapa 2:** greedy, DP introdutória, BFS/DFS, DSU, caminhos mínimos e árvores.", "**Etapa 3:** Fenwick, segment tree, strings, matemática modular, SCC, LCA e MST.", "**Etapa 4:** fluxo, matching, otimizações de DP, suffix structures, geometria e técnicas offline.", "**Etapa 5:** contests completos, análise de editoriais, problemas de nível e especialização."]}]}, {"type": "subsection", "id": "referencias", "number": "12.2", "title": "Referências e prática", "tag": "REFERÊNCIAS", "accent": "blue", "blocks": [{"type": "paragraph", "text": "Este livro foi inspirado na organização temática do [Competitive Programmer’s Handbook em português](https://github.com/natanlimaz/cphb_ptbr), mas o texto e os exemplos aqui são autorais e foram ampliados para C++ moderno."}, {"type": "list", "style": "bullet", "items": ["[CSES Problem Set](https://cses.fi/problemset/) — trilhas de problemas por tema.", "[cp-algorithms](https://cp-algorithms.com/) — algoritmos, provas e implementações de referência.", "[cppreference](https://en.cppreference.com/w/cpp) — linguagem C++ e biblioteca padrão.", "[USACO Guide](https://usaco.guide/) — currículo progressivo e listas de exercícios.", "[Codeforces](https://codeforces.com/) e [AtCoder](https://atcoder.jp/) — competições e problemas variados.", "[ICPC](https://icpc.global/) — contexto e regulamentos de competições universitárias."]}, {"type": "callout", "variant": "info", "text": "Respeite as licenças de cada fonte, confira versões de C++ aceitas pela plataforma e trate editoriais como material de estudo, não como substituto da prova.", "title": "Uso responsável das referências"}]}, {"type": "divider"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis — consolide o conteúdo"}, {"type": "paragraph", "text": "Resolva sem consultar código pronto. Para cada exercício, anote a complexidade esperada e um caso de borda antes de implementar."}, {"type": "list", "style": "number", "items": ["Escreva uma solução lenta para comparar com uma solução rápida em casos aleatórios.", "Crie testes para vetor vazio, um elemento, todos iguais e valores máximos.", "Meça o impacto de reservar capacidade em um vetor.", "Faça uma checklist pessoal de cinco itens antes de enviar uma solução."]}, {"type": "callout", "variant": "tip", "text": "Depois de resolver, escreva uma frase explicando por que a técnica escolhida é suficiente e qual hipótese faria essa técnica deixar de funcionar.", "title": "Rotina de revisão"}]}], "imageRights": {"images/history-dijkstra.jpg": {"source": "Busca de imagens na internet; página de origem registrada no relatório de revisão", "license": "Direitos não determinados na fonte de busca; substituir antes de publicação comercial", "credit": "Fonte de imagem consultada", "retrievedAt": "2026-09-24"}}}, "fisica-eletrica-engenharia-embarcada": {"manifest": {"schema": "books.package.v2", "kind": "book-package", "id": "fisica-eletrica-engenharia-embarcada", "title": "Física Elétrica: da Eletrostática à Engenharia de Sistemas Embarcados", "description": "Livro completo em português sobre eletricidade, eletromagnetismo, circuitos, semicondutores, eletrônica, sistemas embarcados, controle, DSP, instrumentação, confiabilidade e segurança.", "language": "pt-BR", "tags": ["física", "eletricidade", "eletromagnetismo", "circuitos", "eletrônica", "sistemas embarcados", "controle", "instrumentação"], "header": "header.json", "sections": ["sections/fundamentos-matematica.json", "sections/eletrostatica.json", "sections/circuitos-dc-ac.json", "sections/eletromagnetismo-ondas.json", "sections/semicondutores-eletronica.json", "sections/sistemas-embarcados.json", "sections/controle-dsp-instrumentacao.json", "sections/derivacoes-e-metodo.json", "sections/projetos-e-referencias.json"]}, "header": {"schema": "books.header.v2", "kind": "book-header", "kicker": "física · elétrica · eletrônica · embarcados", "title": "Física Elétrica: da Eletrostática à Engenharia de Sistemas Embarcados", "subtitle": "Conceitos, leis, teoremas, modelos, aplicações e engenharia — do campo elétrico à aquisição, controle e segurança.", "guideTitle": "Como usar este livro", "guideText": "Estude a sequência de pré-requisitos, resolva os exercícios fáceis ao final de cada seção e use os projetos como laboratório conceitual. Toda fórmula deve ser lida junto das hipóteses, unidades e limites de validade.", "cover": {"src": "cover.svg", "alt": "Capa abstrata com campos elétricos, circuito e microcontrolador", "ratio": "16:9"}, "legend": [{"label": "conceito", "color": "blue"}, {"label": "equação", "color": "teal"}, {"label": "atenção", "color": "amber"}, {"label": "engenharia", "color": "violet"}, {"label": "segurança", "color": "red"}], "footer": "Material didático autoral sintetizado de referências acadêmicas e institucionais. Consulte normas e datasheets completos para projetos reais."}, "sections": [{"schema": "books.section.v2", "kind": "book-section", "id": "fundamentos-matematica", "number": "0", "title": "Pré-requisitos, unidades e linguagem dos modelos", "blocks": [{"type": "paragraph", "text": "Este livro começa com as ferramentas usadas para descrever fenômenos elétricos. O objetivo não é decorar fórmulas, mas saber quais grandezas são conservadas, quais hipóteses tornam um modelo válido e como verificar dimensionalmente um resultado.", "lead": true}, {"type": "heading", "level": 3, "text": "Grandezas e unidades SI"}, {"type": "paragraph", "text": "Carga elétrica é medida em coulomb (C), corrente em ampere (A), tensão e potencial em volt (V), resistência em ohm (Ω), capacitância em farad (F), indutância em henry (H), potência em watt (W) e energia em joule (J). No SI, a carga elementar é e = 1,602 176 634 × 10⁻¹⁹ C, valor exato. A velocidade da luz no vácuo é c = 299 792 458 m/s, também exata."}, {"type": "table", "header": ["Grandeza", "Símbolo", "Unidade", "Interpretação"], "rows": [["Carga", "q", "C", "propriedade elétrica conservada"], ["Corrente", "I", "A = C/s", "taxa de fluxo de carga"], ["Tensão", "V", "V = J/C", "energia por unidade de carga"], ["Potência", "P", "W = J/s", "taxa de transferência de energia"], ["Campo elétrico", "E", "N/C = V/m", "força por carga de teste"], ["Campo magnético", "B", "T", "efeito magnético sobre cargas em movimento"]], "caption": "Mapa de grandezas"}, {"type": "heading", "level": 3, "text": "Vetores, derivadas e integrais"}, {"type": "paragraph", "text": "Campo elétrico e campo magnético são vetoriais. Produto escalar mede projeção e fluxo; produto vetorial determina direção de torque e força magnética. Derivadas descrevem variação local. Integrais somam uma densidade ao longo de linha, superfície ou volume. Gradiente aponta para o crescimento mais rápido de um escalar; divergente mede fontes ou sumidouros locais; rotacional mede circulação local."}, {"type": "math", "tex": "\\nabla V = (\\partial V/\\partial x,\\partial V/\\partial y,\\partial V/\\partial z),\\quad \\nabla\\cdot E,\\quad \\nabla\\times E", "caption": "Operadores vetoriais centrais"}, {"type": "heading", "level": 3, "text": "Como validar uma equação"}, {"type": "list", "style": "check", "items": ["Confira unidades em cada termo; não se pode somar volts a amperes.", "Teste limites: resistência nula, tempo zero, tempo infinito, distância grande e simetrias.", "Declare o sistema de coordenadas e os sinais.", "Separe modelo ideal de efeitos reais como perdas, parasitas, saturação e temperatura.", "Compare uma ordem de grandeza antes de confiar em muitos algarismos."]}, {"type": "callout", "variant": "warning", "text": "Uma fórmula sem as hipóteses que a acompanham é incompleta. Por exemplo, a lei de Ohm descreve componentes ôhmicos; um diodo exige uma relação não linear e um transistor depende do ponto de operação.", "title": "Modelos têm domínio de validade"}, {"type": "heading", "level": 3, "text": "Trilha de pré-requisitos"}, {"type": "paragraph", "text": "Para a parte introdutória, revise álgebra, trigonometria, vetores, energia e derivadas. Para Maxwell e ondas, acrescente cálculo vetorial, integrais de linha e superfície e equações diferenciais. Para controle e DSP, acrescente números complexos, Laplace, Fourier, álgebra linear e probabilidade."}, {"type": "heading", "level": 3, "text": "Exercícios fáceis"}, {"type": "list", "style": "bullet", "items": ["Converta 2,5 mA em A, 3,3 kΩ em Ω e 470 nF em F.", "Verifique dimensionalmente P = VI e E = V/d.", "Represente um vetor de módulo 5 em componentes quando ele faz 53° com o eixo x.", "Explique por que uma corrente é uma grandeza escalar orientada por uma convenção, enquanto o campo elétrico é vetorial."]}, {"type": "history", "name": "Newton e Leibniz", "shortBio": "Isaac Newton (1643–1727), matemático e físico inglês, e Gottfried Wilhelm Leibniz (1646–1716), filósofo e matemático alemão, desenvolveram o cálculo de forma independente.", "insight": "O cálculo nasceu da necessidade de descrever variação e acumulação contínuas. A derivada mede uma taxa local; a integral soma contribuições infinitesimais. A disputa posterior de prioridade não muda o fato de que as duas notações influenciaram a forma moderna da disciplina.", "image": {"src": "images/history-newton.jpg", "alt": "Retrato de Isaac Newton"}}, {"type": "history", "name": "Carl Friedrich Gauss", "shortBio": "Carl Friedrich Gauss (1777–1855) foi um matemático e físico alemão que trabalhou em teoria dos números, geodesia e eletromagnetismo.", "insight": "A Lei de Gauss transforma uma distribuição com simetria em um cálculo de fluxo pela superfície. O ganho não é uma nova força, mas um atalho baseado na conservação e na simetria do campo.", "image": {"src": "images/history-gauss.jpg", "alt": "Retrato de Carl Friedrich Gauss"}}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "eletrostatica", "number": "1", "title": "Eletrostática: carga, campo, potencial e energia", "blocks": [{"type": "paragraph", "text": "Eletrostática estuda cargas-fonte estacionárias. A carga é quantizada e conservada. Cargas de mesmo sinal se repelem; sinais opostos se atraem. O princípio de superposição permite somar as contribuições de várias fontes.", "lead": true}, {"type": "heading", "level": 3, "text": "Lei de Coulomb"}, {"type": "paragraph", "text": "Para duas cargas puntiformes no vácuo, a força é radial e obedece"}, {"type": "math", "tex": "\\vec F_{12}=\\frac{1}{4\\pi\\varepsilon_0}\\frac{q_1q_2}{r^2}\\hat r_{12}", "caption": "Lei de Coulomb"}, {"type": "paragraph", "text": "Em um meio linear homogêneo, substitui-se ε₀ por ε = ε_r ε₀. O sinal de q₁q₂ determina atração ou repulsão. A força sobre cada carga tem mesmo módulo e sentido oposto, em acordo com a terceira lei de Newton."}, {"type": "heading", "level": 3, "text": "Campo elétrico e superposição"}, {"type": "paragraph", "text": "Campo elétrico é força por carga de teste positiva: E = F/q₀. Para N cargas, soma-se vetorialmente. Para uma distribuição contínua, substitui-se a soma por uma integral com densidade linear λ, superficial σ ou volumétrica ρ."}, {"type": "math", "tex": "\\vec E(\\vec r)=\\frac{1}{4\\pi\\varepsilon_0}\\sum_i q_i\\frac{\\vec r-\\vec r_i}{|\\vec r-\\vec r_i|^3}", "caption": "Campo de cargas puntiformes"}, {"type": "heading", "level": 3, "text": "Fluxo e lei de Gauss"}, {"type": "paragraph", "text": "Fluxo elétrico mede quanto campo atravessa uma superfície. A lei de Gauss relaciona o fluxo líquido através de uma superfície fechada à carga encerrada:"}, {"type": "math", "tex": "\\oint_S \\vec E\\cdot d\\vec A=\\frac{Q_{enc}}{\\varepsilon_0}", "caption": "Lei de Gauss"}, {"type": "paragraph", "text": "A lei é sempre verdadeira, mas só simplifica o cálculo quando há simetria esférica, cilíndrica ou planar. O procedimento é identificar a simetria, escolher uma superfície gaussiana e explorar o módulo constante do campo."}, {"type": "heading", "level": 3, "text": "Potencial, trabalho e energia"}, {"type": "paragraph", "text": "Potencial é energia potencial por unidade de carga. Em eletrostática, o campo é conservativo: o trabalho independe do caminho e E = −∇V."}, {"type": "math", "tex": "\\Delta V=-\\int_A^B \\vec E\\cdot d\\vec l,\\quad U=qV,\\quad W_{campo}=-\\Delta U", "caption": "Relações entre campo e potencial"}, {"type": "paragraph", "text": "Para uma carga puntiforme com V(∞)=0, V = kq/r. Potenciais são escalares e somam algebricamente. Um elétron-volt é 1 eV = 1,602 176 634 × 10⁻¹⁹ J."}, {"type": "heading", "level": 3, "text": "Condutores, dipolos e capacitores"}, {"type": "paragraph", "text": "Um condutor em equilíbrio eletrostático é equipotencial. O campo tangencial na superfície é zero e o excesso de carga livre fica na superfície. Um dipolo possui momento p = qd orientado da carga negativa para a positiva; em campo uniforme, τ = p × E e U = −p·E."}, {"type": "paragraph", "text": "Capacitância é C = Q/ΔV. Para placas paralelas ideais, C = εA/d. A energia armazenada é U = ½C(ΔV)² e a densidade no meio linear é u_E = ½εE²."}, {"type": "heading", "level": 3, "text": "Problema guiado: campo de um anel carregado"}, {"type": "paragraph", "text": "Considere um anel de raio a, carga total Q e um ponto no eixo a uma distância z do centro. Por simetria, componentes transversais se cancelam. Cada elemento está à distância r = √(a²+z²), e apenas a componente axial sobrevive."}, {"type": "math", "tex": "dE_z=\\frac{1}{4\\pi\\varepsilon_0}\\frac{z}{(a^2+z^2)^{3/2}}dq \\Rightarrow E_z=\\frac{1}{4\\pi\\varepsilon_0}\\frac{Qz}{(a^2+z^2)^{3/2}}", "caption": "Integração usando simetria"}, {"type": "paragraph", "text": "Quando z≫a, o resultado tende a kQ/z², como se o anel fosse uma carga puntiforme. Quando z=0, o campo é zero por simetria. Esses limites são testes de consistência."}, {"type": "heading", "level": 3, "text": "Exercícios fáceis"}, {"type": "list", "style": "bullet", "items": ["Calcule a força entre duas cargas separadas por 20 cm e determine se é atrativa.", "Use Gauss para obter o campo de uma linha infinita ideal com densidade λ.", "Encontre o potencial produzido por duas cargas em um ponto e compare com o campo.", "Calcule energia e capacitância de um capacitor de placas paralelas com dados fornecidos."]}, {"type": "history", "name": "Carl Friedrich Gauss", "shortBio": "Carl Friedrich Gauss (1777–1855) foi um matemático e físico alemão cujos métodos ligam simetria, fluxo e cálculo.", "insight": "Na lei de Gauss, a escolha de uma superfície que respeita a simetria transforma uma integral de campo em uma relação entre carga encerrada e fluxo. O teorema não diz que todo campo é radial: a geometria da distribuição é a hipótese que torna a simplificação válida.", "image": {"src": "images/history-gauss.jpg", "alt": "Retrato de Carl Friedrich Gauss"}}, {"type": "history", "name": "Charles-Augustin de Coulomb", "shortBio": "Charles-Augustin de Coulomb (1736–1806) foi um físico francês que mediu forças elétricas e magnéticas com uma balança de torção.", "insight": "A balança de torção permitiu detectar pequenas forças e comparar como elas variavam com a distância. Esse experimento motivou a forma quantitativa da lei de Coulomb.", "image": {"src": "images/history-coulomb.jpg", "alt": "Retrato de Charles-Augustin de Coulomb"}}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "circuitos-dc-ac", "number": "2", "title": "Circuitos: corrente contínua, transitórios e regime senoidal", "blocks": [{"type": "paragraph", "text": "Circuitos concentram elementos e conexões. O modelo de circuito é válido quando dimensões físicas são pequenas diante do comprimento de onda relevante e quando campos distribuídos podem ser representados por tensões e correntes nos elementos.", "lead": true}, {"type": "heading", "level": 3, "text": "Corrente, resistência e potência"}, {"type": "paragraph", "text": "Corrente é I=dQ/dt. Em material ôhmico, V=IR; para um fio uniforme, R=ρL/A. Potência instantânea é p=VI. Em resistor, p=I²R=V²/R e é dissipada como calor."}, {"type": "heading", "level": 3, "text": "Kirchhoff e equivalentes"}, {"type": "paragraph", "text": "A lei dos nós expressa conservação de carga: ΣI=0. A lei das malhas expressa conservação de energia: ΣV=0. Thévenin substitui uma rede linear por uma fonte V_th em série com R_th; Norton usa I_N em paralelo com R_N, com V_th=I_NR_N. Fontes independentes de tensão são curto-circuitadas e fontes independentes de corrente abertas ao calcular resistência vista."}, {"type": "table", "header": ["Técnica", "Quando usar", "Resultado"], "rows": [["Redução série/paralelo", "rede simples", "resistência equivalente"], ["KCL/nodal", "muitos ramos e nós", "tensões nodais"], ["KVL/malhas", "poucas malhas", "correntes de malha"], ["Superposição", "rede linear com várias fontes", "soma de respostas"], ["Thévenin/Norton", "muitas cargas no mesmo porto", "equivalente de dois terminais"]], "caption": "Escolha de método"}, {"type": "heading", "level": 3, "text": "Capacitores e indutores"}, {"type": "paragraph", "text": "Capacitor obedece i=C dv/dt e armazena ½Cv². Indutor obedece v=L di/dt e armazena ½Li². A tensão de um capacitor e a corrente de um indutor não mudam instantaneamente em uma comutação ideal finita."}, {"type": "heading", "level": 3, "text": "Circuitos de primeira e segunda ordem"}, {"type": "math", "tex": "x(t)=x(\\infty)+[x(0^+)-x(\\infty)]e^{-t/\\tau}", "caption": "Resposta de primeira ordem"}, {"type": "paragraph", "text": "Para RC, τ=R_eqC. Para RL, τ=L/R_eq. Em RLC série, Lq¨+Rq˙+q/C=0. Defina α=R/(2L), ω₀=1/√(LC) e ζ=α/ω₀. ζ>1 é superamortecido; ζ=1 é criticamente amortecido; ζ<1 é subamortecido."}, {"type": "heading", "level": 3, "text": "AC, fasores e ressonância"}, {"type": "paragraph", "text": "Em regime senoidal, use impedâncias Z_R=R, Z_L=jωL e Z_C=1/(jωC). Para RLC série, Z=R+j(ωL−1/(ωC)). A ressonância ocorre em ω₀=1/√(LC), quando as reatâncias se cancelam. A qualidade ideal é Q=ω₀L/R e a largura de banda aproximada é Δω=ω₀/Q."}, {"type": "heading", "level": 3, "text": "Problema guiado: filtro RC e resposta a degrau"}, {"type": "paragraph", "text": "Um resistor R alimenta um capacitor C para o terra e a saída é a tensão no capacitor. Pela KCL, (V_in−V_out)/R = C dV_out/dt. Logo RC dV_out/dt + V_out = V_in. Para um degrau V₀ e capacitor inicialmente descarregado, V_out(t)=V₀(1−e^(−t/RC))."}, {"type": "code", "language": "cpp", "code": "double capacitorVoltageAfterStep(double sourceVoltage, double resistanceOhms, double capacitanceFarads, double elapsedSeconds) {\n    // A constante de tempo define a escala temporal do carregamento.\n    double timeConstant = resistanceOhms * capacitanceFarads;\n    return sourceVoltage * (1.0 - exp(-elapsedSeconds / timeConstant));\n}", "lineNumbers": true, "title": "Modelo computacional do transitório RC"}, {"type": "paragraph", "text": "A função é uma tradução direta da solução analítica. Em firmware, use uma amostragem suficientemente rápida, cuide de overflow e compare o modelo com tolerâncias reais, resistência de saída, corrente de fuga e tolerância de R e C."}, {"type": "heading", "level": 3, "text": "Exercícios fáceis"}, {"type": "list", "style": "bullet", "items": ["Resolva uma rede de três resistores em série e paralelo.", "Use KCL para determinar todas as correntes de um circuito de dois nós.", "Calcule τ e o valor após 3τ em um circuito RC.", "Determine a frequência de ressonância de um circuito LC."]}, {"type": "history", "name": "Georg Simon Ohm", "shortBio": "Georg Simon Ohm (1789–1854) foi um físico alemão que relacionou tensão, corrente e resistência em condutores.", "insight": "A recepção inicial de seu trabalho foi fria: o tratado de 1827 foi pouco acolhido e Ohm deixou o posto em Colônia. O reconhecimento veio depois, incluindo a Medalha Copley em 1841. A lei V=RI é, portanto, uma relação experimental de uma classe de condutores, não uma identidade universal para qualquer material.", "image": {"src": "images/history-ohm.jpg", "alt": "Retrato de Georg Simon Ohm"}}, {"type": "history", "name": "Gustav Kirchhoff", "shortBio": "Gustav Kirchhoff (1824–1887) foi um físico alemão que formulou leis fundamentais para análise de circuitos.", "insight": "As leis de Kirchhoff tornam explícitas a conservação de carga nos nós e a conservação de energia nas malhas. Por isso permitem decompor circuitos complexos em equações locais.", "image": {"src": "images/history-kirchhoff.jpg", "alt": "Retrato de Gustav Kirchhoff"}}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "eletromagnetismo-ondas", "number": "3", "title": "Eletromagnetismo: Maxwell, indução, ondas e linhas de transmissão", "blocks": [{"type": "paragraph", "text": "Eletromagnetismo unifica eletricidade, magnetismo e luz. A força sobre uma carga em movimento é F=q(E+v×B). As equações de Maxwell organizam as fontes, a circulação dos campos e a propagação.", "lead": true}, {"type": "heading", "level": 3, "text": "As quatro equações de Maxwell"}, {"type": "math", "tex": "\\nabla\\cdot E=\\rho/\\varepsilon_0,\\quad \\nabla\\cdot B=0,\\quad \\nabla\\times E=-\\partial B/\\partial t,\\quad \\nabla\\times B=\\mu_0J+\\mu_0\\varepsilon_0\\partial E/\\partial t", "caption": "Forma diferencial no vácuo"}, {"type": "paragraph", "text": "A primeira é Gauss elétrica; a segunda expressa ausência de monopolos magnéticos observados; a terceira é Faraday–Lenz; a quarta é Ampère–Maxwell e inclui a corrente de deslocamento. As formas integrais usam fluxo e circulação."}, {"type": "heading", "level": 3, "text": "Indução e energia magnética"}, {"type": "paragraph", "text": "Fluxo magnético é Φ_B=∫B·dA. Uma bobina de N espiras tem fem ε=−N dΦ_B/dt. O sinal de Lenz diz que a resposta induzida se opõe à variação do fluxo. Indutância obedece ε_L=−L dI/dt e armazena U=½LI²."}, {"type": "heading", "level": 3, "text": "Ondas eletromagnéticas"}, {"type": "paragraph", "text": "No vácuo sem fontes, Maxwell produz a equação de onda ∇²ψ−μ₀ε₀∂²ψ/∂t²=0, com c=1/√(μ₀ε₀). Em onda plana, E, B e a direção de propagação são perpendiculares, E/B=c, e c=fλ."}, {"type": "paragraph", "text": "O vetor de Poynting S=(1/μ₀)E×B representa fluxo de energia por área. A densidade de energia é u=½ε₀E²+B²/(2μ₀)."}, {"type": "heading", "level": 3, "text": "Linhas de transmissão"}, {"type": "paragraph", "text": "Quando o comprimento do circuito não é pequeno diante do comprimento de onda, tensão e corrente dependem da posição. O modelo RLGC usa resistência R, indutância L, condutância G e capacitância C por unidade de comprimento."}, {"type": "math", "tex": "\\gamma=\\sqrt{(R+j\\omega L)(G+j\\omega C)},\\quad Z_0=\\sqrt{\\frac{R+j\\omega L}{G+j\\omega C}}", "caption": "Propagação e impedância característica"}, {"type": "paragraph", "text": "Para uma carga Z_L, a reflexão é Γ=(Z_L−Z₀)/(Z_L+Z₀). Casamento Z_L=Z₀ elimina a reflexão. Esse conceito aparece em RF, antenas, cabos, USB, sensores rápidos e placas digitais."}, {"type": "heading", "level": 3, "text": "Problema guiado: fem de uma espira em rotação"}, {"type": "paragraph", "text": "Uma espira de área A gira em campo uniforme B com ângulo θ(t)=ωt. O fluxo é Φ=B A cos(ωt). Pela lei de Faraday, ε(t)=−dΦ/dt=B A ω sin(ωt). A amplitude cresce com B, área e velocidade angular; o sinal depende da convenção de orientação."}, {"type": "heading", "level": 3, "text": "Exercícios fáceis"}, {"type": "list", "style": "bullet", "items": ["Calcule a força magnética em uma carga que entra perpendicularmente em B.", "Determine a fem média quando o fluxo muda linearmente.", "Use Maxwell para identificar qual termo representa corrente de deslocamento.", "Calcule Γ para uma linha de 50 Ω terminada em 75 Ω."]}, {"type": "heading", "level": 3, "text": "Linha histórica: corrente, indução e ondas"}, {"type": "paragraph", "text": "A sequência experimental é cumulativa: Ørsted observou em 1820 que uma corrente desviava a agulha de uma bússola; Faraday mostrou em 1831 que uma variação de campo magnético induz corrente; Maxwell organizou essas relações em equações; Hertz produziu e mediu ondas eletromagnéticas no laboratório. A história não substitui a matemática: ela mostra quais fenômenos cada termo precisa explicar."}, {"type": "history", "name": "Hans Christian Ørsted", "shortBio": "Hans Christian Ørsted (1777–1851) foi um físico e químico dinamarquês.", "insight": "Durante uma demonstração, percebeu que a corrente alterava a direção de uma bússola próxima; depois repetiu o efeito e publicou-o em 1820. A observação conectou eletricidade e magnetismo e abriu o caminho experimental para Ampère, Faraday e Maxwell.", "image": {"src": "images/history-orsted.jpg", "alt": "Retrato de Hans Christian Ørsted"}}, {"type": "history", "name": "Heinrich Hertz", "shortBio": "Heinrich Rudolf Hertz (1857–1894) foi um físico alemão que investigou a radiação eletromagnética.", "insight": "Entre 1885 e 1889, gerou ondas no laboratório e mediu comprimento e velocidade, além de reflexão e refração. Esses resultados confirmaram experimentalmente a previsão de Maxwell de que perturbações eletromagnéticas se propagam como ondas.", "image": {"src": "images/history-hertz.jpg", "alt": "Retrato de Heinrich Hertz"}}, {"type": "history", "name": "Michael Faraday", "shortBio": "Michael Faraday (1791–1867) foi um físico e químico inglês autodidata, originalmente aprendiz de encadernador.", "insight": "Faraday mostrou que campos magnéticos variáveis podem induzir corrente. A ideia de linhas de campo e indução conecta experimento, geometria e a forma posterior das equações de Maxwell.", "image": {"src": "images/history-faraday.jpg", "alt": "Retrato de Michael Faraday"}}, {"type": "history", "name": "James Clerk Maxwell", "shortBio": "James Clerk Maxwell (1831–1879) foi um físico escocês que unificou eletricidade, magnetismo e luz em um sistema de equações.", "insight": "Ao combinar as leis conhecidas e corrigir a simetria da corrente de deslocamento, Maxwell obteve uma velocidade de propagação compatível com a luz. Hertz confirmou experimentalmente as ondas eletromagnéticas.", "image": {"src": "images/history-maxwell.jpg", "alt": "Retrato de James Clerk Maxwell"}}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "semicondutores-eletronica", "number": "4", "title": "Semicondutores, diodos, transistores e conversão de dados", "blocks": [{"type": "paragraph", "text": "Eletrônica usa materiais cuja condutividade pode ser controlada por dopagem, campo elétrico, luz e temperatura. Os modelos desta seção são aproximações de engenharia; o datasheet e o ponto de operação prevalecem sobre uma fórmula isolada.", "lead": true}, {"type": "heading", "level": 3, "text": "Portadores e deriva-difusão"}, {"type": "paragraph", "text": "Em semicondutor, elétrons e lacunas transportam carga. Em equilíbrio, np=n_i². A condutividade é σ=q(nμ_n+pμ_p). A corrente combina deriva pelo campo e difusão por gradiente de concentração."}, {"type": "math", "tex": "J_n=q\\mu_n nE+qD_n\\frac{dn}{dx},\\quad J_p=q\\mu_p pE-qD_p\\frac{dp}{dx}", "caption": "Modelo de deriva-difusão"}, {"type": "heading", "level": 3, "text": "Junção PN e diodo"}, {"type": "paragraph", "text": "A junção forma uma região de depleção e uma barreira de potencial. No modelo de Shockley, I_D=I_S[exp(V_D/(nV_T))−1], com V_T=kT/q. Ruptura reversa, capacitância, temperatura e recombinação limitam o modelo."}, {"type": "heading", "level": 3, "text": "MOSFET e BJT"}, {"type": "paragraph", "text": "No NMOS de canal longo, na região de saturação, I_D≈½μ_nC_ox(W/L)(V_GS−V_T)². O BJT em ativo direto pode ser descrito por I_C≈I_Sexp(V_BE/V_T). Em torno do ponto de operação, pequenos sinais usam g_m e resistências incrementais."}, {"type": "heading", "level": 3, "text": "Amplificadores e realimentação"}, {"type": "paragraph", "text": "Métricas de amplificadores incluem ganho, impedâncias, largura de banda, ruído, distorção, excursão e estabilidade. O amplificador operacional ideal em realimentação negativa assume correntes de entrada nulas e tensões de entrada aproximadamente iguais, mas dispositivos reais têm offset, slew rate e saturação."}, {"type": "heading", "level": 3, "text": "ADC, DAC e ruído"}, {"type": "paragraph", "text": "Para ADC ideal de N bits com faixa V_FS, Δ=V_FS/2^N e ruído de quantização RMS Δ/√12. Para senoide em escala total, SQNR≈6,02N+1,76 dB. Amostragem exige filtro anti-alias e, para banda B, f_s>2B no modelo ideal."}, {"type": "paragraph", "text": "Ruídos independentes somam-se em potência: v_total=√(v₁²+v₂²+...). Resistor apresenta ruído térmico v_n²=4kTRB; fluxo discreto produz ruído shot i_n²=2qIB."}, {"type": "heading", "level": 3, "text": "Problema guiado: escolher resistor para LED"}, {"type": "paragraph", "text": "Para fonte V_S, LED com queda V_F e corrente desejada I_F, o resistor ideal é R=(V_S−V_F)/I_F. A potência no resistor é P_R=I_F²R e a potência no LED é P_LED=V_FI_F. Verifique margem de fonte, tolerâncias, temperatura, corrente máxima e se o GPIO pode fornecer a corrente."}, {"type": "code", "language": "cpp", "code": "// Dimensiona o resistor e verifica a potência dissipada.\ndouble calculateLedResistor(double supplyVoltage, double ledForwardVoltage, double ledCurrent) {\n    return (supplyVoltage - ledForwardVoltage) / ledCurrent;\n}\n\ndouble calculateResistorPower(double resistorValue, double ledCurrent) {\n    return resistorValue * ledCurrent * ledCurrent;\n}", "lineNumbers": true, "title": "Cálculo modular de um limitador de corrente"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis"}, {"type": "list", "style": "bullet", "items": ["Calcule a corrente aproximada de um diodo em um ponto dado.", "Determine as regiões de operação de um MOSFET a partir de V_GS, V_DS e V_T.", "Calcule o passo e o SQNR ideal de um ADC.", "Faça um orçamento de três fontes de ruído independentes."]}, {"type": "history", "name": "Bardeen, Brattain e Shockley", "shortBio": "John Bardeen, Walter Brattain e William Shockley participaram da invenção do transistor nos Bell Labs, em 1947.", "insight": "O transistor substituiu válvulas volumosas em muitas aplicações ao controlar corrente em um dispositivo sólido. O resultado foi uma mudança de escala na eletrônica, não apenas uma troca de componente.", "image": {"src": "images/history-transistor.jpg", "alt": "Fotografia histórica dos inventores do transistor"}}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "sistemas-embarcados", "number": "5", "title": "Engenharia elétrica em sistemas embarcados", "blocks": [{"type": "paragraph", "text": "Um sistema embarcado integra hardware e firmware sob restrições de energia, tempo, confiabilidade, segurança e custo. O circuito deve funcionar no mundo físico; por isso alimentação, retorno de corrente, ruído, tolerâncias e diagnóstico são parte do software tanto quanto do PCB.", "lead": true}, {"type": "heading", "level": 3, "text": "Alimentação e desacoplamento"}, {"type": "paragraph", "text": "Transições digitais geram pulsos de corrente. Capacitores de desacoplamento locais fornecem carga de alta frequência e devem ter laço curto entre pino de alimentação e terra. O valor exato depende do datasheet, da impedância desejada, do ESR/ESL e do espectro do transiente."}, {"type": "heading", "level": 3, "text": "GPIO, temporizadores e PWM"}, {"type": "paragraph", "text": "GPIO configura direção, nível lógico, pull-up/pull-down, multiplexação e, em alguns MCUs, open-drain e slew rate. PWM usa período T=1/f e duty D=t_on/T. A média de uma saída ideal pode controlar brilho, motores, aquecedores e servos, mas a carga e a frequência determinam ripple, ruído e aquecimento."}, {"type": "heading", "level": 3, "text": "ADC e sensores"}, {"type": "paragraph", "text": "O capacitor de sample-and-hold precisa carregar dentro do tempo de aquisição. Impedância da fonte, filtro RC, referência, jitter e ruído afetam a conversão. Um sensor analógico deve ter condicionamento, proteção, calibração e faixa compatível com o ADC."}, {"type": "heading", "level": 3, "text": "Barramentos"}, {"type": "table", "header": ["Barramento", "Linhas", "Característica"], "rows": [["UART", "TX/RX", "assíncrono, simples, ponto a ponto"], ["SPI", "SCLK, MOSI, MISO, CS", "síncrono e rápido, mais fios"], ["I²C", "SDA/SCL", "síncrono, pull-ups, endereçamento"], ["CAN/CAN-FD", "par diferencial", "robusto, multi-mestre, automotivo/industrial"]], "caption": "Escolha de interface"}, {"type": "heading", "level": 3, "text": "EMC, ESD e aterramento"}, {"type": "paragraph", "text": "Compatibilidade eletromagnética inclui emissões e imunidade, conduzidas e radiadas. Planeje retorno de corrente, minimize áreas de laço, separe fontes de ruído, filtre entradas e proteja interfaces. ESD pode causar dano permanente ou falhas transitórias; pré-conformidade não substitui ensaio normativo."}, {"type": "heading", "level": 3, "text": "Segurança e ciclo de vida"}, {"type": "paragraph", "text": "Sistemas conectados exigem inicialização segura, atualização autenticada, proteção de chaves, menor privilégio, logs e recuperação. Em OT/ICS, disponibilidade e segurança física convivem com cibersegurança; defesa em profundidade evita um único ponto de falha."}, {"type": "heading", "level": 3, "text": "Problema guiado: medir sensor com ADC"}, {"type": "paragraph", "text": "Defina uma cadeia: sensor → proteção → filtro anti-alias → buffer ou divisor → ADC → calibração → decisão. Para um sensor de 0 a 3,0 V em ADC de 12 bits com referência de 3,3 V, o passo ideal é 3,3/4095≈0,806 mV. Se o sensor tem resistência alta, calcule o tempo RC de aquisição e use buffer ou aumente o tempo de amostragem."}, {"type": "code", "language": "cpp", "code": "double convertAdcCodeToVoltage(unsigned int adcCode, unsigned int resolutionBits, double referenceVoltage) {\n    if (resolutionBits == 0 || resolutionBits > 31) throw invalid_argument(\"resolutionBits deve estar entre 1 e 31\");\n    unsigned int maximumCode = (1u << resolutionBits) - 1u;\n    if (adcCode > maximumCode) throw out_of_range(\"adcCode excede a resolução\");\n    return referenceVoltage * static_cast<double>(adcCode) / maximumCode;\n}", "lineNumbers": true, "title": "Conversão explícita e parametrizada"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis"}, {"type": "list", "style": "bullet", "items": ["Escolha um capacitor de desacoplamento e explique quais dados do datasheet faltam.", "Calcule a frequência e o tempo ligado de um PWM.", "Compare SPI e I²C para um sensor a 1 m da placa.", "Desenhe o caminho da corrente de retorno de uma carga digital rápida."]}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "controle-dsp-instrumentacao", "number": "6", "title": "Tópicos avançados: controle, DSP, metrologia e confiabilidade", "blocks": [{"type": "paragraph", "text": "Depois de dominar campos, circuitos e dispositivos, pode-se modelar sistemas dinâmicos completos. O objetivo passa a ser medir, estimar, filtrar, controlar e provar que o sistema continua seguro sob incerteza.", "lead": true}, {"type": "heading", "level": 3, "text": "Controle e realimentação"}, {"type": "paragraph", "text": "Em malha fechada, o erro é a diferença entre referência e saída. Um PID contínuo é u=K_p e+K_i∫e dt+K_d de/dt. O termo proporcional reage ao erro, o integral reduz erro estacionário e o derivativo antecipa variação; saturação exige anti-windup."}, {"type": "math", "tex": "C(s)=K_p+K_i/s+K_ds,\\quad \\dot x=Ax+Bu,\\quad y=Cx+Du", "caption": "PID e espaço de estados"}, {"type": "paragraph", "text": "Controlabilidade usa a matriz [B AB … Aⁿ⁻¹B]; observabilidade usa [C; CA; …; CAⁿ⁻¹]. Polos de A determinam modos naturais no modelo contínuo. Realimentação de estados u=−Kx move os polos quando o par é controlável."}, {"type": "heading", "level": 3, "text": "DSP e amostragem"}, {"type": "paragraph", "text": "Amostragem converte tempo contínuo em sequência. Para sinal limitado a B, o modelo ideal exige f_s>2B e filtro anti-alias antes do ADC. A transformada Z descreve sequências e filtros digitais; sua região de convergência faz parte da solução."}, {"type": "math", "tex": "X(z)=\\sum_{n=-\\infty}^{\\infty}x[n]z^{-n},\\quad H(z)=Y(z)/X(z)", "caption": "Transformada Z"}, {"type": "heading", "level": 3, "text": "Instrumentação e incerteza"}, {"type": "paragraph", "text": "O mensurando é a grandeza que se pretende medir. Calibração relaciona indicação a padrão. A incerteza quantifica dispersão; não é simplesmente “erro”. Para Y=f(X₁,…,X_n), a propagação de primeira ordem usa derivadas parciais e covariâncias. Avaliação Tipo A usa repetição; Tipo B usa especificações, certificados e distribuições assumidas."}, {"type": "math", "tex": "u_c^2(y)=\\sum_i\\sum_j c_i c_j u(x_i,x_j),\\quad c_i=\\partial f/\\partial x_i", "caption": "Lei de propagação de incerteza"}, {"type": "heading", "level": 3, "text": "Confiabilidade"}, {"type": "paragraph", "text": "No modelo exponencial com taxa de falha constante λ, R(t)=e^(−λt) e MTTF=1/λ para componentes não reparáveis. MTBF é uma métrica de sistemas reparáveis e não deve ser atribuído automaticamente a um componente não reparável. Weibull usa parâmetro de forma para representar taxa decrescente, constante ou crescente. Declare sempre a parametrização e o mecanismo de falha assumido."}, {"type": "heading", "level": 3, "text": "Problema guiado: filtro digital de média móvel"}, {"type": "paragraph", "text": "Dado x[n], um filtro de média móvel de N amostras é y[n]=(1/N)Σ_{k=0}^{N−1}x[n−k]. Ele reduz ruído não correlacionado aproximadamente por √N, mas introduz atraso e atenua mudanças rápidas. A implementação mantém uma soma corrente para evitar recomputar N valores."}, {"type": "code", "language": "cpp", "code": "class MovingAverageFilter {\nprivate:\n    vector<double> sampleWindow;\n    size_t nextSampleIndex = 0;\n    double runningSum = 0.0;\n\npublic:\n    explicit MovingAverageFilter(size_t windowLength) {\n        if (windowLength == 0) throw invalid_argument(\"windowLength deve ser maior que zero\");\n        sampleWindow.assign(windowLength, 0.0);\n    }\n\n    double processSample(double newSample) {\n        runningSum -= sampleWindow[nextSampleIndex];\n        sampleWindow[nextSampleIndex] = newSample;\n        runningSum += newSample;\n        nextSampleIndex = (nextSampleIndex + 1) % sampleWindow.size();\n        return runningSum / sampleWindow.size();\n    }\n};", "lineNumbers": true, "title": "Filtro com estado explícito"}, {"type": "paragraph", "text": "O custo por amostra é O(1) e a memória é O(N). O filtro não substitui um projeto de banda: avalie frequência de corte, atraso, saturação numérica, inicialização e ruído de quantização."}, {"type": "heading", "level": 3, "text": "Exercícios fáceis"}, {"type": "list", "style": "bullet", "items": ["Calcule a saída de um PID em três instantes com erro fornecido.", "Determine a taxa mínima de amostragem para um sensor limitado a 2 kHz.", "Propague a incerteza de uma resistência calculada por V/I.", "Compare um modelo exponencial e um Weibull para uma taxa de falha crescente."]}, {"type": "heading", "level": 3, "text": "Por que o limite de Nyquist–Shannon não é só uma fórmula"}, {"type": "paragraph", "text": "Para um sinal idealmente limitado a B hertz, a reconstrução sem ambiguidade requer f_s>2B e um filtro anti-alias antes da conversão. Se componentes acima da banda dobram para dentro da banda observada, ocorre aliasing: frequências diferentes passam a produzir a mesma sequência. O limite descreve uma condição de reconstrução ideal; sensores reais também exigem margem, filtro com banda de transição, jitter e análise de ruído."}, {"type": "history", "name": "Harry Nyquist e Claude Shannon", "shortBio": "Harry Nyquist (1889–1976) estudou limites de transmissão e estabilidade; Claude Shannon (1916–2001) formalizou a teoria matemática da comunicação.", "insight": "Nyquist estabeleceu resultados fundamentais sobre taxa e largura de banda, e Shannon provou no fim dos anos 1940 a reconstrução de sinais limitados em banda. O nome composto não é uma regra decorativa: ele resume uma cadeia histórica que liga comunicação analógica, amostragem e reconstrução.", "image": {"src": "images/history-shannon.png", "alt": "Retrato de Claude Shannon"}}, {"type": "history", "name": "Harry Nyquist", "shortBio": "Harry Theodor Nyquist (1889–1976) foi um físico e engenheiro sueco-americano ligado à teoria da comunicação, ao ruído e à estabilidade de sistemas.", "insight": "O trabalho de Nyquist ajudou a quantificar quanta informação uma linha pode transportar e a relacionar banda, taxa e estabilidade. Na amostragem, seu nome aparece junto ao de Shannon porque a reconstrução rigorosa depende de uma hipótese de banda limitada e de uma taxa suficientemente alta.", "image": {"src": "images/history-nyquist.jpg", "alt": "Retrato de Harry Nyquist"}}, {"type": "heading", "level": 3, "text": "PID: sintonia é uma escolha experimental"}, {"type": "paragraph", "text": "A fórmula u=K_p e+K_i∫e dt+K_d de/dt descreve a estrutura, mas não escolhe ganhos. As regras de Ziegler–Nichols usam resposta em malha aberta ou ganho último em malha fechada para obter uma configuração inicial; o resultado pode produzir sobressinal e precisa ser validado contra saturação, ruído, atraso e requisitos de estabilidade."}, {"type": "history", "name": "James Watt", "shortBio": "James Watt (1736–1819) foi um engenheiro e inventor escocês cuja melhoria da máquina a vapor tornou central o problema de regular velocidade e potência.", "insight": "A regulação de máquinas a vapor é um antecedente histórico do controle por realimentação: medir a velocidade e corrigir a entrada transforma uma máquina em sistema dinâmico controlado. O PID moderno é posterior, mas a pergunta de engenharia — como corrigir sem oscilar — já aparece nesse contexto.", "image": {"src": "images/history-watt.jpg", "alt": "Retrato de James Watt"}}, {"type": "history", "name": "Joseph Fourier", "shortBio": "Joseph Fourier (1768–1830) foi um matemático e físico francês que estudou a condução de calor.", "insight": "Decompor um sinal em frequências transforma uma forma de onda difícil de analisar em componentes senoidais mais simples. Essa ideia é útil para filtragem, transmissão e diagnóstico.", "image": {"src": "images/history-fourier.jpg", "alt": "Retrato de Joseph Fourier"}}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "derivacoes-e-metodo", "number": "7", "title": "Como físicos e matemáticos chegam às leis e fórmulas", "blocks": [{"type": "paragraph", "text": "Uma fórmula não nasce isolada. Há quatro origens recorrentes: definições que fixam o significado de uma grandeza; leis empíricas obtidas de medições; teoremas matemáticos aplicados a leis físicas; e aproximações construídas ao desprezar termos pequenos. Esta seção mostra a cadeia de raciocínio para os resultados centrais do livro e aponta a fonte oficial em que a derivação pode ser estudada em detalhes.", "lead": true}, {"type": "heading", "level": 3, "text": "1. Da medição de força à lei de Coulomb"}, {"type": "paragraph", "text": "Coulomb mediu a força entre cargas usando uma balança de torção. O procedimento separava duas variáveis: ao mudar a distância, a força variava como 1/r²; ao mudar a quantidade de carga, a força variava proporcionalmente ao produto das cargas. A direção radial e a superposição transformam esses resultados experimentais em"}, {"type": "math", "tex": "F=k\\frac{|q_1q_2|}{r^2},\\quad \\vec E=\\vec F/q_0", "caption": "Resultado experimental e definição de campo"}, {"type": "paragraph", "text": "A definição E=F/q₀ não é uma segunda lei empírica: ela define uma propriedade do ponto do espaço e permite separar a fonte da carga de teste. O OpenStax apresenta a lei de Coulomb e a construção do campo; o MIT 8.02 mostra como medições e simetria levam à forma vetorial. [1] [2]"}, {"type": "heading", "level": 3, "text": "2. Por que a lei de Gauss segue da forma radial"}, {"type": "paragraph", "text": "Para uma carga puntiforme, o campo tem módulo kQ/r² e é radial. Em uma esfera de raio r, dA aponta radialmente e E é constante na superfície. Portanto, o fluxo é E·4πr²=kQ/r²·4πr²=Q/ε₀. O passo matemático é a escolha de uma superfície adaptada à simetria; a lei de Gauss generaliza esse fluxo para qualquer distribuição e segue da forma integral do teorema da divergência."}, {"type": "math", "tex": "\\oint_S E\\cdot dA=E(4\\pi r^2)=Q/\\varepsilon_0", "caption": "Derivação esférica de Gauss"}, {"type": "paragraph", "text": "O teorema da divergência transforma o fluxo de um campo pela fronteira em uma integral volumétrica de sua divergência. Assim, a forma integral e a forma diferencial ∇·E=ρ/ε₀ são equivalentes sob regularidade suficiente. A cautela é essencial: Gauss sempre vale, mas só fornece E diretamente quando a simetria torna E constante ou orientado de modo simples. [3] [4]"}, {"type": "heading", "level": 3, "text": "3. Potencial a partir do trabalho"}, {"type": "paragraph", "text": "A força eletrostática é conservativa porque o trabalho entre dois pontos não depende do caminho. Define-se energia potencial pela relação dU=−dW_field e potencial por V=U/q. Com F=qE, o trabalho ao longo de um deslocamento é q∫E·dl. Dividindo por q, obtém-se"}, {"type": "math", "tex": "V_B-V_A=-\\int_A^B E\\cdot dl,\\quad E=-\\nabla V", "caption": "Definição energética do potencial"}, {"type": "paragraph", "text": "A igualdade E=−∇V é a forma local da integral quando o campo é suficientemente regular. O MIT 8.02 e o OpenStax deduzem o potencial de uma carga integrando o campo de Coulomb; a liberdade de escolher V(∞)=0 é uma escolha de referência, não uma propriedade observável isolada. [1] [2]"}, {"type": "heading", "level": 3, "text": "4. Capacitor e energia armazenada"}, {"type": "paragraph", "text": "A capacitância C=Q/V é definida pela razão entre carga e diferença de potencial no regime linear. Para adicionar uma quantidade infinitesimal dq, o trabalho externo é dW=V dq=(q/C)dq. Integrando de 0 a Q, obtém-se W=∫₀^Q(q/C)dq=Q²/(2C)=½CV². A densidade u_E=½εE² vem de distribuir essa energia no volume onde existe campo. [5]"}, {"type": "heading", "level": 3, "text": "5. Corrente, Ohm e potência"}, {"type": "paragraph", "text": "I=dQ/dt é definição de corrente. A lei de Ohm macroscópica foi obtida como relação material para condutores em determinada faixa: V=IR. Microscopicamente, um modelo de deriva relaciona velocidade média dos portadores ao campo, gerando J=σE. A potência vem da energia transferida por carga: dW=V dq; dividindo por dt, P=VI. O OpenStax separa explicitamente definição de corrente, relação constitutiva e energia elétrica. [6] [7]"}, {"type": "heading", "level": 3, "text": "6. Kirchhoff a partir de conservação"}, {"type": "paragraph", "text": "KCL não é uma regra decorada: integrar a equação de continuidade ∂ρ/∂t+∇·J=0 em um pequeno volume ao redor de um nó produz “corrente que entra menos corrente que sai” igual à variação de carga acumulada. No modelo de circuito concentrado, a carga acumulada no nó é desprezível, então ΣI=0. KVL resulta da circulação de campo elétrico em regime em que o fluxo magnético variável através da malha pode ser desprezado; a forma geral de Faraday exige incluir esse fluxo. [8]"}, {"type": "heading", "level": 3, "text": "7. RC e a exponencial"}, {"type": "paragraph", "text": "Aplicando KVL ao circuito série, V_s=Ri+v_C. Substitua i=C dv_C/dt: RC dv_C/dt+v_C=V_s. A solução homogênea é Ae^(−t/RC); uma solução particular para fonte constante é V_s. A condição inicial determina A=−V_s para capacitor descarregado. Daí v_C(t)=V_s(1−e^(−t/RC)). A constante τ=RC aparece como escala natural da equação diferencial, não como uma regra empírica arbitrária. [9]"}, {"type": "heading", "level": 3, "text": "8. Maxwell e ondas"}, {"type": "paragraph", "text": "Faraday e Ampère-Maxwell ligam circulação elétrica e magnética. Em região sem fontes, tome o rotacional de uma equação e substitua a outra. Usando a identidade vetorial ∇×(∇×E)=∇(∇·E)−∇²E e ∇·E=0, resulta"}, {"type": "math", "tex": "\\nabla^2E-\\mu_0\\varepsilon_0\\frac{\\partial^2E}{\\partial t^2}=0,\\quad c=1/\\sqrt{\\mu_0\\varepsilon_0}", "caption": "Equação de onda eletromagnética"}, {"type": "paragraph", "text": "A mesma operação vale para B. A velocidade calculada coincide com a luz, levando Maxwell a identificar luz como onda eletromagnética; Hertz confirmou a propagação em experimentos. O MIT, OpenStax e Feynman apresentam essa cadeia: leis locais → equação de onda → velocidade e relações entre E e B. [10] [11] [12]"}, {"type": "heading", "level": 3, "text": "9. Junção PN, transistor e modelos de engenharia"}, {"type": "paragraph", "text": "Em semicondutores, a equação de Poisson liga potencial à densidade de carga. As equações de continuidade ligam variação de portadores à corrente e recombinação. Sob hipóteses de junção abrupta, equilíbrio e aproximação de depleção, integrar Poisson por regiões produz campo triangular, potencial incorporado e largura W. A relação exponencial do diodo vem da estatística de portadores e das condições de contorno de difusão; ela não deve ser confundida com a lei de Ohm."}, {"type": "paragraph", "text": "Para MOSFET de canal longo, a corrente é obtida integrando a carga de inversão ao longo do canal e usando o transporte de deriva. A aproximação de saturação ocorre quando o canal se estrangula no dreno. MIT 6.012, 6.720J e Berkeley EE W230A apresentam as hipóteses e mostram quais efeitos de canal curto quebram o modelo quadrático. [13] [14] [15]"}, {"type": "heading", "level": 3, "text": "10. ADC, Nyquist e ruído"}, {"type": "paragraph", "text": "O teorema de Nyquist–Shannon é matemático: um sinal limitado em banda pode ser reconstruído a partir de amostras acima de duas vezes sua maior frequência, usando interpolação sinc ideal. A exigência prática de filtro anti-alias decorre do fato de que componentes fora da banda dobram para dentro da banda ao amostrar. Quantização arredonda o valor para níveis separados por Δ; se o erro for modelado como uniforme independente, sua variância é Δ²/12. NPTEL, TI e Analog Devices explicam as hipóteses e limites desse modelo. [16] [17] [18]"}, {"type": "heading", "level": 3, "text": "11. Controle e metrologia"}, {"type": "paragraph", "text": "PID é uma combinação escolhida por engenharia: proporcional reage ao erro atual, integral acumula erro e derivativo reage à taxa de mudança. As tendências de overshoot e erro estacionário dependem da planta; não são teoremas universais. Em espaço de estados, controlabilidade e observabilidade são propriedades de posto de matrizes derivadas das equações x_dot=Ax+Bu e y=Cx+Du. Na metrologia, a propagação de incerteza vem da expansão de Taylor de primeira ordem: linearize Y=f(X) ao redor dos valores estimados e calcule a variância quadrática com covariâncias. CTMS, MIT 2.14 e NIST GUM/Technical Note 1297 apresentam essas derivações. [19] [20] [21]"}, {"type": "heading", "level": 3, "text": "Mapa de evidência"}, {"type": "table", "header": ["Resultado", "Origem do raciocínio", "Tipo"], "rows": [["Coulomb", "medição de força + ajuste em r e carga", "lei experimental"], ["E=F/q", "definição operacional", "definição"], ["Gauss", "fluxo radial + teorema da divergência", "lei/teorema"], ["V e energia", "trabalho de força conservativa", "definição + cálculo"], ["RC", "KVL + relação do capacitor + EDO", "dedução matemática"], ["Maxwell → onda", "rotacional + identidade vetorial", "dedução matemática"], ["Diodo/MOSFET", "Poisson, continuidade, transporte e hipóteses de dispositivo", "modelo físico"], ["Nyquist", "reconstrução de sinal limitado em banda", "teorema matemático"], ["Incerteza", "Taylor + variância/covariância", "propagação estatística"]], "caption": "Como ler as fórmulas"}, {"type": "callout", "variant": "tip", "text": "Quando uma fonte apresenta uma equação pronta, procure as etapas: hipóteses, lei de conservação ou definição usada, operação matemática, condição inicial/de contorno e teste de limite. Esse roteiro é mais transferível do que memorizar a expressão final.", "title": "Método de derivação"}, {"type": "heading", "level": 3, "text": "Exercícios fáceis"}, {"type": "list", "style": "bullet", "items": ["Derive a energia do capacitor integrando V(q)dq.", "Partindo de KCL e i=C dv/dt, obtenha a equação diferencial de um RC.", "Use a identidade do duplo rotacional para mostrar a forma de onda de E no vácuo.", "Explique qual hipótese deixa de ser válida quando uma linha de transmissão é tratada como circuito concentrado.", "Diferencie em uma frase definição, lei experimental, teorema e aproximação."]}]}, {"schema": "books.section.v2", "kind": "book-section", "id": "projetos-e-referencias", "number": "8", "title": "Projetos integradores, segurança e referências acadêmicas", "blocks": [{"type": "paragraph", "text": "Os projetos abaixo conectam teoria e prática. Eles são roteiros de estudo, não instruções para trabalhar em tensão de rede ou realizar ensaios perigosos. Use fontes isoladas, limites de corrente e supervisão adequada em laboratório.", "lead": true}, {"type": "heading", "level": 3, "text": "Projeto 1 — fonte e monitor de alimentação"}, {"type": "paragraph", "text": "Modele uma fonte DC com carga variável, meça tensão, corrente e ripple, calcule potência e compare a resposta de um capacitor de entrada. Documente queda de tensão, aquecimento, ESR, proteção contra inversão e corrente de partida."}, {"type": "heading", "level": 3, "text": "Projeto 2 — sensor analógico embarcado"}, {"type": "paragraph", "text": "Construa um caminho de aquisição com sensor, filtro RC, ADC e firmware. Faça calibração com pelo menos cinco pontos, estime incerteza, investigue ruído e teste saturação. Relate resolução efetiva, atraso e faixa válida."}, {"type": "heading", "level": 3, "text": "Projeto 3 — controle de motor de baixa tensão"}, {"type": "paragraph", "text": "Modele uma planta simples, use PWM, meça velocidade, implemente controle proporcional e depois PID. Inclua limite de corrente, desligamento seguro, watchdog, filtro de medição e tratamento de falhas. Não conecte a rede elétrica."}, {"type": "heading", "level": 3, "text": "Projeto 4 — investigação de EMI"}, {"type": "paragraph", "text": "Gere um sinal digital com bordas controladas, observe alimentação e retorno com osciloscópio e compare diferentes layouts de desacoplamento. Use sondas apropriadas e trate o resultado como pré-conformidade, não como certificação."}, {"type": "heading", "level": 3, "text": "Checklist de engenharia"}, {"type": "list", "style": "check", "items": ["Toda grandeza tem unidade e referência?", "O modelo declara linearidade, temperatura, frequência, geometria e condições iniciais?", "A alimentação tem proteção, desacoplamento e retorno de corrente definido?", "A medição tem calibração, faixa, incerteza e saturação documentadas?", "O firmware trata timeout, valores impossíveis, watchdog e atualização segura?", "O projeto foi validado no pior caso, não apenas no cenário nominal?"]}, {"type": "heading", "level": 3, "text": "Exercícios fáceis"}, {"type": "list", "style": "bullet", "items": ["Faça um diagrama de blocos de um sensor até uma decisão de controle.", "Monte um orçamento de potência para um sistema embarcado.", "Liste cinco modos de falha de uma interface I²C e um teste para cada.", "Escreva uma especificação de medição com faixa, resolução, incerteza e frequência de atualização."]}, {"type": "heading", "level": 3, "text": "Referências acadêmicas e institucionais"}, {"type": "paragraph", "text": "As referências foram selecionadas para cobrir física universitária, circuitos, eletromagnetismo, dispositivos, sistemas embarcados, controle, DSP, metrologia, EMC e segurança. Use o texto integral das normas quando um projeto exigir conformidade formal."}, {"type": "list", "style": "bullet", "items": ["[1] MIT OpenCourseWare, 8.02 Electricity and Magnetism — https://ocw.mit.edu/courses/8-02-physics-ii-electricity-and-magnetism-spring-2007/", "[2] OpenStax University Physics Volume 2 — https://openstax.org/books/university-physics-volume-2/", "[3] NIST CODATA, elementary charge and constants — https://physics.nist.gov/cuu/Constants/", "[4] MIT OpenCourseWare, 6.002 Circuits and Electronics — https://ocw.mit.edu/courses/6-002-circuits-and-electronics-spring-2007/", "[5] MIT 18.03 Differential Equations, LRC circuits — https://ocw.mit.edu/courses/18-03sc-differential-equations-fall-2011/", "[6] MIT 6.013 Electromagnetics and Applications — https://ocw.mit.edu/courses/6-013-electromagnetics-and-applications-fall-2005/", "[7] Caltech, The Feynman Lectures on Physics, Vol. II — https://www.feynmanlectures.caltech.edu/II_toc.html", "[8] Cornell ECE 3030 Electromagnetic Fields and Waves — https://ocw.ece.cornell.edu/courses/ece-3030-electromagnetic-fields-and-waves-2/", "[9] UC Berkeley, Integrated-Circuit Devices — https://eecs.berkeley.edu/book/online-specializations-programs/ic/courses/eew230a/", "[10] MIT 6.012 Microelectronic Devices and Circuits — https://ocw.mit.edu/courses/6-012-microelectronic-devices-and-circuits-fall-2009/", "[11] NPTEL Analog Electronic Circuits — https://nptel.ac.in/courses/108106188", "[12] NPTEL VLSI Data Conversion Circuits — https://nptel.ac.in/courses/117106034", "[13] ARM Embedded Systems Education Kits — https://www.arm.com/resources/education/education-kits/rapid-embedded-systems", "[14] Microchip, GPIO and hardware design documentation — https://onlinedocs.microchip.com/", "[15] Analog Devices, ADC and noise resources — https://www.analog.com/en/education/education-library.html", "[16] Texas Instruments, Precision Labs ADCs and signal chain — https://www.ti.com/video/series/precision-labs/ti-precision-labs-analog-to-digital-converters-adcs.html", "[17] NXP UM10204 I²C-bus specification — https://www.nxp.com/docs/en/user-guide/UM10204.pdf", "[18] Stanford EE263 Linear Dynamical Systems — https://ee263.stanford.edu/", "[19] MIT 6.003 Signals and Systems — https://ocw.mit.edu/courses/6-003-signals-and-systems-fall-2011/", "[20] NIST Measurement Uncertainty — https://www.nist.gov/itl/sed/topic-areas/measurement-uncertainty", "[21] IEC Basic EMC Publications — https://www.iec.ch/basic-emc-publications", "[22] NIST SP 800-82 Rev. 3, Operational Technology Security — https://csrc.nist.gov/pubs/sp/800/82/r3/final", "[23] ISA/IEC 62443 Series — https://www.isa.org/standards-and-publications/isa-standards/isa-iec-62443-series-of-standards", "[24] Keysight EMC basics — https://docs.keysight.com/kkbopen/emc-basics-what-are-emc-emi-measurements-601758891.html", "[25] NIST Engineering Statistics Handbook, reliability — https://www.itl.nist.gov/div898/handbook/apr/section3/apr311.htm"]}]}], "imageRights": {"images/history-newton.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3ASir_Isaac_Newton_%281643-1727%29.jpg", "sourceFile": "File:Sir Isaac Newton (1643-1727).jpg", "license": "Public domain", "credit": "Godfrey Kneller", "retrievedAt": "2026-09-24"}, "images/history-gauss.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3ACarl_Friedrich_Gauss.jpg", "sourceFile": "File:Carl Friedrich Gauss.jpg", "license": "Public domain", "credit": "Gottlieb Biermann / After Christian Albrecht Jensen", "retrievedAt": "2026-09-24"}, "images/history-ohm.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3AGeorg-simon-ohm2.jpg", "sourceFile": "File:Georg-simon-ohm2.jpg", "license": "Public domain", "credit": "Wikimedia Commons", "retrievedAt": "2026-09-24"}, "images/history-kirchhoff.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3AGustav_Robert_Kirchhoff._Wood_engraving._Wellcome_V0003228.jpg", "sourceFile": "File:Gustav Robert Kirchhoff. Wood engraving. Wellcome V0003228.jpg", "license": "CC BY 4.0", "credit": "Wikimedia Commons", "retrievedAt": "2026-09-24"}, "images/history-orsted.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3AHans_Christian_%C3%98rsted_daguerreotype.jpg", "sourceFile": "File:Hans Christian Ørsted daguerreotype.jpg", "license": "Public domain", "credit": "Unknown authorUnknown author", "retrievedAt": "2026-09-24"}, "images/history-faraday.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3APortrait_of_Michael_Faraday%2C_by_Drummond_after_Eddis_Wellcome_L0005470.jpg", "sourceFile": "File:Portrait of Michael Faraday, by Drummond after Eddis Wellcome L0005470.jpg", "license": "CC BY 4.0", "credit": "Wikimedia Commons", "retrievedAt": "2026-09-24"}, "images/history-maxwell.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3AJames_Clerk_Maxwell_profile.jpg", "sourceFile": "File:James Clerk Maxwell profile.jpg", "license": "Public domain", "credit": "Unidentified photographer. Smithsonian Institution from United States", "retrievedAt": "2026-09-24"}, "images/history-hertz.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3AHeinrich_Rudolf_Hertz.jpg", "sourceFile": "File:Heinrich Rudolf Hertz.jpg", "license": "Public domain", "credit": "Robert Krewaldt", "retrievedAt": "2026-09-24"}, "images/history-fourier.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3AJoseph_Fourier.jpg", "sourceFile": "File:Joseph Fourier.jpg", "license": "Public domain", "credit": "Amédée Félix Barthélemy Geille / After Julien-Léopold Boilly", "retrievedAt": "2026-09-24"}, "images/history-watt.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3AWatt_James_von_Breda.jpg", "sourceFile": "File:Watt James von Breda.jpg", "license": "Public domain", "credit": "Carl Frederik von Breda", "retrievedAt": "2026-09-24"}, "images/history-coulomb.jpg": {"source": "https://commons.wikimedia.org/wiki/File%3ACoulomb.jpg", "sourceFile": "File:Coulomb.jpg", "license": "Public domain", "credit": "Wikimedia Commons", "retrievedAt": "2026-09-24"}, "images/history-shannon.png": {"source": "https://commons.wikimedia.org/wiki/File:Claude_Shannon_c1930.png", "sourceFile": "File:Claude Shannon c1930.png", "license": "Public domain", "credit": "Wikimedia Commons", "retrievedAt": "2026-09-24"}, "images/history-transistor.jpg": {"source": "https://technoventions.substack.com/", "sourceFile": "Imagem histórica dos inventores do transistor", "license": "Direitos não determinados na fonte de busca; uso educacional interno até substituição por imagem licenciada", "credit": "Technoventions / fonte indicada na busca", "retrievedAt": "2026-09-24"}, "images/history-nyquist.jpg": {"source": "https://kids.kiddle.co/Harry_Nyquist", "sourceFile": "Image:Harry Nyquist.jpg", "license": "Direitos não determinados na fonte de busca; substituir antes de publicação comercial", "credit": "Kiddle / fonte indicada no arquivo", "retrievedAt": "2026-09-24"}}}}};
